// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 회피
// ==========================================

// ── 곡예사 (acrobat) · 무력 ──────────────────
kJob('acrobat', 'S', [
  { at:'S', t:'천장 틀 — 바닥을 사냥하는 것들',
    x:`바닥을 걷는 것은 다 사냥당했다. 앞서 간 이들의 신발이 바닥 여기저기에 한 짝씩 남았다.<br><br>
    천장 밑으로 철골 틀이 지나간다. 손목 두 개 굵기. 먼지가 쌓인 채다. 아무도 그 길을 안 썼다.<br>
    아래에서는 그것들이 코를 바닥에 대고 다닌다. 바닥에 실린 무게를 읽는다. 위는 안 읽는다. 위에는 무게가 실릴 데가 없다고 배웠을 것이다.<br><br>
    곡예사는 손 닿는 것을 다 길로 본다. 저 틀도 길이다.`,
    o:[
      { l:'① 틀에 매달려 손으로 건넌다.', k:'evade', dc:24, wake:1,
        ok:`뛰어서 틀을 잡았다. 다리를 접어 배에 붙였다. 손을 하나씩 옮겼다.<br><br>아래에서 그것들이 지나간다. 이쪽 바로 밑을. 냄새는 위로 뜬다는데 그것들은 바닥만 읽었다. 숨을 아껴 쉬며 끝까지 갔다.<br>내려서서 손바닥을 봤다. 먼지가 쓸린 자국이 틀 위에 한 줄로 남았다.<br><br>바닥이 길이 아니게 된 날, 손이 길을 대신 걸었다. 걷는 데가 발만이 아니라는 걸 몸이 먼저 알았다.`,
        ng:`셋째 이음매가 녹아 있었다. 손을 얹자 틀이 한 뼘 내려앉았다.<br><br>쇳소리가 났다. 아래 것들이 일제히 고개를 들었다. 위를 안 읽는다는 건 이쪽 생각이었다.<br>남은 길이를 반쯤 날다시피 건넜다. 뛰어내리다 어깨가 벽에 갈렸다. 등 뒤에서 틀이 마저 떨어졌다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 무력을 실어 틀에서 틀로 몸을 날린다.', k:'evade', dc:24, cost:{ might:30 },
        ok:`틀이 끊긴 자리가 두 군데다. 손으로는 못 잇는다. 몸을 흔들어 반동을 모았다.<br><br>놓고, 날고, 잡았다. 한 번. 두 번. 아래 것들이 바람 소리에 멈칫했지만 바닥에는 아무것도 안 실렸다.<br>건너편 턱에 발끝으로 내렸다.<br><br>뒤돌아보니 그것들이 끊긴 틀 밑에 모여 있다. 위를 본다. 늦게라도 배우는 것들이다.`,
        ng:`두 번째 도약에서 잡은 틀이 통째로 꺾였다.<br><br>틀을 쥔 채 떨어졌다. 틀이 바닥을 치는 소리가 건물을 울렸다. 그것들이 왔다.<br>구르고, 차고, 턱을 넘었다. 옆구리가 길게 긁혔다. 틀은 두고 왔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } },
      { l:'③ 틀의 이음매부터 하나씩 눈으로 짚는다.', k:'sense', dc:24,
        ok:`건너기 전에 틀을 끝까지 눈으로 쓸었다.<br><br>이음매 아홉 개. 그중 둘이 색이 다르다. 녹은 자국이다. 뭔가의 피가 닿은 자리.<br>그 둘을 피해 길을 그렸다. 손이 갈 순서를 입속으로 한 번 외웠다.<br><br>외운 대로 건넜다. 녹은 이음매 하나는 지나가는 바람에도 떨고 있었다.`,
        ng:`눈으로 짚는 사이에 아래 것 하나가 멈춰 섰다.<br><br>이쪽을 본 게 아니다. 이쪽이 볼 자리를 봤다. 틀 건너편 끝. 거기서 기다리기 시작했다.<br>다른 길로 돌았다. 한참 걸렸고, 도는 내내 그것이 틀 끝을 지키고 있었다.`,
        win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-18 } }
    ] },

  { at:'S', t:'꺼진 바닥 — 떨어지는 법',
    x:`복도 한가운데 바닥이 없다. 녹아서 꺼졌다. 가장자리가 아직 무르다.<br><br>
    아래는 깜깜하다. 깊이는 모른다. 다만 아래에서 숨소리가 올라온다. 하나가 아니다.<br>
    건너편까지 몸 세 개 길이. 뛰기에는 멀고 돌아갈 길은 없다.<br><br>
    곡예사는 걷는 법보다 떨어지는 법을 먼저 배운다. 오늘은 떨어지면 안 되는 날이다.`,
    o:[
      { l:'① 가장자리를 차고 구멍을 뛰어 건넌다.', k:'evade', dc:25,
        doom:{ title:'꺼진 바닥', what:'구멍 아래로 끌려 들어갑니다', dc:19, sec:45,
          text:`가장자리를 찼다. 무른 바닥이 발밑에서 부서졌다. 반밖에 못 날았다.<br><br>구멍 턱을 손으로 잡았다. 버텼다. 아래에서 숨소리가 가까워진다. 발목에 뭔가 감겼다. 축축하고 뜨겁다.<br>당긴다. 손가락이 턱에서 한 마디씩 미끄러진다. 몸이 구멍 아래로 끌려 내려간다.<br><br>동료들이 턱에 엎드려 손을 뻗는다. 아래 숨소리가 웃음처럼 빨라졌다.`,
          dieText:`떨어지는 법은 바닥이 있을 때 쓰는 법이다.<br><br>아래에는 바닥 대신 입이 있었다.<br>구멍 가장자리에 손가락 자국 열 개가 반 마디 깊이로 남았다.` },
        ok:`가장자리 중에 덜 무른 데를 발끝으로 두 번 눌러 봤다. 거기를 찼다.<br><br>낮게 날았다. 건너편 턱에 가슴으로 걸렸다. 다리를 끌어올렸다.<br>아래에서 뭔가 솟았다가 빈 데를 물고 내려갔다. 바람이 발바닥을 스쳤다.<br><br>구르고 일어섰다. 구멍 아래 숨소리가 한동안 성났다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 벽에 붙은 턱을 따라 가장자리를 돈다.', k:'steady', dc:23,
        ok:`벽 쪽에 바닥이 한 뼘 남았다. 벽에 가슴을 붙이고 게걸음으로 돌았다.<br><br>발꿈치 밑에서 부스러기가 떨어졌다. 아래 숨소리가 그때마다 멎었다. 듣고 있다.<br>숨을 부스러기 떨어지는 박자에 맞췄다. 돌 하나, 숨 하나.<br><br>다 돌았다. 마지막 한 걸음에서 남은 바닥이 다 떨어졌다. 뒤에 길은 이제 없다.`,
        ng:`반쯤 돌았을 때 벽이 젖어 있었다. 손이 밀렸다.<br><br>한 발이 구멍 쪽으로 빠졌다. 동료가 옷깃을 잡아챘다. 둘이 벽에 매달려 한참 떨었다.<br>아래에서 뭔가 벽을 타고 올라오는 소리가 났다. 남은 반을 뛰다시피 돌았다. 종아리가 찢어졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S', t:'도약 거리 — 두 번 재는 것',
    x:`그것이 길목에 서 있다. 달려들지 않는다. 재고 있다.<br><br>
    고개를 낮췄다가 든다. 또 낮췄다가 든다. 두 번 잰다. 두 번 재고 나면 몸 일곱 개 길이를 한 번에 온다. 앞서 간 이가 그 길이 안에서 끝났다.<br>
    곡예사도 거리를 잰다. 뛰는 쪽이 아니라 뛰어 들어오는 쪽의 거리를 재 본 적은 없었다.<br><br>
    그것이 고개를 낮췄다. 한 번째다.`,
    o:[
      { l:'① 도약이 끝나는 자리 바로 바깥에 서서 받아넘긴다.', k:'evade', dc:25, wake:1,
        ok:`일곱 길이에서 반 걸음 바깥. 거기 섰다. 그것이 고개를 두 번 들고 날았다.<br><br>발톱이 코앞에서 바닥을 쳤다. 반 걸음이 모자랐다. 그것이 다시 재려고 고개를 낮추는 사이, 그 옆구리를 스치듯 지나 길목을 빠졌다.<br>등 뒤에서 그것이 두 번 재는 소리가 또 났다. 이번에는 빈 데를 쟀다.<br><br>남의 도약을 재서 피한 건 처음이다. 거리는 이쪽 것만이 아니었다. 저쪽 거리도 이쪽 몸에 적혔다.`,
        ng:`반 걸음이 아니라 한 걸음을 물렀어야 했다. 그것은 세 번째도 쟀다.<br><br>더 멀리 날았다. 어깨에 발톱 끝이 걸렸다. 넘어지며 굴렀다. 구른 덕에 몸통은 피했다.<br>길목을 기어 나왔다. 어깨에서 등까지 세 줄이 그였다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 재는 다리를 본다 — 어디에 힘이 실리는지.', k:'gaze', dc:24,
        ok:`고개가 아니라 뒷다리를 봤다. 두 번째 재기에서 뒷다리 힘줄이 당겨진다. 그게 진짜 신호다.<br><br>힘줄이 당겨지는 순간 옆으로 빠졌다. 그것은 이쪽이 서 있던 자리의 반 박자 앞을 물었다. 이쪽 움직임까지 재고 있었다.<br>서로 한 번씩 빗나갔다. 그 사이에 길목을 지났다.<br><br>지나고 나서야 등이 젖은 걸 알았다. 식은땀이 아니라 그것의 숨이었다.`,
        ng:`힘줄을 보느라 거리를 놓쳤다. 어느새 여섯 길이 안이다.<br><br>재지도 않고 왔다. 잴 필요가 없는 거리였다. 몸을 던져 피했다. 바닥에 어깨부터 떨어졌다.<br>두 번 구르고 틈새에 몸을 박았다. 그것이 틈 앞에서 오래 고개를 낮췄다 들었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
    ] },

  { at:'S', t:'녹는 디딤 — 떨어지는 핏방울',
    x:`외길 발판 위로 뭔가의 피가 떨어진다. 천장 어디서 다친 것이 끼어 있다.<br><br>
    피가 닿은 자리마다 발판이 운다. 쇠가 녹으며 실 같은 연기가 선다. 구멍이 하나씩 늘어난다.<br>
    떨어지는 데는 세 군데. 박자는 제각각이다. 발판은 앞으로 얼마 못 버틴다.<br><br>
    곡예사 눈에 구멍은 막힌 길이 아니다. 디딜 데가 줄어든 길이다.`,
    o:[
      { l:'① 핏방울 사이로 박자를 맞춰 건넌다.', k:'evade', dc:24,
        ok:`세 군데 박자를 따로 셌다. 하나는 길고 둘은 짧다. 셋이 겹치는 빈 박자가 있다.<br><br>그 박자에 한 구간씩 갔다. 멈출 때는 구멍과 구멍 사이 쇠가 성한 데에 발끝으로 섰다.<br>마지막 구간에서 박자 하나가 빨라졌다. 다친 것이 더 다쳤나 보다. 반 박자 일찍 뛰었다.<br><br>건너고 나서 발판을 봤다. 이쪽이 디딘 자리만 멀쩡하고 나머지는 그물처럼 뚫렸다.`,
        ng:`겹치는 박자를 기다리는 사이 발밑이 먼저 녹았다.<br><br>디딘 자리가 꺼지며 핏방울 하나가 어깨에 닿았다. 천이 타고 살이 탔다.<br>남은 길을 박자 없이 뛰었다. 운이 반이었다. 어깨의 구멍에서 연기가 한참 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-34, mind:-16 } },
      { l:'② 무력을 실어 성한 판을 뜯어 머리 위에 인다.', k:'break', dc:24, cost:{ might:32 },
        ok:`난간 덮개를 발로 밟아 뜯었다. 팔 두 개 너비 쇠판이다. 머리 위에 이고 걸었다.<br><br>핏방울이 판을 때린다. 판이 녹는 소리가 정수리 바로 위에서 난다. 걸음을 안 멈췄다.<br>건너편에서 판을 던져 버렸다. 판에는 구멍이 아홉 개 나 있었다.<br><br>아홉 방울이면 사람 하나가 아홉 번 끝나는 수다. 판을 한 번 더 돌아봤다.`,
        ng:`판을 뜯는 데 너무 오래 걸렸다. 그 사이 발판이 더 삭았다.<br><br>이고 걷는데 발밑이 꺼졌다. 무릎까지 빠졌다. 판을 버리고 기었다. 핏방울 하나가 종아리를 스쳤다.<br>건너긴 건넜다. 종아리의 탄 자국이 손가락 두 개 길이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-36, mind:-14 } }
    ] },

  { at:'S', t:'틈 — 몸 하나 너비',
    x:`무너진 더미 사이로 틈이 하나 났다. 어깨를 접으면 들어가는 너비다.<br><br>
    틈 안쪽은 깜깜하다. 바람이 틈에서 나온다. 미지근하다. 안쪽 어딘가 숨 쉬는 게 있다는 뜻이다.<br>
    틈 바깥 벽에는 긁힌 자국이 있다. 들어간 자국이 아니라 끌려 들어가며 버틴 자국이다. 열 손가락.<br><br>
    돌아가는 길은 그것들이 지키고 있다. 길은 이 틈뿐이다.`,
    o:[
      { l:'① 몸을 접어 틈을 빠져나간다.', k:'evade', dc:25,
        doom:{ title:'틈', what:'틈 안쪽으로 끌려 들어갑니다', dc:19, sec:40,
          text:`어깨를 접고 머리부터 넣었다. 반쯤 들어갔을 때 안쪽 미지근한 바람이 멎었다.<br><br>숨을 참은 것이다. 이쪽 말고 안쪽 것이.<br>손목이 잡혔다. 사람 손이 아니다. 마디가 너무 많다. 틈 안쪽으로 당긴다. 어깨가 끼인 채 몸이 한 뼘씩 들어간다.<br><br>바깥에 남은 발이 허공을 찬다. 동료들이 발목을 잡았다. 틈이 좁아 둘이 같이 당길 수가 없다.`,
          dieText:`틈은 몸 하나 너비였다.<br><br>둘이 들어가기엔 좁았는데, 안쪽 것은 애초에 나올 생각이 없었다.<br>틈 바깥 벽에 긁힌 자국이 열 줄 늘었다. 먼저 것보다 깊다.` },
        ok:`발부터 넣었다. 머리를 마지막에 넣었다. 안쪽을 등지지 않으려고.<br><br>반쯤에서 안쪽 바람이 멎었다. 기다리는 숨이다. 몸을 비틀어 틈의 꺾인 데로 먼저 빠졌다. 손 하나가 방금 자리를 긁었다.<br>꺾인 틈은 더 좁았다. 더 좁아서 그것은 못 따라왔다.<br><br>빠져나와 숨을 몰아쉬었다. 틈 안에서 마디 많은 손가락이 바깥쪽으로 하나 나와 있었다. 이쪽을 가리키듯.`,
        win:{ exp:24, dream:3 } },
      { l:'② 허리에 줄을 묶고 동료에게 끝을 맡긴다.', k:'bond', dc:23,
        ok:`줄을 허리에 감고 매듭을 두 번 지었다. 당길수록 조이는 매듭. 끝은 동료 손에.<br><br>신호를 정했다. 한 번 당기면 멈춤, 두 번이면 빼 달라. 틈에 들어갔다.<br>중간에 손목이 잡혔다. 두 번 당겼다. 동료 셋이 줄을 당겼다. 이쪽은 발로 벽을 찼다. 손이 떨어져 나갔다.<br><br>빠져나와 매듭을 풀었다. 허리에 줄 자국이 깊다. 목숨 자국이다.`,
        ng:`줄이 틈의 꺾인 데에 걸렸다. 신호가 안 갔다.<br><br>당겨도 멈춤인지 빼 달라는 건지 저쪽이 모른다. 손목 잡힌 채로 혼자 버텼다. 소리를 질렀다. 틈이 소리를 먹었다.<br>동료가 줄을 그냥 다 당겼다. 벽에 쓸리며 끌려 나왔다. 옷이 반은 틈에 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-20 } }
    ] },

  { at:'S', t:'매달린 사체 — 추 하나',
    x:`끊긴 다리 위에 줄이 하나 늘어졌다. 줄 끝에 뭔가의 사체가 매달렸다.<br><br>
    팽팽하다. 추 노릇은 된다. 저걸 잡고 흔들면 건너편까지 몸이 간다.<br>
    다만 사체가 너무 멀쩡하다. 상한 냄새가 없다. 여기 것들이 멀쩡한 고기를 남겨 둘 리가 없다.<br><br>
    남겨 둔 게 아니라면, 걸어 둔 것이다.`,
    o:[
      { l:'① 줄을 잡고 한 번에 건너뛴다.', k:'evade', dc:24, wake:1,
        ok:`도움닫기 없이 줄을 잡자마자 몸무게를 다 실었다. 머뭇거리면 미끼를 문 것이 된다.<br><br>줄이 호를 그렸다. 가장 멀리 간 꼭대기에서 손을 놓았다. 건너편 바닥에 굴러 내렸다.<br>등 뒤에서 아래 어둠이 솟았다. 사체째 줄을 삼키고 내려갔다. 줄이 끊기는 소리.<br><br>미끼는 무는 게 아니라 쓰는 것이다. 한 번 스치고 버리면 그건 이쪽 발판이지 저쪽 미끼가 아니다.`,
        ng:`줄을 잡는 순간 사체가 눈을 떴다.<br><br>사체가 아니었다. 자는 것이었다. 손에 힘이 빠지며 호가 짧아졌다. 건너편 턱에 정강이를 박고 걸렸다.<br>기어오르는 등 뒤에서 그것이 줄을 타고 거꾸로 내려오는 소리가 났다. 돌아보지 않고 뛰었다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-16 } },
      { l:'② 다리 골조 밑면을 타고 천천히 돈다.', k:'steady', dc:23,
        ok:`끊긴 다리의 밑면 골조가 반쯤 남았다. 거꾸로 매달려 손발 네 점으로 갔다.<br><br>팔이 타는 것 같아도 박자를 안 바꿨다. 빠른 손은 미끄러진 손이다.<br>건너편 기둥을 안고 올라왔다. 손바닥이 녹 가루로 벌겋다.<br><br>매달린 사체 쪽을 봤다. 사체가 고개만 돌려 이쪽을 보고 있었다. 눈이 마주쳤는데 아무 일도 없었다. 그게 제일 오래 남았다.`,
        ng:`골조 중간이 삭아 있었다. 쥔 채로 부러졌다.<br><br>한 손으로 매달렸다. 부러진 쇠가 아래로 떨어져 한참 만에 물소리를 냈다. 아래가 물이라는 걸 그때 알았다. 물이 움직이기 시작했다.<br>남은 거리를 반쯤 정신없이 건넜다. 팔이 한동안 안 올라갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'S', t:'높이 — 소리 없는 낙법',
    x:`내려가는 길이 끊겼다. 아래층 바닥까지 몸 두 개 높이. 뛰어내리면 되는 높이다.<br><br>
    다만 아래는 그것들의 길목이다. 귀로 사냥하는 것들. 발소리 하나에 벽 셋 너머에서 온다.<br>
    곡예사는 떨어질 때 소리를 바닥에 안 준다. 무릎과 발목과 등이 나눠 갖는다.<br><br>
    문제는 짐이다. 짐은 낙법을 모른다.`,
    o:[
      { l:'① 소리를 몸으로 다 받으며 내린다.', k:'evade', dc:24, wake:1,
        ok:`짐을 가슴에 묶고 가장자리에 매달렸다가 손을 놓았다.<br><br>발끝, 무릎, 허리, 등. 닿는 순서대로 소리를 나눠 받았다. 바닥에는 숨소리만 한 소리만 남겼다.<br>길목 어둠이 조용하다. 동료들을 한 사람씩 같은 자리로 받았다. 받는 몸이 반, 바닥이 반.<br><br>마지막 사람까지 받고 나서 알았다. 소리는 참는 게 아니라 나눠 갖는 것이다. 몸 마디마다 소리를 한 몫씩 맡기는 법을 오늘 배웠다.`,
        ng:`이쪽은 소리 없이 내렸다. 짐이 문제였다.<br><br>가슴에 묶은 짐 속에서 쇠붙이 두 개가 부딪쳤다. 종만 한 소리였다.<br>길목 끝에서 그것이 왔다. 다들 벽 틈에 몸을 박고 그것이 소리 난 자리를 파헤치는 걸 봤다. 바닥이 손가락 깊이로 파였다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 } },
      { l:'② 그것들이 소리를 내는 때를 기다려 내린다.', k:'hide', dc:24,
        ok:`길목 어둠 속에서 그것들끼리 부딪는 때가 있다. 그르렁대는 소리가 벽을 긁는 때.<br><br>그 소리에 맞춰 하나씩 내렸다. 저쪽 소리가 이쪽 소리를 덮었다.<br>다 내려와서 벽에 붙어 지나갔다.<br><br>그르렁 소리가 뚝 멎은 건 마지막 사람 발이 바닥에 닿고 세 숨 뒤였다. 세 숨 차이로 산 셈이다.`,
        ng:`소리를 기다리는데 그것들이 한참 조용했다.<br><br>기다리다 못해 내린 순간, 저쪽도 같은 생각이었는지 움직이기 시작했다. 소리와 소리가 어긋났다.<br>이쪽 발소리 반쪽이 바닥에 남았다. 길목 어둠이 멎었다. 서로 숨을 죽인 채 한나절 같은 시간이 갔다. 먼저 움직인 건 저쪽이었다. 다른 쪽으로 갔다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S', t:'지나가는 등 — 건너는 다리',
    x:`두 턱 사이가 끊겼다. 아래로 큰 것이 지나다닌다. 등이 이쪽 턱 높이까지 올라온다.<br><br>
    등이 지나가는 동안만 두 턱이 이어진다. 걸음 네 개 길이의 다리. 숨 쉴 때마다 오르내리는 다리.<br>
    그 등에는 다른 작은 것들이 붙어 산다. 이가 살듯이. 작은 것들이 이쪽을 보면 끝이다.<br><br>
    큰 것이 또 온다. 등이 턱에 닿을 만큼 차오른다.`,
    o:[
      { l:'① 등이 지나는 동안 네 걸음에 건넌다.', k:'evade', dc:26,
        doom:{ title:'지나가는 등', what:'큰 것의 등에 실려 갑니다', dc:20, sec:40,
          text:`등에 올라 두 걸음을 갔다. 등가죽이 숨에 맞춰 솟았다. 세 걸음째가 빗나갔다.<br><br>발이 가죽 주름에 빠졌다. 그 사이 등이 턱을 지나쳤다. 내릴 데가 없어졌다.<br>큰 것이 걸음을 안 멈춘다. 이쪽을 모른다. 몰라서 더 큰일이다. 등에 붙은 작은 것들이 하나둘 이쪽으로 고개를 돌린다.<br><br>등 위에 엎드린 채 실려 간다. 동료들이 턱을 따라 달리며 손을 뻗는다. 턱이 곧 끝난다.`,
          dieText:`다리는 네 걸음이었다.<br><br>세 걸음까지는 다리였고 네 걸음째부터는 짐승이었다.<br>큰 것은 어디론가 계속 갔다. 등에 탄 것이 하나 는 줄도 모르고.`,
        },
        ok:`숨을 봤다. 들숨에 등이 솟고 날숨에 꺼진다. 들숨 꼭대기에 올라탔다.<br><br>네 걸음을 날숨 한 번 안에 다 썼다. 등이 꺼지기 전에 건너편 턱을 잡았다.<br>몸을 끌어올리는데 등에 붙은 작은 것 하나와 눈이 마주쳤다. 그것이 입을 벌렸다.<br><br>큰 것이 지나가 버렸다. 작은 것의 소리는 큰 것의 발소리에 묻혔다. 운이었다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 큰 것이 오가는 틈새 박자를 먼저 샌다.', k:'sense', dc:24,
        ok:`턱에 엎드려 세 번을 보냈다. 올 때마다 셌다.<br><br>숨 마흔에 한 번 온다. 등이 턱 높이에 머무는 건 숨 다섯. 네 걸음에 숨 다섯이면 넉넉하지 않다. 빠듯하다.<br>그걸 알고 건너는 것과 모르고 건너는 건 다르다. 다음 번 등에서 다들 숨 다섯 안에 건넜다.<br><br>마지막 사람이 건넌 직후 큰 것이 처음으로 멈춰 섰다. 코로 턱 밑을 한 번 훑고 갔다. 다섯이 아니라 여섯이었으면 들켰다.`,
        ng:`세는 동안 등에 붙은 작은 것들이 이쪽을 먼저 셌다.<br><br>네 번째로 등이 왔을 때 작은 것들이 턱 쪽 가장자리에 줄지어 앉아 있었다. 기다리고 있었다.<br>건너기를 접고 물러났다. 물러나는 등 뒤로 작은 것 하나가 턱에 뛰어내려 쫓아왔다. 뿌리치는 데 셋이 달라붙었다. 팔뚝을 물렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'S', t:'굴뚝 틈 — 아래서 오르는 것',
    x:`수직 통로다. 두 벽 사이가 어깨너비. 등과 발로 버티며 오르면 된다.<br><br>
    반쯤 올랐을 때 아래가 소리를 냈다. 뭔가 들어왔다. 그것도 오른다. 벽을 긁으며. 이쪽보다 빠르다.<br>
    위까지는 몸 열 개 높이. 긁는 소리는 몸 여섯 개 아래. 셈이 안 맞는다.<br><br>
    곡예사는 오르다 막히면 버틴다. 버티는 것도 길이다.`,
    o:[
      { l:'① 무력을 실어 단숨에 치고 오른다.', k:'evade', dc:25, cost:{ might:34 },
        ok:`등과 발에 힘을 다 실었다. 반동으로 한 번에 두 몸 높이씩 올랐다.<br><br>긁는 소리가 발꿈치 바로 밑까지 왔다. 마지막 반동에서 위 테두리를 잡았다. 몸을 넘겼다.<br>통로에서 손 하나가 테두리를 잡았다. 마디가 많은 손. 다 같이 밟았다. 손이 들어갔다.<br><br>테두리에 무거운 것을 끌어다 얹었다. 밤새 그 밑에서 긁는 소리가 났다.`,
        ng:`세 번째 반동에서 발이 미끄러졌다. 벽이 안쪽으로 갈수록 미끈했다.<br><br>두 몸 높이를 도로 미끄러졌다. 긁는 소리와 거의 닿았다. 숨이 목덜미에 닿았다.<br>남은 높이를 어떻게 올랐는지 기억이 안 난다. 등가죽이 벽에 쓸려 다 벗겨졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-34, mind:-16 } },
      { l:'② 벽이 되어 버틴다 — 그것이 지나가게.', k:'steady', dc:25, wake:1,
        ok:`오르기를 멈췄다. 틈의 제일 좁은 데에 몸을 끼웠다. 등은 벽, 무릎도 벽. 숨을 벽처럼 쉬었다.<br><br>그것이 올라왔다. 이쪽 몸을 디뎠다. 벽을 디디듯. 발톱이 허벅지를 밟고, 어깨를 밟고, 위로 갔다.<br>위 테두리를 넘어 가 버렸다. 이쪽을 끝까지 벽으로 알았다.<br><br>몸이 벽이 되는 법을 배웠다. 숨과 떨림을 돌처럼 만들면, 눈이 아니라 발로 보는 것들은 속는다. 허벅지에 발톱 자국이 벽 금 가듯 남았다.`,
        ng:`버티는데 다리가 먼저 떨렸다. 벽은 떨지 않는다.<br><br>그것이 이쪽 무릎에서 멈췄다. 벽이 아닌 걸 알았다. 고개가 돌아오기 전에 위로 치고 올랐다.<br>쫓겼다. 테두리를 넘으며 발목이 잡혔다 풀렸다. 신발 한 짝이 통로에 남았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-20 } }
    ] },

  { at:'S', t:'꼬리 — 낮게 오는 호',
    x:`어둠 속에서 꼬리가 온다. 무릎 높이. 벽에서 벽까지 한 번에 쓴다.<br><br>
    박자가 있다. 쓸고, 돌아오고, 쉰다. 쉬는 길이가 숨 둘. 그 사이에 한 구간씩 가면 된다.<br>
    몸통은 안 보인다. 꼬리만 이 방을 담당하는 것처럼 온다.<br><br>
    바닥에는 먼저 쓸려 간 것들의 신발이 구석에 모여 있다. 누가 모은 것처럼 가지런히.`,
    o:[
      { l:'① 박자에 맞춰 뛰어넘으며 나아간다.', k:'evade', dc:24,
        ok:`쓸고—돌아오고—쉼. 쉼에 두 걸음, 쓸 때 한 번 뛰었다.<br><br>꼬리가 발바닥 밑으로 지나갔다. 바람이 복사뼈를 스쳤다. 다시 두 걸음, 다시 한 번.<br>방을 반 넘었을 때 박자가 반으로 접혔다. 쉼이 없어졌다. 마지막 구간은 박자 없이, 꼬리 위를 구르며 건넜다.<br><br>문을 넘자 꼬리가 문턱을 때렸다. 문설주가 부러졌다. 무릎 높이가 아니었으면 끝이었다.`,
        ng:`세 번째 뜀에서 꼬리가 높이를 바꿨다. 무릎이 아니라 허리.<br><br>배로 맞았다. 벽까지 날아가 떨어졌다. 숨이 한참 안 돌아왔다.<br>기다시피 문을 넘었다. 갈비 어디가 어긋난 것 같다. 꼬리는 박자대로 계속 쓸고 있었다. 아무 일 없었다는 듯.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-36, mind:-14 } },
      { l:'② 꼬리의 박자가 어디서 접히는지 본다.', k:'gaze', dc:24,
        ok:`박자를 세지 않고 꼬리 끝을 봤다. 꼬리 끝이 방바닥을 읽고 있었다. 먼지가 흔들린 데를.<br><br>박자는 정해진 게 아니었다. 먼지가 흔들리면 접힌다. 걸음이 아니라 걸음이 일으키는 바람이 문제였다.<br>발을 끌 듯 낮게 걸었다. 먼지가 안 일게. 꼬리는 끝까지 제 박자대로만 쓸었다.<br><br>문을 넘고 나서 동료들에게 알렸다. 바닥 말고 공기를 조심하라고. 다들 처음 듣는 말이라는 얼굴이었다.`,
        ng:`꼬리 끝을 보다가 꼬리 끝과 눈이 마주쳤다. 끝에 눈이 있었다.<br><br>박자가 그 자리에서 끝났다. 꼬리가 이쪽으로만 왔다. 뛰고 구르고 벽을 찼다.<br>문을 넘을 때 등을 한 번 쓸렸다. 옷이 찢어지고 등에 긴 멍이 남았다. 눈 달린 것을 보는 일은 언제나 값을 치른다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
    ] },

  { at:'S', t:'거꾸로 — 피가 쏠리는 시간',
    x:`들보에 무릎을 걸고 거꾸로 매달렸다. 그래야 했다. 그것들이 방에 들어왔으니까.<br><br>
    그것들은 바닥과 벽을 읽는다. 천장은 안 읽는다. 대신 이쪽 피가 머리로 쏠린다. 귀에서 북소리가 난다.<br>
    버티는 시간과 그것들이 나가는 시간. 어느 쪽이 먼저인지의 문제다.<br><br>
    하나가 바로 밑에 앉았다. 자리를 잡는다. 오래 있을 자세다.`,
    o:[
      { l:'① 피가 버티는 동안 숨으로 시간을 늘린다.', k:'steady', dc:24, wake:1,
        ok:`숨을 길게 바꿨다. 들숨 넷, 날숨 여섯. 북소리가 조금 멀어진다.<br><br>밑의 것이 털을 고른다. 다른 것들이 하나씩 나간다. 마지막 것이 일어나기까지 숨을 몇 번 쉬었는지 모른다.<br>나가고 나서 들보 위로 몸을 접어 올렸다. 눈앞이 하얬다가 돌아왔다.<br><br>거꾸로 매달린 시간에도 바닥이 있다는 걸 배웠다. 숨이 그 바닥이다. 숨을 디디면 피 쏠리는 시간도 길이 된다.`,
        ng:`북소리가 숨을 이겼다. 눈앞에 점이 번지기 시작했다.<br><br>손끝이 저리다 못해 감각이 없다. 몸이 흔들렸다. 들보가 울었다.<br>밑의 것이 고개를 들기 전에 옆 들보로 몸을 던졌다. 소리가 났지만 어두워서 살았다. 코피가 거꾸로 이마를 타고 흘렀다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 그것들 머리 위로 들보를 타고 빠져나간다.', k:'evade', dc:25,
        ok:`매달린 채 손을 뻗어 다음 들보를 잡았다. 몸을 옮겼다. 거꾸로 건너는 길.<br><br>그것들 정수리 위를 지나갔다. 하나가 귀를 세웠다. 멈췄다. 귀가 눕기를 기다려 또 갔다.<br>문 위 들보에서 복도로 몸을 넘겼다.<br><br>마지막에 봤다. 그것들이 모여 앉은 한가운데 바닥에, 이쪽 땀 한 방울이 떨어져 있었다. 하나가 그걸 핥았다. 천장을 올려다봤다. 늦은 뒤였다.`,
        ng:`세 번째 들보가 손안에서 돌았다. 헛돈 만큼 몸이 흔들렸다.<br><br>먼지가 떨어졌다. 그것들 등 위로. 일제히 일어났다. 천장을 읽기 시작했다.<br>들보에서 들보로 도망치는 길이 길었다. 창틀로 빠질 때 발뒤꿈치를 물렸다 뺐다. 신발 뒤축이 이빨 자국째 없어졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'S1', t:'통풍구 — 치수가 맞는 것',
    x:`표본실 복도가 막혔다. 남은 길은 통풍구다. 덮개를 떼니 어깨 하나 너비.<br><br>
    곡예사는 제 몸 치수를 안다. 어깨 접으면 들어간다. 무릎은 끌면 된다.<br>
    통풍구 안쪽 벽에 긁힌 자국이 줄지어 있다. 이쪽과 같은 방향. 그리고 더 깊은 자국이 그 위를 거슬러 간다. 반대 방향.<br><br>
    이 관을 쓰는 건 이쪽만이 아니다. 치수가 맞는 게 하나 더 있다.`,
    o:[
      { l:'① 소리 없이 기어 환기실까지 간다.', k:'evade', dc:25,
        doom:{ title:'통풍구', what:'통풍구 안쪽으로 끌려 들어갑니다', dc:19, sec:40,
          text:`팔꿈치와 무릎으로 쇠판을 눌러 가며 갔다. 소리는 안 났다. 그게 문제였다.<br><br>저쪽도 소리를 안 냈다. 갈림 관에서 미지근한 숨이 얼굴에 닿았다. 어둠 속에 어둠보다 짙은 것이 접혀 있었다.<br>발목이 잡혔다. 관이 좁아 돌아볼 수도 없다. 몸이 갈림 관 쪽으로 끌려 들어간다. 쇠판에 손톱이 긁히는 소리만 관을 타고 멀리 갔다.<br><br>동료들이 바깥에서 관을 두드리며 따라온다. 소리가 점점 멀어진다.`,
          dieText:`치수가 맞는 것이 하나 더 있었다.<br><br>그쪽이 이 관을 먼저 썼고, 더 오래 썼다.<br>환기실 덮개는 그날 밤 안쪽에서 한 번 덜컹였다. 열리지는 않았다.` },
        ok:`기다가 멈추기를 반복했다. 이쪽 소리를 지우는 게 아니라 저쪽 소리를 들으려고.<br><br>갈림 관 앞에서 미지근한 바람이 왔다. 숨이다. 멈췄다. 숨이 멀어질 때까지 셌다. 백스물.<br>갈림 관을 지나 환기실 덮개를 발로 밀어 열었다.<br><br>나와서 덮개를 도로 끼웠다. 끼우는 손끝에, 관 안쪽에서 미지근한 바람이 한 번 닿았다. 배웅처럼.`,
        win:{ exp:24, dream:3 } },
      { l:'② 관 이음매마다 귀를 대고 저쪽 위치부터 잡는다.', k:'sense', dc:24,
        ok:`들어가기 전에 복도 쪽 관 이음매마다 귀를 댔다. 쇠는 소리를 멀리 나른다.<br><br>세 번째 이음매에서 긁는 소리가 잡혔다. 느리고 무겁다. 북쪽 관이다. 남쪽 관은 비었다.<br>남쪽으로 돌아 기었다. 길은 멀어도 숨은 편했다.<br><br>환기실에 나와서 북쪽 관 덮개를 봤다. 안쪽에서 긁어 놓은 자국이 덮개 틈으로 보였다. 거의 뚫려 있었다.`,
        ng:`귀를 댄 이음매가 안쪽에서 두들겨졌다. 똑, 똑.<br><br>이쪽이 듣는 걸 저쪽이 알았다. 소리로 사냥하는 건 저쪽이 위였다. 두들김이 관을 타고 이쪽 위치를 재고 있었다.<br>관을 포기하고 막힌 복도의 잔해를 반나절 걷어 냈다. 손톱 두 개가 뒤집혔다. 관 안에서는 밤새 똑, 똑, 소리가 따라왔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'S1', t:'표본 선반 — 병 위의 길',
    x:`표본 보관실. 바닥이 없다. 산성 피가 바닥을 먹어 아래층까지 뚫렸다.<br><br>
    남은 길은 선반 위다. 벽을 따라 선반이 가슴 높이로 이어진다. 그 위에 표본 병이 줄지어 섰다. 금 간 것, 빈 것, 아직 안이 움직이는 것.<br>
    선반 폭은 한 뼘 반. 병을 쓰러뜨리면 아래로 떨어진다. 아래 어둠은 떨어지는 걸 다 받아먹는다.<br><br>
    곡예사한테 한 뼘 반은 넓은 길이다. 병만 아니면.`,
    o:[
      { l:'① 병 사이사이 빈 데만 디디며 선반을 탄다.', k:'evade', dc:24,
        ok:`병과 병 사이, 발 반쪽 들어가는 틈을 골라 디뎠다. 발끝으로만.<br><br>안이 움직이는 병 앞에서는 디딤을 더 멀리 끊었다. 병 속 것이 유리에 입을 대고 이쪽 발을 따라왔다.<br>모퉁이에서 선반이 한 번 기울었다. 무게를 반대발로 넘기고 지나갔다. 병 하나가 흔들리다 멎었다.<br><br>끝까지 하나도 안 깼다. 보관실을 나올 때 등 뒤에서 병들이 일제히 달그락였다. 박수처럼.`,
        ng:`빈 병인 줄 알고 스친 병이 빈 게 아니었다. 안의 것이 유리를 쳤다.<br><br>병이 선반에서 굴렀다. 받으려다 이쪽 무게가 쏠렸다. 병은 아래로, 이쪽은 선반에 매달렸다.<br>아래에서 유리 깨지는 소리, 그리고 그걸 받아먹는 소리. 기어오르는 팔이 후들거렸다. 남은 길 내내 병 속 것들이 이쪽만 봤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 병을 한 칸씩 옮겨 길부터 비운다.', k:'steady', dc:23,
        ok:`서두르지 않았다. 병을 두 손으로 들어 뒤 칸으로 옮겼다. 한 병, 한 걸음.<br><br>안이 움직이는 병은 눕히지 않고 세워서 옮겼다. 눕히면 깨어난다는 걸 금 간 병 하나가 가르쳐 줬다.<br>빈 길로 동료들이 다 건넜다.<br><br>마지막 병을 제자리에 돌려놨다. 왜 그랬는지는 모른다. 그 병이 제일 조용했다.`,
        ng:`여섯 번째 병이 손안에서 금이 갔다. 안의 것이 유리를 민 것이다.<br><br>놓지도 못하고 든 채로 굳었다. 금이 거미줄처럼 번졌다. 선반 끝에 겨우 내려놓고 물러났다.<br>병이 터졌다. 안의 것은 선반 밑으로 떨어져 사라졌다. 어디로 갔는지 모른다는 게 제일 나쁘다. 손바닥이 유리에 그였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'S1', t:'격벽 — 닫히는 박자',
    x:`격벽 문 두 짝이 번갈아 여닫힌다. 고장 난 뒤로 제멋대로다.<br><br>
    첫 문이 열리고 숨 셋에 닫힌다. 둘째 문은 첫 문이 닫혀야 연다. 두 문 사이 공간은 몸 두 개 길이.<br>
    문짝은 뼈째 자른다. 문틀에 끼인 채 말라붙은 것이 그 증거다. 사람 것은 아니다. 아직은.<br><br>
    곡예사는 박자 있는 문을 무서워하지 않는다. 박자 없는 문을 무서워한다. 이 문은 박자가 반쯤 남았다.`,
    o:[
      { l:'① 두 문을 한 호흡에 이어 빠진다.', k:'evade', dc:25, wake:1,
        ok:`첫 문이 열리는 순간 굴러 들어갔다. 사이 공간에서 멈추지 않았다. 멈추면 다음 박자를 머리로 세게 된다.<br><br>몸이 먼저 셌다. 둘째 문이 열리는 바람을 얼굴로 받으며 그대로 빠졌다. 등 뒤에서 두 문이 거의 동시에 닫혔다.<br>옷자락 끝이 잘려 문틈에 남았다.<br><br>박자는 머리로 세면 늦는다. 몸에 새겨서 몸이 세게 해야 한다. 오늘 그 옮겨 적는 법을 알았다. 숨 한 번이 종이였다.`,
        ng:`사이 공간에서 반 박자 멈췄다. 머리가 세기 시작한 탓이다.<br><br>둘째 문이 반만 열리고 닫히기 시작했다. 몸을 던졌다. 문짝이 등을 쓸고 닫혔다.<br>빠지긴 했다. 등가죽이 불에 덴 것처럼 아프다. 문틈에 옷이 아니라 살갗이 남았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 무력을 실어 첫 문을 어깨로 받아 버틴다.', k:'steady', dc:24, cost:{ might:30 },
        ok:`첫 문이 닫히는 길에 어깨를 넣었다. 무력을 뼈에 둘렀다.<br><br>문이 어깨를 밀었다. 밀리면서도 닫히지는 못했다. 그 틈으로 동료들이 하나씩 빠졌다.<br>마지막에 어깨를 빼며 굴렀다. 문이 등 뒤에서 쾅 닫혔다.<br><br>어깨가 한동안 제 것 같지 않았다. 문틀의 말라붙은 것 옆에 이쪽 어깨 천 조각이 나란히 끼어 있었다.`,
        ng:`문 힘이 생각보다 위였다. 어깨가 한 뼘씩 밀렸다.<br><br>동료 둘이 빠지고 셋째에서 팔이 꺾였다. 문틈에서 어깨를 뽑으며 같이 굴렀다. 못 빠진 동료는 다음 박자를 기다려야 했다.<br>다음 박자는 숨 서른 뒤에야 왔다. 그동안 문 너머와 이쪽이 서로의 숨소리만 들었다. 팔이 올라가지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-36, mind:-15 } },
      { l:'③ 문 박자를 소리 내어 세 줘 일행을 통과시킨다.', k:'bond', dc:23,
        ok:`문 옆에 붙어 서서 박자를 소리로 셌다. 하나, 둘, 지금.<br><br>지금, 소리에 한 사람씩 굴러 들어갔다. 사이 공간에서는 이쪽 손뼉이 신호였다.<br>다섯을 다 보내고 이쪽이 마지막으로 빠졌다. 세어 주는 사람 없이.<br><br>건너가 보니 다들 이쪽 박자를 입속으로 외우고 있었다. 하나, 둘, 지금. 그 박자가 한동안 일행의 걸음이 됐다.`,
        ng:`셋째 사람에서 문이 박자를 바꿨다. 고장이 더 고장 났다.<br><br>지금, 하고 외친 순간 문이 닫혔다. 동료가 문틀에 몸을 날려 반쯤 끼었다가 빠졌다. 이쪽 신호 탓이다.<br>그 뒤로는 아무도 이쪽 소리에 안 맞췄다. 각자 제 눈으로 보고 빠졌다. 그게 맞았다. 미안하다는 말은 문 너머에서 했다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-18 } }
    ] },

  { at:'S1', t:'배관 밑 — 떨어지는 간격',
    x:`천장 배관 다발 속에 뭔가 끼어 산다. 다친 몸에서 피가 떨어진다. 산성 피다.<br><br>
    복도 바닥에 구멍이 점점이 뚫렸다. 떨어지는 자리는 세 군데. 간격이 있다.<br>
    배관 속 것은 안 내려온다. 내려올 몸이 아니다. 이미 배관과 반쯤 한 몸이다. 숨 쉴 때마다 배관이 같이 부푼다.<br><br>
    그 밑을 지나야 한다. 길은 그 복도 하나다.`,
    o:[
      { l:'① 방울 사이 간격을 재서 빠져나간다.', k:'evade', dc:24,
        ok:`세 자리의 박자를 셌다. 첫째는 숨 넷, 둘째는 숨 여섯, 셋째는 제멋대로.<br><br>첫째 둘째는 박자로 지났다. 셋째 앞에서는 박자를 버리고 방울이 맺히는 걸 직접 봤다. 맺히고, 늘어지고, 끊어진다. 늘어질 때 뛰었다.<br>등 뒤에서 방울이 바닥을 뚫는 소리가 났다.<br><br>복도 끝에서 돌아봤다. 배관 속 것이 숨을 들이켰다. 복도의 구멍들이 다 이쪽 걸음 자국을 따라 나 있었다.`,
        ng:`셋째 자리에서 방울이 둘로 갈라져 떨어졌다. 하나는 피했다. 하나는 못 피했다.<br><br>손등에 닿았다. 지글거리는 소리가 제 살에서 났다. 물통을 통째로 부었다.<br>손등에 동전만 한 흉이 남았다. 당분간 그 손으로는 매달리지 못한다. 곡예사한테는 손이 발이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } },
      { l:'② 배관 속 것의 숨과 방울의 간격을 잇대어 본다.', k:'gaze', dc:25,
        ok:`방울을 보지 않고 배관을 봤다. 배관이 부풀 때마다 반 박자 뒤에 방울이 진다.<br><br>숨이 신호였다. 제멋대로인 셋째 자리도 숨에는 맞았다. 그것이 아파서 몰아쉬면 방울도 몰아서 졌다.<br>숨을 읽으며 다 건넜다. 동료들에게도 배관을 보라고 했다.<br><br>마지막 사람이 지날 때 배관 속 것이 숨을 멈췄다. 방울도 멎었다. 한참 뒤에 아주 길게 내쉬었다. 한숨 같았다.`,
        ng:`배관을 보는데 배관 틈으로 눈이 이쪽을 봤다. 숨이 흐트러졌다.<br><br>박자가 다 무너졌다. 방울 셋이 한꺼번에 졌다. 뛰고 구르며 피했다. 소매 끝이 녹아 떨어졌다.<br>복도를 나온 뒤에도 그 눈이 머리에 남았다. 아픈 것의 눈이었다. 도와 달라는 눈인지 들어오라는 눈인지 끝내 모르겠다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S1', t:'벽의 숙주들 — 닿으면 깨는 잠',
    x:`복도 양쪽 벽에 사람들이 반쯤 묻혀 있다. 시설 사람들이다. 가슴이 다 오르내린다. 자고 있다.<br><br>
    배마다 뭔가 들어 있다. 불룩하다. 이따금 그 불룩한 것이 혼자 움직인다.<br>
    복도 폭은 어깨 둘. 스치면 깬다. 깨면 어느 쪽이 깨어나는지 모른다. 사람 쪽인지, 배 속 쪽인지.<br><br>
    곡예사는 좁은 길을 안다. 이 길은 좁은 게 문제가 아니다. 길이 숨을 쉰다는 게 문제다.`,
    o:[
      { l:'① 벽과 벽 사이 숨 쉬는 틈을 골라 지난다.', k:'evade', dc:26,
        doom:{ title:'벽의 숙주들', what:'벽 속 숙주들 사이로 끌려 들어갑니다', dc:20, sec:40,
          text:`들숨에 벽이 좁아지고 날숨에 넓어진다. 날숨마다 한 걸음씩 갔다.<br><br>복도 한가운데서 숙주 하나가 눈을 떴다. 자던 눈이 아니다. 기다리던 눈이다.<br>팔이 벽에서 빠져나와 이쪽 허리를 안았다. 다른 벽에서도 팔이 나온다. 여럿이다. 벽 속으로 당긴다. 벽이 살처럼 벌어진다.<br><br>허리까지 묻혔다. 벽 안은 따뜻하다. 그게 제일 무섭다. 동료들이 팔을 하나씩 떼어 내고 있다.`,
          dieText:`벽에 자리가 하나 비어 있었다.<br><br>이제 안 비어 있다.<br>새 숙주의 가슴은 금방 다른 것들과 같은 박자로 오르내리기 시작했다. 배는 아직 불룩하지 않다. 아직은.`,
        },
        ok:`벽의 숨을 먼저 읽었다. 양쪽 벽이 같이 들이쉬는 때와 어긋나는 때가 있다.<br><br>어긋나는 숨에만 걸었다. 한쪽이 부풀면 다른 쪽으로 몸을 기울이며. 어깨가 숙주의 손끝을 여덟 번 스칠 뻔했고 여덟 번 다 비켰다.<br>복도 끝에서 뒤돌아봤다.<br><br>숙주들이 다 이쪽을 보고 있었다. 눈을 감은 채로. 감은 눈이 따라 도는 게 보였다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 바닥의 찬 점액을 어깨에 바르고 지난다.', k:'hide', dc:24,
        ok:`바닥에 고인 점액을 손에 떴다. 차고 미끈하다. 숙주들 몸에서 흘러내린 것이다.<br><br>어깨와 팔에 발랐다. 따뜻한 살 냄새가 덮였다. 벽에 스쳐도 벽이 제 것인 줄 알게.<br>두 번 스쳤다. 두 번 다 숙주가 뒤척이다 말았다. 제 몸이 제 몸에 닿은 줄 알았을 것이다.<br><br>복도를 나와 점액을 벅벅 닦았다. 다 닦이지 않는다. 당분간 이쪽한테서 이 복도 냄새가 난다. 그게 쓸모 있을 날이 또 올지도 모른다.`,
        ng:`점액이 마르면서 당기기 시작했다. 복도 한가운데서.<br><br>마른 점액은 냄새가 바뀐다. 그걸 몰랐다. 숙주 하나가 코를 벌름였다. 낯선 냄새 쪽으로 고개가 돌아간다.<br>남은 거리를 숨도 안 쉬고 지났다. 등 뒤에서 여럿이 동시에 뒤척이는 소리가 났다. 벽이 한참 출렁였다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
    ] },

  { at:'S1', t:'바닥 없는 복도 — 벽의 못',
    x:`여왕이 있는 쪽으로 가는 복도. 바닥이 통째로 없다. 산성 피가 강처럼 지나간 자국이다.<br><br>
    아래층이 내려다보인다. 아래층에서 그것들이 다닌다. 위를 본 적은 아직 없다.<br>
    벽에 격자 지지대의 못과 볼트가 줄지어 박혀 있다. 발끝 하나씩은 걸린다.<br><br>
    곡예사한테는 그게 길이다. 못 박힌 벽이 다리다.`,
    o:[
      { l:'① 무력을 실어 못에서 못으로 벽을 타고 내달린다.', k:'evade', dc:26, cost:{ might:36 },
        ok:`멈추면 무게가 못 하나에 다 실린다. 안 멈추는 게 답이다.<br><br>무력을 다리에 두르고 벽을 달렸다. 못은 디딤이 아니라 스치는 점이었다. 하나가 빠져도 다음 점이 받는다.<br>복도 끝 문턱에 닿아 멈췄다. 등 뒤에서 못 두 개가 빠져 아래층으로 떨어졌다.<br><br>쇳소리에 아래 것들이 일제히 위를 봤다. 처음으로. 빈 벽만 봤을 것이다. 이쪽은 이미 문턱 너머다.`,
        ng:`여섯 번째 못이 통째로 빠졌다. 달리던 박자가 무너졌다.<br><br>벽에 매달렸다. 못 하나에 손가락 네 개. 아래 것들이 떨어진 못 주위로 모였다. 위를 본다.<br>남은 길을 매달려 건넜다. 손가락이 펴지지 않는다. 아래 것들 중 하나가 벽을 타 보려고 뛰어오르는 걸 봤다. 아직은 못 탄다. 아직은.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-34, mind:-16 } },
      { l:'② 세 점 지지로 못을 하나씩 옮겨 디딘다.', k:'steady', dc:24,
        ok:`손 둘 발 하나, 늘 세 점을 벽에 뒀다. 넷째 점만 옮겼다.<br><br>못마다 발끝으로 먼저 눌러 봤다. 우는 못은 버리고 먼 못으로 건너뛰었다. 느렸다. 느린 만큼 한 번도 안 흔들렸다.<br>아래 것들이 두 번 멈춰서 코를 들었다. 두 번 다 이쪽은 돌이 되어 있었다.<br><br>건너편에서 손을 펴 보니 손금에 못 자국이 겹겹이 찍혔다. 길 하나가 손바닥에 그려져 있었다.`,
        ng:`중간에 못 하나가 휘었다. 세 점 중 한 점이 무너졌다.<br><br>두 점으로 버텼다. 벽에 뺨을 붙이고. 아래에서 그것들이 멈춰 서는 기척이 났다.<br>식은땀이 턱을 타고 떨어졌다. 아래층 바닥에. 하나가 그 자리를 오래 핥았다. 그동안 이쪽은 두 점으로 매달려 있었다. 팔이 한계까지 갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-18 } },
      { l:'③ 못의 녹을 읽어 빠질 못부터 가려낸다.', k:'sense', dc:24, wake:1,
        ok:`못을 다 같은 못으로 보지 않았다. 산 연기를 쐰 못은 머리가 희다. 흰 못은 속이 삭았다.<br><br>흰 못 아홉 개를 길에서 지웠다. 남은 못으로 길을 다시 그렸다. 동료들에게도 흰머리 못은 밟지 말라고 일렀다.<br>다 건넌 뒤 흰 못 하나를 손으로 뽑아 봤다. 종이처럼 뽑혔다.<br><br>쇠를 눈으로 읽는 법이 생겼다. 디디기 전에 손끝이 먼저 묻는다. 너 버틸 거냐고. 대답 없는 못은 안 디딘다.`,
        ng:`녹을 가리는 데 해가 너무 들었다. 복도에 이쪽 그림자가 길게 섰다.<br><br>아래 것 하나가 그림자를 밟았다. 그림자가 밟히는 느낌이 있을 리 없는데 목덜미가 쭈뼛했다. 그것이 그림자 끝을 따라 고개를 들었다.<br>가리던 못을 다 버리고 그냥 건넜다. 운이 좋았을 뿐이다. 운은 셈이 안 되는 게 문제다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } }
    ] },

  { at:'S1', t:'알 방 — 디딜 틈',
    x:`창고였던 방이다. 지금은 바닥 가득 알이 놓였다. 허리 높이. 가죽질. 따뜻하다.<br><br>
    알과 알 사이에 발 하나 들어갈 틈이 있다. 잘못 디디면 알이 아니라 알을 묶은 힘줄을 밟는다. 힘줄은 방 전체로 이어져 있다. 하나를 울리면 방이 운다.<br>
    방 건너편 문이 나가는 길이다. 알 사이로 스물몇 걸음.<br><br>
    알 몇 개는 위가 벌써 꽃처럼 열려 있다. 빈 알이기를.`,
    o:[
      { l:'① 틈만 골라 알 사이를 건넌다.', k:'evade', dc:25, wake:1,
        ok:`걸음을 반으로 줄였다. 발끝이 먼저 틈을 묻고 몸이 따라갔다.<br><br>힘줄은 틈 바닥에 그물처럼 깔렸다. 발끝으로 힘줄의 당김을 읽으며 느슨한 데만 디뎠다. 열린 알 옆을 지날 때는 숨도 반으로 줄였다.<br>스물세 걸음. 문턱을 넘었다.<br><br>발바닥에 눈이 생겼다. 보지 않고 읽는 눈. 틈을 고르는 게 아니라 틈이 발을 부르는 데까지 갔다. 곡예는 발끝에서 시작해서 발끝에서 끝난다는 걸 알 방이 가르쳤다.`,
        ng:`열아홉 걸음째에 힘줄 하나가 발꿈치에 닿았다. 당겨진 힘줄이었다.<br><br>방이 울렸다. 알들이 일제히 한쪽으로 기울었다. 이쪽으로.<br>남은 걸음을 뛰었다. 알 두 개를 찼다. 등 뒤에서 뭔가 젖은 것들이 깨어나는 소리가 났다. 문을 닫고도 한참 그 소리가 들렸다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 동료들 발을 한 걸음씩 자리에 놓아 준다.', k:'bond', dc:24,
        ok:`이쪽이 먼저 반쯤 건너가 자리를 잡았다. 그리고 한 사람씩 불렀다.<br><br>말이 아니라 손으로. 다음 디딜 틈을 손가락으로 짚어 주고, 흔들리면 손목을 받쳐 줬다. 무게가 실리는 순간만 잡았다가 놓았다.<br>다섯이 다 건넜다. 알은 하나도 안 울렸다.<br><br>마지막 동료가 문턱에서 이쪽 손을 한 번 꽉 쥐었다 놓았다. 알 방에서는 그게 고맙다는 말이다.`,
        ng:`넷째 동료가 이쪽 손짓을 잘못 읽었다. 왼발 자리에 오른발이 왔다.<br><br>몸이 꼬이며 알 하나를 안고 넘어졌다. 알은 안 깨졌다. 대신 품에서 데워졌다. 알 속 것이 온기 쪽으로 몸을 뒤집는 게 겉가죽 너머로 보였다.<br>알을 내려놓고 다들 숨을 죽여 나왔다. 그 알이 제일 먼저 열릴 것이다. 품어 준 온기만큼 먼저.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-18 } }
    ] },

  { at:'S2', t:'울타리 — 흔들리면 우는 철사',
    x:`정원 구획을 가르는 울타리다. 기둥은 돌, 가로줄은 철사. 녹슬었지만 팽팽하다.<br><br>
    철사는 흔들리면 운다. 그 소리를 듣는 것들이 있다. 밤마다 울타리에 몸을 부딪어 보는 것들. 우는 자리를 기억해 두는 것들.<br>
    넘어야 한다. 울지 않게.<br><br>
    곡예사 눈에 울타리는 담이 아니라 사다리다. 우는 사다리라는 게 문제다.`,
    o:[
      { l:'① 철사는 안 밟고 돌기둥만 디뎌 넘는다.', k:'evade', dc:24, wake:1,
        ok:`기둥 옆면의 돌 틈에 발끝을 걸었다. 철사는 눈으로만 보고 손도 안 댔다.<br><br>기둥 꼭대기에서 반대편으로 몸을 넘겼다. 내릴 때는 기둥에 바짝 붙어 미끄러져 내렸다.<br>철사는 끝까지 안 울었다.<br><br>울타리를 사다리로 보던 눈이 한 겹 더 벗겨졌다. 길은 물건의 쓰임새가 아니라 물건의 침묵에 나 있다. 안 우는 데만 이으면 어디든 길이다.`,
        ng:`기둥 중간의 돌 하나가 헐거웠다. 발밑에서 돌이 빠지며 무릎이 철사에 닿았다.<br><br>한 줄이 울었다. 낮게, 길게. 풀숲 저쪽에서 대답처럼 우는 소리가 왔다.<br>구르다시피 넘어 반대편 수풀에 엎드렸다. 그것들이 울타리의 운 자리에 와서 한참 머물다 갔다. 운 자리를 기억해 갔다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 무력을 실어 아래 철사 둘을 천천히 벌린다.', k:'break', dc:24, cost:{ might:32 },
        ok:`맨 아래 두 줄을 잡았다. 확 당기면 운다. 숨 열 번에 걸쳐 조금씩 벌렸다.<br><br>쇠가 우는 건 떨 때다. 떨지 않게, 힘을 끊김 없이 이었다. 몸 하나 지나갈 틈이 생겼다.<br>다들 배로 기어 지나갔다. 철사는 벌어진 채로 침묵했다.<br><br>마지막에 철사를 도로 좁혀 놨다. 틈을 기억하는 건 이쪽들만이 아니니까.`,
        ng:`아홉 번째 숨에서 손이 미끄러졌다. 철사가 제자리로 튕겼다.<br><br>울타리 전체가 울었다. 종처럼. 풀숲에서 여럿이 일어서는 소리.<br>틈이고 뭐고 다 같이 기둥을 타 넘었다. 손바닥이 철사에 길게 그였다. 등 뒤에서 그것들이 울타리에 몸을 부딪는 소리가 밤새 났다. 운 자리를 찾고 있었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-15 } },
      { l:'③ 울타리에서 이미 죽은 구간을 찾아낸다.', k:'sense', dc:24,
        ok:`울타리를 따라 걸으며 철사를 하나씩 눈으로 퉁겼다. 팽팽한 줄과 죽은 줄은 녹 색부터 다르다.<br><br>물에 반쯤 잠긴 구간이 있었다. 철사가 셋 다 늘어져 있다. 늘어진 줄은 울지 못한다.<br>거기로 넘었다. 물소리가 발소리를 덮었다.<br><br>넘고 나서 봤다. 그 구간 바닥의 진흙에 발자국이 포개져 있었다. 그것들도 이 구간을 안다. 그것들의 문으로 들어온 셈이다.`,
        ng:`죽은 구간인 줄 알았던 데에 줄 하나가 새로 걸려 있었다. 녹슨 척하는 새 줄.<br><br>건드렸다. 울지 않았다. 대신 줄 끝에 달린 작은 뼈들이 서로 부딪었다. 딸깍딸깍. 방울이었다. 그것들이 단 방울.<br>뼈 방울 소리에 풀숲이 갈라지며 왔다. 다들 흩어져 뛰었다. 다시 모이는 데 한나절 걸렸다. 하나는 발목을 절었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S2', t:'잠긴 양치 — 뿌리 징검다리',
    x:`양치 숲이 물에 잠겼다. 무릎에서 허리 깊이. 물 위로 굵은 뿌리들이 등처럼 솟았다.<br><br>
    물을 흔들면 안 된다. 큰 것이 물결을 읽는다. 어디서 읽는지는 모른다. 그래서 더 안 된다.<br>
    뿌리에서 뿌리로 뛰면 물에는 몸이 안 닿는다. 뿌리 간격은 제각각이다. 먼 것은 몸 두 개.<br><br>
    곡예사는 징검다리를 좋아한다. 이 징검다리는 미끄럽고, 아래에서 올려다보는 게 있다.`,
    o:[
      { l:'① 뿌리에서 뿌리로 물을 안 울리고 건넌다.', k:'evade', dc:26,
        doom:{ title:'잠긴 양치', what:'물 밑으로 끌려 들어갑니다', dc:20, sec:35,
          text:`여섯 번째 뿌리가 뿌리가 아니었다. 디딘 순간 그것이 가라앉았다.<br><br>등이었다. 물밑에 엎드려 뿌리 흉내를 내던 것의 등. 발목이 물에 잠기기도 전에 아래에서 잡아챘다.<br>물이 얼굴 위로 닫혔다. 초록 어둠. 큰 뿌리 밑 굴 쪽으로 끌려 들어간다. 물풀이 몸을 쓸고 지나간다.<br><br>물 위에서 동료들의 다리가 허우적대는 게 거꾸로 보인다. 공기 방울이 마지막으로 크게 한 번 올라갔다.`,
          dieText:`징검다리 돌을 밟기 전에 두드려 보라고 배웠다.<br><br>물에 잠긴 숲에서는 두드리는 것도 소리다. 두드릴 수 없으면 디디지 말았어야 했다.<br>물 위로 양치 잎 몇 장이 돌았다. 물결은 금방 잤다. 큰 것이 읽을 것도 없이.`,
        },
        ok:`뛰기 전에 뿌리마다 눈으로 재 봤다. 물때 낀 높이가 다 비슷한데 하나만 물때가 없다.<br><br>그 하나를 건너뛰고 먼 뿌리로 바로 넘었다. 몸 두 개 거리. 날면서 물에 그림자도 안 줬다.<br>건너편 둔덕에 내려 돌아봤다. 물때 없던 뿌리가 천천히 가라앉고 있었다. 숨 쉬러 올라와 있던 것이다.<br><br>물결 하나 없이 건넜는데 등이 다 젖었다. 땀이었다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 물살이 치는 박자에 걸음을 묻어 걷는다.', k:'steady', dc:24,
        ok:`바람이 수면을 긁을 때마다 물결이 인다. 그 물결에 이쪽 물결을 묻었다.<br><br>바람 불 때 세 걸음, 멎으면 돌. 허리까지 잠긴 채 숲을 반 시간에 건넜다.<br>큰 것이 한 번 지나갔다. 물이 멀리서 밀려 올라왔다 내려갔다. 다들 숨을 물 위에 띄워 놓고 견뎠다.<br><br>건너편에서 보니 지나온 물길에 이쪽들 자국이 하나도 없다. 바람 자국뿐이다.`,
        ng:`바람이 너무 일찍 멎었다. 걸음 반이 물에 남았다.<br><br>그 반 걸음의 물결이 퍼져 나갔다. 멀리서 물이 부풀었다. 온다.<br>뿌리 뒤에 몸을 구겨 넣고 코만 내놓았다. 큰 것이 아주 가까이서 물을 들이켰다 뱉었다. 이쪽 물결을 마셨다 뱉은 것이다. 그러고는 갔다. 심장이 한나절 뛰었다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-20 } }
    ] },

  { at:'S2', t:'가지 — 무게를 다는 나무',
    x:`물을 피해 나무 위로 길을 잡았다. 가지가 서로 얽혀 숲 끝까지 이어진다.<br><br>
    아래에 무리가 따라붙었다. 올려다보며 걷는다. 서두르지 않는다. 가지가 휘기를 기다린다.<br>
    가지는 무게를 단다. 휜 만큼이 이쪽 몸값이다. 많이 휘면 떨어질 자리를 먼저 가서 기다리면 된다. 그걸 아는 것들이다.<br><br>
    곡예사도 가지를 안다. 어디가 휘고 어디가 안 휘는지.`,
    o:[
      { l:'① 줄기 쪽 밑동 가지만 밟아 휨을 죽인다.', k:'evade', dc:25,
        ok:`가지 끝은 길이 넓어 보여도 안 갔다. 줄기에서 손 두 뼘 안쪽만 디뎠다.<br><br>휨이 없으니 무게도 없다. 아래 것들이 고개를 갸웃대며 따라왔다. 다는 저울에 아무것도 안 올라오니까.<br>나무 여섯 그루를 그렇게 건넜다. 무리가 반으로 줄었다. 흥미를 잃은 쪽이 떨어져 나갔다.<br><br>남은 반은 끝까지 왔다. 끈질긴 쪽만 남는 건 어디나 같다. 숲 끝에서 바위 지대로 내려서자 그제야 돌아갔다.`,
        ng:`일곱 그루째에서 줄기가 속이 빈 나무였다. 밑동 가지가 통째로 내려앉았다.<br><br>한 단 아래 가지에 걸렸다. 크게 휘었다. 저울이 몸값을 제대로 달았다.<br>아래 것들이 떨어질 자리로 모여드는 게 보였다. 반대쪽으로 몸을 던져 옆 나무로 넘었다. 팔꿈치가 꺾이는 소리가 났다. 부러지진 않았다. 이번에는.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-16 } },
      { l:'② 짐을 먼 가지 끝에 던져 저울을 속인다.', k:'sense', dc:24,
        ok:`빈 짐자루에 돌을 채워 옆 나무 가지 끝에 던졌다. 가지가 크게 휘었다.<br><br>무리가 일제히 그 나무 밑으로 옮겨 갔다. 떨어질 자리를 잡는다.<br>그 사이 이쪽들은 반대쪽 가지로 조용히 건넜다. 짐자루가 떨어질 때까지 그것들은 빈 저울만 지켰다.<br><br>자루 떨어지는 소리와 그것들이 자루를 찢는 소리를 등 뒤로 들었다. 돌만 나왔을 것이다. 다음번에는 안 속는다. 다음번이 없기를.`,
        ng:`던진 자루가 가지에 안 걸리고 그대로 떨어졌다.<br><br>떨어지는 소리에 무리가 돌아봤다. 자루가 아니라 던진 자리를. 던진 팔의 높이를. 이쪽 나무를.<br>그 나무를 흔들기 시작했다. 뿌리째. 옆 나무로 뛰고 또 뛰었다. 마지막 도약에서 가지를 놓칠 뻔했다. 손끝 두 마디로 살았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S2', t:'큰 것의 길 — 발자국 사이',
    x:`숲을 가르는 맨땅 길. 큰 것이 다니는 길이다. 발자국 하나가 욕조만 하다.<br><br>
    길 건너편까지 몸 여덟 개. 가로질러야 한다. 큰 것은 지금 길 저쪽 끝에서 이쪽으로 온다. 땅이 발걸음마다 운다.<br>
    걸음과 걸음 사이, 땅이 안 우는 틈이 있다. 그 틈에 건너는 거다.<br><br>
    곡예사는 박자 있는 것은 다 건넌다. 이 박자는 발밑에서 올라온다는 게 다를 뿐이다.`,
    o:[
      { l:'① 발걸음 울림 사이에 길을 가로지른다.', k:'evade', dc:26,
        doom:{ title:'큰 것의 길', what:'큰 것의 입에 물려 갑니다', dc:20, sec:35,
          text:`울림 하나, 틈, 울림 둘. 틈에 뛰었다. 길 한가운데서 울림이 사라졌다.<br><br>멈춘 것이다. 큰 것이 걸음을 멈추면 박자도 없다. 돌아보니 큰 것이 고개를 낮추고 이쪽을 보고 있었다. 생각보다 가깝다. 생각보다 빠르다.<br>세 걸음 만에 왔다. 입이 몸통을 스쳤다 닫혔다. 옷째 물렸다. 땅에서 발이 떨어진다.<br><br>높다. 큰 것의 입에 물린 채 숲이 아래로 지나간다. 동료들이 점처럼 작아지며 쫓아온다.`,
          dieText:`박자는 걷는 것의 것이다.<br><br>멈추는 것은 박자가 아니라 눈이었다. 눈까지는 셈에 못 넣었다.<br>큰 것의 길에 욕조만 한 발자국이 이어진다. 그중 하나에 신발 한 짝이 고여 있다.`,
        },
        ok:`울림을 발바닥으로 받으며 셌다. 틈은 숨 둘 길이.<br><br>첫 틈에 반을 건넜다. 발자국 구덩이 하나에 몸을 던져 넣고 울림 둘을 보냈다. 둘째 틈에 나머지 반.<br>건너편 수풀에 구르며 들어갔다.<br><br>큰 것이 지나갔다. 방금 이쪽이 엎드렸던 발자국 위에 새 발자국이 찍혔다. 반 뼘 비껴서. 같은 자리를 두 번 안 밟는 것이었다. 그걸 알았으면 거기 안 엎드렸다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 발자국 구덩이에 엎드려 지나가기를 기다린다.', k:'hide', dc:24,
        ok:`제일 깊은 발자국을 골라 들어가 엎드렸다. 흙냄새가 이쪽 냄새를 덮는다.<br><br>큰 것이 왔다. 발 하나가 구덩이 바로 옆에 내려앉았다. 흙벽이 무너져 어깨를 덮었다. 숨을 반만 쉬었다.<br>지나갔다. 울림이 멀어진 뒤에도 쉰을 세고 나왔다.<br><br>나와 보니 이쪽이 엎드린 발자국만 빼고 길의 발자국이 다 새로 찍혀 있었다. 제 발자국은 안 밟는 것이다. 제일 안전한 자리였던 셈이다. 알고 고른 건 아니었다.`,
        ng:`구덩이가 얕았다. 등이 지면 위로 손가락 두 개만큼 솟았다.<br><br>큰 것이 그 옆을 지나다 멈췄다. 콧김이 등을 훑었다. 뜨겁고 축축하다. 흙까지 같이 들이켜는 숨.<br>재채기가 나기 직전에 큰 것이 흥미를 잃고 갔다. 일어나니 등에 콧김 자국처럼 풀이 다 누웠다. 무릎에 힘이 안 들어와 한참 앉아 있었다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S2', t:'승강기 통로 — 낡은 줄',
    x:`낡은 승강기의 통로. 승강기 칸은 아래층에 처박혀 있고 쇠줄만 수직으로 걸렸다.<br><br>
    줄은 가닥이 반쯤 풀렸다. 풀린 가닥이 가시처럼 섰다. 그래도 줄은 줄이다.<br>
    아래 어둠에서 물소리가 난다. 통로 바닥까지 물이 들어와 있다. 물이 있으면 그 큰 것도 올 수 있다.<br><br>
    위로 두 층. 곡예사한테 줄 두 층은 길이 아니라 복도다.`,
    o:[
      { l:'① 풀린 가닥을 피해 줄을 타고 오른다.', k:'evade', dc:25, wake:1,
        ok:`줄을 쥐기 전에 눈으로 가시 자리를 다 외웠다. 왼손 자리, 오른손 자리.<br><br>외운 대로 올랐다. 손은 줄을 보지 않고도 가시를 비켜 쥐었다. 반 층쯤에서 아래 물이 크게 출렁였다. 올려다보는 기척. 서두르지 않았다. 서두른 손이 가시를 쥔다.<br>두 층을 다 올라 난간을 넘었다.<br><br>외운 길을 손이 따라가는 동안 눈은 쉬고 있었다. 눈이 한 번 본 것을 손이 끝까지 기억하는 법. 그게 오늘 줄에서 얻은 것이다.`,
        ng:`외운 자리가 하나 밀렸다. 오른손이 가시 묶음을 쥐었다.<br><br>손바닥이 뚫렸다. 놓으면 아래는 물이다. 쥔 채로 올랐다.<br>난간을 넘고 손을 펴 보니 가시 두 개가 박힌 채 부러져 있었다. 뽑는 데 이 악물었다. 줄 아래 물이 그때까지 출렁이고 있었다. 기다렸던 것이다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 무력으로 줄을 당겨 고정해 일행의 사다리를 만든다.', k:'steady', dc:24, cost:{ might:30 },
        ok:`줄 끝을 끌어다 난간 기둥에 감았다. 무력으로 당겨 팽팽하게. 비스듬한 사다리가 됐다.<br><br>흔들리지 않는 줄은 오르기 쉽다. 동료들이 하나씩 올랐다. 이쪽은 밑에서 줄을 지켰다.<br>마지막으로 이쪽이 올랐다. 감았던 줄을 풀어 떨어뜨렸다.<br><br>줄이 물에 닿는 순간 물이 끓듯 일었다. 뭔가 줄을 물고 흔들었다. 사람인 줄 알았을 것이다. 줄이어서 미안하게 됐다.`,
        ng:`당기는 중에 줄이 위 도르래에서 한 칸 미끄러졌다.<br><br>쇠가 쇠를 무는 비명이 통로를 두 층 울렸다. 아래 물이 벽을 쳤다.<br>고정이고 뭐고 다들 그냥 맨줄을 타고 올랐다. 마지막 사람 발밑으로 물이 기둥처럼 솟았다 내려갔다. 젖은 건 신발뿐이다. 신발뿐이어서 다행이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'③ 먼저 올라 위층 난간에서 일행을 끌어올린다.', k:'bond', dc:24,
        ok:`이쪽이 먼저 올랐다. 난간에 다리를 감아 몸을 고정하고 팔을 내렸다.<br><br>올라오는 동료의 손목을 받아 마지막 한 층을 끌어올렸다. 한 사람씩. 줄에서 제일 힘든 건 마지막 팔 하나 길이다. 그걸 대신 맡았다.<br>다섯을 다 올렸다.<br><br>마지막 동료를 올릴 때 아래 물에서 뭔가가 줄을 타고 오르기 시작했다. 줄을 걷어 올렸다. 그것이 물로 도로 떨어지는 소리가 통로를 울렸다. 무거운 소리였다. 생각보다 많이.`,
        ng:`셋째 동료가 손을 뻗다 줄에서 몸이 돌았다. 받은 손목이 비틀렸다.<br><br>둘 다 난간에 걸린 채 버텼다. 이쪽 어깨가 빠질 듯 늘어났다. 겨우 끌어올렸다.<br>남은 둘은 제 힘으로 올라왔다. 이쪽 팔이 당분간 줄을 못 탄다. 끌어올리는 쪽도 값을 치른다는 걸 오늘 알았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-16 } }
    ] },

  { at:'S2', t:'도약하는 무리 — 호를 읽기',
    x:`무리가 둘러쌌다. 바위 지대. 그것들은 달려들지 않는다. 뛴다. 포물선으로.<br><br>
    한 마리가 뛰면 이쪽이 피할 자리에 다음 마리가 뛴다. 피하는 길목을 접수하는 사냥. 앞서 간 이들이 그렇게 몰렸을 것이다.<br>
    곡예사도 호를 안다. 호는 아름답고, 정직하다. 뜬 것은 방향을 못 바꾼다.<br><br>
    제일 큰 것이 어깨를 낮췄다. 시작이다.`,
    o:[
      { l:'① 박자를 어긋내 두 번째 도약을 빗나가게 한다.', k:'evade', dc:25,
        ok:`첫 마리가 떴다. 피하는 척 왼쪽으로 반 걸음, 그리고 멈췄다.<br><br>두 번째 마리는 이쪽이 갈 자리로 떴다. 이쪽이 안 간 자리로. 빈 바위에 둘이 포개져 떨어졌다.<br>엉킨 틈에 바위 사이로 빠졌다. 세 번째 마리가 떴지만 그건 읽던 책의 다음 장을 넘긴 것뿐이다. 책이 바뀐 걸 모르고.<br><br>바위 지대를 벗어날 때까지 같은 수를 세 번 썼다. 세 번째에는 반쯤 읽혔다. 네 번은 없어야 한다.`,
        ng:`멈추는 반 걸음이 반의반 걸음 모자랐다.<br><br>두 번째 마리의 뒷발이 어깨를 긁고 지나갔다. 바위에 어깨부터 넘어졌다.<br>구르며 바위 틈에 몸을 박았다. 무리가 틈 위에 모여 교대로 앞발을 넣었다. 발톱이 머리카락을 몇 올 집어 갔다. 틈 안쪽으로 반나절을 기어서 빠져나왔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-34, mind:-16 } },
      { l:'② 무리 중 세는 놈이 어느 놈인지 본다.', k:'gaze', dc:25,
        ok:`뛰는 놈들을 안 봤다. 안 뛰는 놈을 봤다.<br><br>뒤쪽에 하나, 바위 위에 앉아 고개만 움직이는 놈. 이쪽 걸음을 세고 다음 도약 자리를 무리에게 일러 주는 놈. 세는 놈.<br>그놈 쪽으로 똑바로 걸었다. 세는 놈은 제가 셈당할 줄 모른다. 당황해서 일어선 순간 무리의 호가 다 흐트러졌다.<br><br>그 틈에 빠져나왔다. 등 뒤에서 세는 놈이 울었다. 꾸짖는 소리 같았다. 누구를 꾸짖는지는 모르겠다.`,
        ng:`세는 놈을 찾는 동안 세는 놈도 이쪽을 셌다. 저쪽이 빨랐다.<br><br>눈이 마주친 순간 무리 전체가 동시에 떴다. 호 다섯 개가 한 점으로 모였다. 그 점이 이쪽이었다.<br>몸을 바닥에 던져 호 밑으로 깔렸다. 발톱 하나가 등을 밟고 갔다. 바위 틈까지 네 발로 뛰었다. 사람이 네 발로 그렇게 빨리 뛸 수 있는 줄 몰랐다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-36, spirit:-18 } }
    ] },

  { at:'S2', t:'쓰러진 줄기 — 나란히 헤엄치는 것',
    x:`아름드리 줄기가 물 위에 쓰러져 다리가 됐다. 건너편 둔덕까지 서른 걸음.<br><br>
    물속에서 뭔가 줄기와 나란히 헤엄친다. 등지느러미도 그림자도 아니고, 그냥 물의 결이 다르다. 이쪽 걸음과 같은 속도로.<br>
    기다리는 것이다. 발을 헛딛는 순간을. 서른 걸음 중 한 걸음이면 된다는 걸 아는 것이다.<br><br>
    곡예사 걸음은 안 미끄러진다. 그걸 저쪽은 모른다.`,
    o:[
      { l:'① 걸음 속도를 바꿔 가며 저쪽 셈을 흩뜨린다.', k:'evade', dc:25, wake:1,
        ok:`열 걸음은 느리게. 그러다 세 걸음을 한달음에. 다시 멈춰 섰다.<br><br>물의 결이 자꾸 어긋난다. 이쪽을 앞질렀다가 되돌아오고, 기다렸다가 놓친다. 셈이 안 맞는 사냥은 사냥이 아니다.<br>마지막 다섯 걸음을 그냥 걸었다. 물의 결이 멀어졌다. 포기가 물결로도 보였다.<br><br>걸음은 재주가 아니라 말이라는 걸 배웠다. 속도 하나로 저쪽에 거짓말을 할 수 있다. 몸이 하는 거짓말은 들키지 않는다.`,
        ng:`속도를 바꾸다 이끼 낀 옹이를 밟았다. 미끄러지진 않았다. 휘청였다.<br><br>그 휘청 하나에 물이 터졌다. 줄기 옆으로 입이 솟았다. 팔뚝째 옷소매를 물고 내려갔다.<br>줄기에 엎드려 소매를 찢어 버리고 남은 길을 기었다. 물의 결이 줄기 밑으로 들어와 이쪽 배 밑을 따라왔다. 나무 한 겹 아래서.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 줄기에 배를 붙이고 걸터타 낮게 건넌다.', k:'steady', dc:24,
        ok:`서서 주는 그림자가 제일 크다. 걸터앉아 배를 붙이고 손으로 끌며 갔다.<br><br>그림자가 줄기 그림자에 묻혔다. 물의 결이 줄기 옆을 두 번 오갔다. 사람을 잃어버린 결이었다.<br>서른 걸음을 손으로 다 갔다. 느렸지만 물은 끝까지 조용했다.<br><br>둔덕에 올라 바지를 짰다. 물에 안 빠졌는데 배부터 무릎까지 다 젖었다. 줄기가 그만큼 물에 가라앉아 있었다는 걸 건너고서야 알았다. 이쪽 무게만큼.`,
        ng:`반쯤 갔을 때 줄기가 천천히 구르기 시작했다. 물먹은 쪽으로.<br><br>배를 붙인 채 같이 굴렀다. 머리가 물에 잠기기 직전에 반대쪽으로 몸을 넘겨 다시 위를 잡았다.<br>물의 결이 급하게 다가오는 게 보였다. 남은 거리를 네 발로 뛰다시피 갔다. 둔덕에 구르며 올라갔다. 바로 뒤에서 물이 줄기를 쳤다. 줄기가 한 바퀴 돌았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] }
]);

// ── 경신술사 (lightfoot) · 내공 ──────────────
kJob('lightfoot', 'S', [
  { at:'S', t:'재 바닥 — 발자국을 읽는 것들',
    x:`바닥에 재가 고르게 깔렸다. 손가락 한 마디 깊이. 눈처럼 곱다.<br><br>
    재 위에 발자국이 몇 줄 나 있다. 사람 것이 앞서가고, 그 위를 밟으며 큰 것이 따라갔다. 발자국이 끝나는 자리에 재가 크게 흐트러졌다. 그 뒤로는 끌린 자국 하나뿐이다.<br>
    여기 것들은 눈이 아니라 자국을 본다. 자국은 지워지지 않는 비명이다.<br><br>
    경신술사는 무게를 발에 안 싣는다. 재가 받을 무게가 없으면 자국도 없다.`,
    o:[
      { l:'① 재에 자국을 안 남기고 건넌다.', k:'evade', dc:24, wake:1,
        ok:`숨을 끌어올려 가슴에 띄웠다. 발은 재에 얹기만 했다. 디딘다기보다 스쳤다.<br><br>반쯤 갔을 때 뒤에서 그것이 들어왔다. 코를 재에 박고 자국을 읽는다. 이쪽 자국은 없다. 그것이 재 한가운데서 길을 잃었다.<br>끝까지 건너 돌아봤다. 재 벌판에 그것의 발자국만 어지럽다.<br><br>지나온 길이 이쪽 눈에도 안 보였다. 몸이 가벼워진 게 아니다. 무게를 어디다 두고 오는 법을 몸이 익힌 것이다. 어디다 뒀는지는 아직 모른다.`,
        ng:`아홉 걸음째에 재 밑에 숨은 턱을 찼다. 몸이 흔들리며 무게가 한 발에 다 실렸다.<br><br>자국 하나가 깊게 찍혔다. 하나면 충분했다. 그것이 그 자국에 코를 박더니 고개를 들어 자국의 방향을 봤다.<br>남은 거리를 전력으로 달렸다. 자국이 줄줄이 찍혔다. 문을 넘고 나서도 그것이 자국을 하나하나 밟으며 따라오는 소리가 들렸다.`,
        win:{ exp:22, dream:2 }, lose:{ mind:-18, spirit:-20 } },
      { l:'② 내공을 실어 한 호흡에 재 벌판을 가로지른다.', k:'evade', dc:24, cost:{ qi:30 },
        ok:`내공을 다리에 몰고 숨을 하나로 길게 뽑았다. 그 숨이 끝나기 전에 건넌다.<br><br>달렸다. 재가 일 틈이 없었다. 발이 닿는 시간이 재가 무게를 아는 시간보다 짧았다.<br>건너편 돌바닥에 내려서며 숨을 뱉었다.<br><br>재 벌판에는 바람 지나간 자국만 한 줄 남았다. 그것이 와서 그 바람 자국에 한참 코를 댔다. 바람을 쫓아갈 수는 없다.`,
        ng:`숨이 반에서 끊겼다. 끊긴 자리에서 몸이 가라앉았다.<br><br>무릎까지 재에 빠졌다. 재가 연기처럼 일었다. 자국이 아니라 봉화를 올린 셈이다.<br>허우적대며 나머지를 건넜다. 재를 뒤집어쓴 채. 그것들이 봉화를 보고 모여드는 기척이 사방에서 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'③ 끌린 자국이 어디로 갔는지부터 본다.', k:'sense', dc:24,
        ok:`끌린 자국을 눈으로 따라갔다. 벽의 구멍으로 들어갔다. 구멍 둘레에 재가 쌓인 모양새가 오래됐다.<br><br>드나드는 길이 저 구멍 하나라는 뜻이다. 구멍에서 제일 먼 가장자리로 길을 잡았다.<br>벌판을 돌아 건너는 내내 구멍은 조용했다.<br><br>다 건널 즈음 구멍에서 코 고는 소리가 났다. 먹고 자는 중이었다. 끌려간 이에게는 미안하지만, 그 식사가 이쪽들 시간을 벌었다.`,
        ng:`자국을 읽느라 고개를 숙인 사이 재가 발등을 덮었다. 재가 움직인 것이다.<br><br>바닥의 재 전체가 아주 천천히 구멍 쪽으로 흐르고 있었다. 벌판이 혀였다.<br>다들 소리치며 가장자리로 뛰었다. 재가 좋아리를 감으며 당겼다. 벽을 잡고 빠져나왔다. 신발 속까지 재가 찼다. 털어도 털어도 나온다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-26, spirit:-18 } }
    ] },

  { at:'S', t:'검은 물 — 가라앉기 전에',
    x:`길이 물에 끊겼다. 검고 고요한 물. 건너편까지 몸 열 개 길이.<br><br>
    물속에 큰 것이 있다. 들어가면 안 되는 물이라고 물가의 뼈들이 말해 준다. 뼈는 다 물 쪽으로 머리를 두고 있다. 나오다 당긴 것이다.<br>
    경신술사는 물을 밟는다. 가라앉기 전에 다음 발이 나가면 물도 바닥이다.<br><br>
    다만 물 위를 달리는 발소리는 물속에 그대로 울린다. 저쪽 귀에 대고 뛰는 셈이다.`,
    o:[
      { l:'① 물결보다 가볍게 수면을 밟아 건넌다.', k:'evade', dc:26,
        doom:{ title:'검은 물', what:'물 밑으로 끌려 들어갑니다', dc:20, sec:35,
          text:`다섯 걸음까지는 물이 바닥이었다. 여섯 걸음째에 물이 입이 됐다.<br><br>발밑에서 물이 꺼지며 올라온 것이 발목을 감았다. 차갑고 빈틈없는 힘. 수면이 눈앞에서 닫혔다.<br>검은 물속은 위아래가 없다. 공기 방울이 가는 쪽이 위라는 것만 안다. 몸은 그 반대로 끌려간다. 깊은 쪽으로. 바닥의 더 깊은 어둠 쪽으로.<br><br>물가에서 동료들이 장대를 뻗고 있다. 장대 끝이 손끝에서 한 뼘 멀다.`,
          dieText:`가라앉기 전에 다음 발이 나가면 물도 바닥이다.<br><br>다음 발이 나가기 전에 물이 먼저 왔을 뿐이다.<br>물가의 뼈가 한 줄 늘었다. 머리는 물 쪽을 보고 있다.` },
        ok:`발끝에 내공을 모으고 수면을 스치듯 달렸다. 발이 물을 누르기 전에 다음 발.<br><br>한가운데서 물이 부풀었다. 아래에서 올라오는 것의 머리가 수면을 밀었다. 그 부푼 물마루를 오히려 디딤 삼아 찼다.<br>건너편 바위에 내려섰다. 등 뒤에서 물이 크게 열렸다 닫혔다.<br><br>물마루를 디딘 발바닥이 한동안 저렸다. 그 밑이 그것의 정수리였다는 걸 발이 알고 있었다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 뼈들을 이어 디딤 삼아 가장자리로 돈다.', k:'steady', dc:24,
        ok:`물가를 따라 큰 뼈들이 반쯤 잠겨 있다. 등뼈, 갈비뼈. 디딜 만한 것들이다.<br><br>뼈에서 뼈로 무게를 옮겼다. 뼈는 가라앉지 않는다. 이미 바닥에 닿아 있는 것들이라.<br>물속 큰 것이 한 바퀴 돌며 지나갔다. 뼈는 건드리지 않았다. 제가 먹고 남긴 것이라 그런가.<br><br>다 돌아 건넜다. 마지막 뼈에서 내려설 때 그 뼈가 조금 움직였다. 아직 뼈가 아니었는지도 모른다. 돌아보지 않았다.`,
        ng:`갈비뼈 하나가 디딘 순간 부러졌다. 물에 반쯤 빠졌다.<br><br>물속에서 큰 것이 방향을 트는 게 물결로 느껴졌다. 뼈를 끌어안고 몸을 뺐다.<br>물가로 구르며 나왔다. 바지가 허리까지 젖었다. 젖은 자리가 밤새 시렸다. 물이 아니라 그 물속 시선이 시렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
    ] },

  { at:'S', t:'숨을 세는 어둠',
    x:`어둠 저쪽에 그것이 있다. 보이지 않는다. 숨소리로 사냥하는 것.<br><br>
    사람은 쉰다. 참아도 심장이 밀어낸다. 앞서 간 이는 숨을 참다가 터뜨렸을 것이다. 터뜨린 자리가 저기 어둠 속이다.<br>
    경신술사의 숨은 실이다. 가늘고 길게, 코끝에서만.<br><br>
    그것이 어둠 속에서 이쪽 숨을 기다린다. 들을 것이 없으면 그것도 움직여야 한다.`,
    o:[
      { l:'① 숨을 실처럼 늘여 어둠을 지난다.', k:'steady', dc:25, wake:1,
        ok:`들숨 열, 날숨 스물. 코끝으로만. 심장도 내공으로 눌러 반 박자로 낮췄다.<br><br>그것 곁을 지났다. 팔 하나 거리. 그것의 숨이 이쪽 뺨에 닿았다. 비리고 뜨겁다. 이쪽 숨은 실이라 저쪽에 안 닿았다.<br>어둠을 다 지나 모퉁이를 돌았다.<br><br>숨을 돌려놓는데 한참 걸렸다. 실로 늘인 숨은 급히 당기면 끊어진다. 끊어진 숨이 소리가 된다. 끝까지 실을 천천히 감는 법, 그것까지가 오늘 배운 것이다.`,
        ng:`날숨 열아홉에서 목이 간지러웠다. 재채기가 아니라 그 전 단계.<br><br>삼켰다. 삼키는 소리가 났다. 꿀꺽. 그 작은 소리에 어둠이 통째로 몸을 틀었다.<br>달렸다. 숨이고 뭐고 다 터뜨리면서. 모퉁이 두 개를 돌고 틈에 끼어들었다. 그것이 틈 앞을 세 번 오갔다. 숨을 실로 뽑은 채 그 세 번을 다 보냈다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-18 } },
      { l:'② 젖은 벽에 몸을 붙여 숨을 벽에 묻는다.', k:'hide', dc:24,
        ok:`벽이 젖어 차다. 거기 가슴을 붙였다. 숨이 벽을 타고 아래로 깔렸다.<br><br>찬 벽은 숨의 온기를 먹는다. 그것은 온기 실린 숨을 듣는다. 식은 숨은 바람과 같다.<br>벽을 따라 게걸음으로 어둠을 지났다. 그것이 한 번 이쪽 벽에 코를 댔다. 벽 냄새만 맡고 돌아섰다.<br><br>지나고 나니 가슴팍이 벽의 찬 기운으로 뻣뻣했다. 심장이 언 것 같았다. 덕분에 조용했지만.`,
        ng:`벽에 가슴을 붙였는데 벽 안쪽에서 맥이 뛰었다. 벽이 살아 있었다.<br><br>이쪽 심장과 벽의 맥이 어긋나며 겹쳤다. 그 박자를 그것이 들었다. 두 심장은 한 심장보다 시끄럽다.<br>벽에서 떨어져 뛰었다. 등 뒤에서 벽이 꿈틀대는 소리와 그것이 벽을 치는 소리가 겹쳤다. 서로 싸우는 모양이었다. 덕분에 살았다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
    ] },

  { at:'S', t:'조각 밭 — 밟으면 우는 바닥',
    x:`바닥 가득 깨진 조각이 깔렸다. 유리인지 뼈인지 비늘인지, 셋 다인지.<br><br>
    한 조각이 울면 밭 전체가 운다. 서로 괴어 있어서. 그 소리를 기다리는 것들이 천장 어둠에 매달려 있다. 가끔 침이 조각 위로 떨어진다.<br>
    건너편 문까지 마흔 걸음. 돌아가는 길은 없다.<br><br>
    경신술사 발은 조각 위에서도 무게가 없다. 문제는 혼자가 아니라는 것이다.`,
    o:[
      { l:'① 조각이 울기 전에 발을 거둔다.', k:'evade', dc:25,
        ok:`조각이 우는 건 눌려서 돌 때다. 돌기 전에 발을 거뒀다.<br><br>발끝이 조각에 닿고, 조각이 기울려는 찰나에 무게가 이미 다음 발에 가 있었다. 마흔 걸음 내내.<br>천장의 것들이 침만 흘렸다. 들을 것이 없었다.<br><br>문 앞에서 돌아보니 동료들이 이쪽 디딘 자리를 눈으로 외우고 있었다. 자리가 아니라 박자를 외워야 하는데. 그건 가르쳐 줄 방법이 없다.`,
        ng:`서른 걸음째, 밟은 조각 밑에 빈 데가 있었다. 조각이 반 바퀴 돌며 울었다.<br><br>맑은 소리였다. 종처럼. 천장에서 셋이 떨어졌다.<br>남은 열 걸음을 조각을 차며 달렸다. 밭 전체가 울었다. 문을 닫는 순간까지 등 뒤에서 조각 밟는 소리가 따라왔다. 이쪽보다 가벼운 발소리였다. 그게 제일 서늘했다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 내공을 나눠 동료를 업고 두 번 건넌다.', k:'evade', dc:25, cost:{ qi:34 },
        ok:`제일 무거운 동료부터 업었다. 내공을 등과 다리에 나눠 둘 무게를 하나로 눌렀다.<br><br>두 몫의 무게로도 조각은 안 울었다. 무게는 더해져도 발은 하나니까.<br>두 번 왕복했다. 네 번 건넌 셈이다. 마지막 길에는 다리가 젓가락 같았다.<br><br>업혀 온 동료가 미안해했다. 업는 쪽이 편하다고 말해 줬다. 반은 진심이다. 제 발로 걷겠다고 조각 밭에 들어서는 걸 보느니.`,
        ng:`둘째 왕복에서 내공이 바닥을 보였다. 등의 동료가 기울었다.<br><br>동료 발끝이 조각에 끌렸다. 조각 셋이 울었다. 천장이 깨어났다.<br>남은 길을 그냥 달렸다. 둘이 한 몸으로 구르다시피 문을 넘었다. 동료 발뒤꿈치에 조각이 박혔다. 이쪽 몫의 상처다. 뽑는 건 이쪽이 했다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'S', t:'바람길 — 냄새를 나르는 복도',
    x:`좁은 복도에 바람이 분다. 등 뒤에서 앞으로. 냄새가 바람을 탄다.<br><br>
    복도 끝 어둠에 그것들이 있다. 코로 사는 것들. 바람이 이쪽 냄새를 미리 배달하는 중이다.<br>
    바람은 끊긴다. 벽의 깨진 틈들이 숨을 쉬듯, 불다 멎다 한다.<br><br>
    경신술사는 바람을 거슬러 달릴 수 있다. 냄새보다 먼저 도착하면 냄새는 빈 소식이 된다.`,
    o:[
      { l:'① 바람이 멎은 틈에 냄새보다 먼저 간다.', k:'evade', dc:25,
        ok:`바람이 멎는 박자를 쟀다. 숨 여덟 불고 숨 셋 멎는다.<br><br>멎는 숨 셋 동안 복도 반을 갔다. 다시 멎을 때 나머지 반. 이쪽 냄새는 아직 복도 중간에 떠 있다.<br>그것들 옆을 지날 때 그것들은 코를 복도 가운데로 들고 있었다. 오고 있는 냄새 쪽으로. 이미 지나간 몸 쪽이 아니라.<br><br>모퉁이를 돌고 나서 바람이 다시 불었다. 그것들이 빈 냄새를 받아 들고 어리둥절해하는 기척이 등 뒤에 남았다.`,
        ng:`둘째 멎음이 짧았다. 숨 셋이 아니라 하나 반.<br><br>복도 한가운데서 바람이 등을 밀었다. 냄새가 이쪽을 앞질러 배달됐다.<br>그것들이 마중을 나왔다. 벽 틈으로 몸을 구겨 넣고 그것들이 지나가길 기다렸다. 코가 틈 앞에서 벌름거렸다. 틈의 곰팡내가 이쪽을 덮어 줬다. 곰팡이한테 빚졌다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-18, spirit:-18 } },
      { l:'② 벽 틈들의 숨을 읽어 바람 지도를 그린다.', k:'sense', dc:24, wake:1,
        ok:`벽 틈마다 손바닥을 댔다. 트는 틈, 마시는 틈. 복도의 바람은 한 줄이 아니었다.<br><br>마시는 틈 앞에서는 냄새가 벽으로 빨린다. 그 앞을 이어 걸으면 냄새가 그것들한테 안 간다.<br>마시는 틈 열하나를 점으로 이어 복도를 지났다. 동료들도 그 점만 밟았다.<br><br>바람에도 길이 있다는 걸 손바닥이 배웠다. 공기가 가는 길을 읽으면 몸이 가는 길은 그 틈에 그려져 있다. 이제 복도에 들어서면 바람부터 보인다.`,
        ng:`지도를 반쯤 그렸을 때 큰 틈 하나가 숨을 바꿨다. 마시던 틈이 불기 시작했다.<br><br>모아 뒀던 이쪽 냄새를 그 틈이 한꺼번에 뱉었다. 복도가 이쪽 냄새로 찼다.<br>그것들이 사방에서 코를 들었다. 지도고 뭐고 달렸다. 모퉁이에서 하나와 스쳤다. 어깨가 그것의 이빨을 스치고 지나갔다. 옷이 한 줌 뜯겼다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } }
    ] },

  { at:'S', t:'먼지 층 — 일으키면 보이는 것',
    x:`방바닥에 먼지가 담요처럼 쌓였다. 몇 년 치인지 모른다.<br><br>
    빛줄기 하나가 천장 틈에서 내려와 방 한가운데 서 있다. 먼지가 일면 그 빛 속에서 연기처럼 보인다.<br>
    그 빛줄기를 보는 눈이 있다. 방 건너 어둠에서 깜빡이지도 않고.<br>
    발소리는 안 듣는 것 같다. 먼지만 본다.<br><br>
    경신술사 걸음은 먼지를 깨우지 않는다. 바람을 안 만들면 된다.`,
    o:[
      { l:'① 바람 한 올 없이 걸어 빛 옆을 지난다.', k:'evade', dc:25, wake:1,
        ok:`걸음에서 바람을 뺐다. 발을 들 때 천천히, 디딜 때 더 천천히. 옷자락도 손으로 눌렀다.<br><br>빛줄기 옆을 지났다. 먼지는 잠든 채였다. 빛 속에는 아무것도 안 떠올랐다.<br>건너편 문에 닿아 돌아봤다. 어둠의 눈이 여전히 빛줄기만 보고 있었다.<br><br>걸음에서 바람을 빼는 법은 숨에서 소리를 빼는 법과 같은 자리에 있었다. 하나를 익히면 옆의 하나가 따라온다. 몸 안의 지도가 한 칸 넓어졌다.`,
        ng:`옷자락까지는 눌렀는데 머리카락을 못 눌렀다.<br><br>돌아서는 결에 머리카락이 바람을 한 올 만들었다. 먼지 서넛이 떠서 빛 속으로 흘러들었다.<br>어둠의 눈이 움직였다. 빛에서 이쪽으로. 숨을 끊고 벽에 붙었다. 눈이 한참 이쪽 언저리를 더듬다 돌아갔다. 그동안 먼지 하나가 콧등에 앉아 있었다. 재채기를 참은 값으로 눈물이 났다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 } },
      { l:'② 빛줄기 반대편 어둠에 붙어 돈다.', k:'hide', dc:24,
        ok:`빛이 밝을수록 그 옆 어둠은 깊다. 벽을 따라 도는 길은 멀지만 어둠이 이어진다.<br><br>어둠에서 어둠으로, 먼지가 얕게 쌓인 벽 밑만 밟았다. 벽 밑은 바람이 안 통해 먼지가 떡져 있다. 떡진 먼지는 안 뜬다.<br>반 바퀴를 돌아 문에 닿았다.<br><br>어둠의 눈 바로 밑을 지날 때 그것의 숨소리를 들었다. 위에서 모래 떨어지는 소리 같았다. 눈만 있는 게 아니었다. 뭔지는 끝내 안 봤다. 보면 걸음이 흐트러진다.`,
        ng:`벽 밑에서 뭔가를 밟았다. 떡진 먼지가 아니라 부드러운 것.<br><br>그것이 꿈틀했다. 먼지가 확 일었다. 빛까지 안 가도 어둠의 눈은 가까운 먼지도 봤다.<br>눈이 이쪽을 찾기 시작했다. 벽에 붙은 채 숨을 죽였다. 발밑의 부드러운 것이 다리를 타고 오르기 시작했다. 그걸 참는 게 눈을 피하는 것보다 어려웠다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
    ] },

  { at:'S', t:'빈 터 — 달리는 것보다 빠른 것',
    x:`가릴 것 없는 빈 터가 펼쳐졌다. 건너편 바위 그늘까지 백 걸음.<br><br>
    빈 터 가장자리를 그것이 돈다. 달리는 것을 잡는 것. 앞서 간 이들 중 제일 빠른 이가 저 한가운데서 따라잡혔다고 한다.<br>
    그것도 쉰다. 돌다가 멈춰 옆구리를 핥는 시간. 한 바퀴에 한 번.<br><br>
    경신술사의 달리기는 달리기가 아니다. 그래도 백 걸음은 백 걸음이다.`,
    o:[
      { l:'① 그것이 옆구리를 핥는 사이 백 걸음을 끊어 간다.', k:'evade', dc:26,
        doom:{ title:'빈 터', what:'빈 터 너머로 채여 갑니다', dc:20, sec:40,
          text:`첫 핥기에 마흔 걸음. 바위 뒤에 숨었다. 둘째 핥기에 나머지를 갔어야 했다.<br><br>둘째 핥기가 없었다. 그것이 핥는 척만 하고 이쪽을 기다리고 있었다. 예순 걸음째에 세상이 옆으로 흘렀다.<br>목덜미 옷깃이 물렸다. 발이 땅에서 떨어졌다. 그것이 이쪽을 문 채 빈 터를 가로질러 달린다. 바람이 귀에서 운다. 제가 달리는 것보다 빠른 바람.<br><br>동료들이 뒤에서 뛰는 게 보인다. 점점 작아진다.`,
          dieText:`달리는 것을 잡는 것한테는 달리지 말았어야 했다.<br><br>그건 알고 있었다. 마흔 걸음까지는.<br>빈 터 한가운데 신발 두 짝이 가지런하다. 제일 빠른 이의 것 옆에.` },
        ok:`핥기 시작하는 걸 보고 뛰었다. 마흔 걸음에 바위 하나. 멈춰서 돌처럼 섰다.<br><br>그것이 고개를 들고 빈 터를 훑었다. 선 것은 안 보고 움직이는 것만 본다. 다시 핥기 시작했다.<br>남은 예순 걸음을 두 번에 끊어 갔다. 멈출 때마다 돌이 됐다.<br><br>바위 그늘에 들어서서 보니 그것이 이쪽이 멈췄던 자리들을 코로 훑고 있었다. 돌 세운 자리마다. 돌은 냄새까지 돌이 되지는 못한다. 다음에는 더 빨리 끊어야 한다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 그것의 쉬는 박자가 진짜인지부터 본다.', k:'gaze', dc:25,
        ok:`핥는 모습을 한 바퀴 내내 봤다. 혀가 옆구리에 닿을 때 귀가 어디를 향하는지.<br><br>귀는 빈 터를 향해 있었다. 핥기는 쉬기가 아니라 듣기였다. 눈을 쉬게 하고 귀로 사냥하는 시간.<br>그래서 핥을 때는 걷고, 돌 때 뛰었다. 거꾸로. 도는 발소리가 제 귀를 가리는 때가 그것의 진짜 빈틈이었다.<br><br>건너고 나서 동료들에게 일렀다. 저것이 쉬는 때는 없다. 시끄러운 때가 있을 뿐이다.`,
        ng:`보는 데 너무 오래 걸렸다. 한 바퀴, 두 바퀴.<br><br>세 바퀴째에 그것이 도는 반경을 줄였다. 이쪽이 숨은 가장자리 쪽으로. 보는 동안 저쪽도 좁혀 온 것이다.<br>관찰을 버리고 뛰었다. 바위 그늘까지 숨이 터지게 달렸다. 뒤에서 모래 갈리는 소리가 발뒤꿈치까지 왔다가 멀어졌다. 그늘 안은 안 들어온다. 그것만 알아냈다. 몸으로.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'S', t:'삭은 잔교 — 우는 판자',
    x:`어둠 위로 잔교가 걸렸다. 판자가 반은 삭았다. 밟으면 운다. 어떤 판은 부러진다.<br><br>
    잔교 아래 어둠에서 숨소리들이 올라온다. 판자가 울기를 기다리는 숨소리. 우는 자리 바로 밑으로 모이는 기척.<br>
    판자들 중 성한 것과 삭은 것은 색이 거의 같다. 발이 먼저 안다. 발에 무게가 없을 때만.<br><br>
    경신술사가 앞장서는 길이다. 다들 그걸 안다.`,
    o:[
      { l:'① 무게 없는 발로 판자를 읽으며 길을 연다.', k:'evade', dc:25,
        ok:`발끝을 얹으면 판자가 속을 말한다. 성한 판은 대답이 짧고 삭은 판은 대답이 길다.<br><br>짧은 대답만 밟았다. 뒤따르는 동료들을 위해 삭은 판에는 분필 금을 그었다.<br>마흔 장 중 열일곱 장이 삭았다. 열일곱 금을 긋고 건넜다.<br><br>마지막 동료가 건넌 뒤 잔교를 돌아봤다. 금 그은 판 하나에 금이 하나 더 늘어 있었다. 아래에서 그은 금이. 저쪽도 읽고 있었다. 어느 판이 삭았는지를. 위로 올라올 판을.`,
        ng:`열두 장째, 발끝 대답은 짧았는데 속이 비어 있었다. 겉만 성한 판.<br><br>디딘 순간 부러졌다. 다리가 어둠에 무릎까지 빠졌다. 아래에서 숨소리들이 치솟았다.<br>동료가 겨드랑이를 잡아 올렸다. 빠졌던 다리의 신발이 없다. 벗겨 간 것이다. 씹는 소리가 아래서 올라왔다. 신발이라 다행이었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-18 } },
      { l:'② 잔교 밧줄 난간 위로 줄을 타고 건넌다.', k:'steady', dc:24,
        ok:`판자 대신 난간 밧줄을 봤다. 밧줄은 안 운다. 늘어질 뿐이다.<br><br>밧줄 위에 올라 발바닥으로 줄을 감듯 걸었다. 늘어지는 건 내공으로 당겨 받쳤다.<br>판자는 한 장도 안 밟고 건넜다.<br><br>아래 숨소리들이 조용했다. 들을 게 없어서. 건너편에서 동료들에게 밧줄을 팽팽히 당겨 주고 하나씩 매달려 건너게 했다. 우는 판자 위로 조용한 줄 하나가 길이 됐다.`,
        ng:`중간에서 밧줄의 묶인 쪽 말뚝이 기울었다. 줄이 한 뼘 꺼졌다.<br><br>몸이 출렁이며 발바닥이 판자를 스쳤다. 판자 하나가 길게 울었다.<br>아래 숨소리가 그 판 밑으로 모였다. 판 틈으로 뭔가 희끗한 것이 올라오는 걸 보며 남은 줄을 날다시피 건넜다. 손바닥이 밧줄에 쓸려 벗겨졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
    ] },

  { at:'S', t:'심장 소리 — 가슴에 귀를 대는 것',
    x:`길목에 그것이 잠들어 있다. 비켜 갈 틈은 그것 몸뚱이 옆 두 뼘뿐.<br><br>
    그것은 소리로 깨지 않는다. 동료 하나가 돌을 던져 봤다. 안 깼다. 그런데 앞서 간 이는 그 옆을 지나다 잡혔다. 소리도 없이 지났는데.<br>
    가슴이 뛰는 걸 듣는 것이다. 가까이 오는 심장을. 잠든 채로.<br><br>
    경신술사는 심장도 걸음처럼 다룬다. 느리게, 더 느리게.`,
    o:[
      { l:'① 심장을 내공으로 눌러 반 박자로 지난다.', k:'steady', dc:26, wake:1,
        ok:`내공을 가슴에 모아 심장을 감쌌다. 뛰는 걸 막는 게 아니라 깊게 만들었다. 얕고 빠른 박동을 깊고 느린 박동으로.<br><br>두 뼘 틈을 지났다. 그것의 갈비뼈가 이쪽 숨에 닿을 듯했다. 그것의 심장 소리가 이쪽 몸에 울렸다. 크고 느렸다. 이쪽 심장이 거기에 맞춰 더 느려졌다.<br>지나고 쉰 걸음 뒤에야 심장을 풀어 줬다.<br><br>심장도 발이라는 걸 배웠다. 디디는 법이 있고 거두는 법이 있다. 몸 안에서 제일 시끄러운 발 하나를 오늘 길들이기 시작했다.`,
        ng:`틈 한가운데서 그것이 뒤척였다. 놀란 심장이 내공을 뚫고 한 번 크게 뛰었다.<br><br>그것의 눈꺼풀이 반 열렸다. 잠과 사냥 사이의 눈.<br>동료들이 길목 밖에서 일부러 발을 굴렀다. 소리로는 안 깨니까, 깨우지는 않고 이쪽 심장만 가려 준 셈이다. 그 틈에 빠져나왔다. 가슴이 멍든 것처럼 아팠다. 안에서부터.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 내공을 실어 그것의 숨 꼭대기에서 단숨에 넘는다.', k:'evade', dc:25, cost:{ qi:32 },
        ok:`그것의 숨을 봤다. 들숨에 몸통이 부풀면 틈이 한 뼘으로 준다. 날숨 바닥에서 틈이 제일 넓다.<br><br>날숨 바닥에 내공을 터뜨려 단숨에 지났다. 심장이 뛸 틈도 없는 시간. 한 박동 안에 들어갔다 나왔다.<br>심장이 다음 번 뛸 때 이쪽은 이미 길목 밖이었다.<br><br>박동 사이에도 길이 있었다. 좁지만 분명히 있었다. 그 길은 심장이 느린 사람한테만 넓어진다.`,
        ng:`날숨 바닥을 기다리는데 그것이 숨을 멈췄다. 자면서 숨을 참는 것이었다.<br><br>틈이 줄지도 늘지도 않는 시간이 길어졌다. 기다리던 심장이 먼저 뛰었다. 그것의 귀가 움찔했다.<br>참지 못하고 지났다. 반쯤에서 그것의 앞발이 잠결에 휘둘러졌다. 정강이를 스쳤다. 잠결이어서 스친 거다. 깨어 있었으면 정강이가 없었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'S', t:'벽 달리기 — 먹는 자리 옆',
    x:`복도 한가운데서 그것이 먹고 있다. 뭘 먹는지는 안 보는 게 낫다.<br><br>
    바닥으로는 못 지나간다. 먹는 것 주위로 피가 넓게 고였다. 밟으면 소리가 난다. 끈적한 소리.<br>
    벽은 비었다. 벽 높은 데를 옆으로 달리면 피 웅덩이 위를 지난다.<br>
    먹는 동안은 고개를 안 든다. 먹는 소리가 이쪽 발소리를 덮는다.<br><br>
    다만 벽 달리기는 길면 떨어진다. 복도는 길다.`,
    o:[
      { l:'① 내공을 쏟아 벽을 달려 한 번에 지난다.', k:'evade', dc:25, cost:{ qi:36 },
        ok:`내공을 다리에 다 몰았다. 벽에 첫 발을 걸었다.<br><br>옆으로 달렸다. 벽이 바닥이고 바닥이 벽인 시간. 먹는 소리에 발소리를 묻었다.<br>복도 끝에서 바닥으로 내려섰다. 열여덟 걸음을 벽에서 썼다.<br><br>마지막 발이 바닥에 닿는 순간 먹는 소리가 멎었다. 돌아보지 않고 모퉁이를 돌았다. 모퉁이 뒤에서 심장이 그제야 제 박자로 돌아왔다. 벽에 발자국처럼 피 묻은 신발 자국이 몇 개 남았을 것이다. 높은 데라 못 볼 거라 믿는 수밖에.`,
        ng:`열두 걸음째에 벽이 바스러졌다. 삭은 벽이었다.<br><br>발 디딜 힘이 벽을 뚫고 들어갔다. 몸이 떨어졌다. 피 웅덩이 가장자리에. 끈적한 소리가 복도에 울렸다.<br>그것이 고개를 들었다. 입에 문 것이 늘어진 채. 눈이 마주쳤다. 그 눈에는 아무 감정이 없었다. 식사 중의 눈. 다음 식사를 봐 두는 눈. 구르고 일어나 복도 끝까지 달렸다. 쫓아오지는 않았다. 아직 먹을 게 남아서.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, spirit:-20 } },
      { l:'② 먹는 박자가 끊기는 때를 피해 벽을 짧게 끊어 탄다.', k:'evade', dc:26,
        doom:{ title:'먹는 자리', what:'먹는 자리로 끌려갑니다', dc:20, sec:38,
          text:`벽을 세 번에 끊어 타기로 했다. 먹는 소리가 이어질 때만.<br><br>두 번째 구간에서 먹는 소리가 뚝 끊겼다. 벽에 붙은 채 멈췄다. 매달린 손가락이 식어 간다.<br>그것이 고개를 들고 벽을 봤다. 처음부터 알고 있었다는 눈. 식사의 다음 접시를 보는 눈. 앞발이 벽을 짚었다. 생각보다 높이 닿는다.<br>발목이 걸렸다. 벽에서 뜯겨 바닥으로, 피 웅덩이 위로 끌려 내려간다. 먹다 만 것 옆으로.<br><br>동료들이 복도 입구에서 소리를 질러 그것의 귀를 흔들고 있다.`,
          dieText:`먹는 동안은 고개를 안 든다.<br><br>다 먹어 가고 있었다는 게 문제였다.<br>복도의 피 웅덩이가 조금 넓어졌다. 먹는 소리가 다시 시작됐다. 아까보다 싱싱한 소리.`,
        },
        ok:`먹는 소리를 들으며 탔다. 씹을 때 달리고 삼킬 때 멈췄다. 삼키는 동안은 복도가 조용해서.<br><br>세 번 끊어 복도를 다 지났다. 삼킴 두 번, 벽에 매달려 돌이 된 시간 두 번.<br>바닥에 내려서 모퉁이를 돌았다.<br><br>마지막 삼킴이 유난히 길었다. 돌이 된 채로 세었다. 심장 마흔둘. 그 마흔둘 동안 그것과 이쪽은 같은 복도에서 각자 숨을 참고 있었다. 서로 모르는 채. 아니, 한쪽만 모르는 채였기를.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'S', t:'빛 웅덩이 — 어둠만 밟는 길',
    x:`천장이 군데군데 뚫려 빛이 웅덩이처럼 고였다. 빛과 어둠이 바닥에 얼룩졌다.<br><br>
    빛에 들어간 것은 사냥당한다. 저 위 어디서 내려다보는 게 있다. 빛 웅덩이 가장자리마다 긁힌 자국이 둘렀다. 빛 밟은 것을 낚아챈 자국.<br>
    어둠만 밟으면 된다. 다만 구름이 가는지 빛 웅덩이들이 천천히 자리를 옮긴다.<br><br>
    경신술사는 움직이는 디딤도 디딘다. 어둠이라고 다를 것 없다.`,
    o:[
      { l:'① 옮겨 가는 어둠을 따라 디디며 건넌다.', k:'evade', dc:25, wake:1,
        ok:`어둠을 땅으로 보지 않고 물로 봤다. 흐르는 물. 흐름을 따라 걸으면 디딤은 늘 발밑에 있다.<br><br>빛이 다가오면 어둠이 가는 쪽으로 반걸음 먼저 갔다. 쫓기는 게 아니라 같이 흐르는 걸음.<br>방을 다 건넜다. 빛은 한 번도 안 밟았다.<br><br>그림자와 보폭을 맞춘 건 처음이다. 땅이 움직이면 땅의 박자가 내 박자다. 멈춘 땅에서만 걷던 때로는 못 돌아간다. 돌아갈 생각도 없다.`,
        ng:`빛 웅덩이 둘이 갑자기 하나로 합쳤다. 디디려던 어둠이 사라졌다.<br><br>발 반쪽이 빛에 들어갔다. 위에서 바람이 쏟아졌다. 낚아채는 바람.<br>몸을 던져 어둠으로 굴렀다. 어깨 위로 뭔가가 빛을 긁고 지나갔다. 바닥의 긁힌 자국이 하나 늘었다. 이쪽 어깨 바로 옆에. 소매가 세 갈래로 찢어져 있었다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 } },
      { l:'② 빛을 내리는 위쪽 구멍들의 임자부터 본다.', k:'gaze', dc:25,
        ok:`빛이 아니라 빛이 내려오는 구멍을 봤다. 구멍 일곱 개. 그중 둘에서만 가장자리에 발톱이 보였다.<br><br>다섯 구멍은 그냥 구멍이다. 그 다섯이 내리는 빛은 밟아도 되는 빛이다.<br>밟아도 되는 빛과 어둠을 섞어 디디니 길이 세 배로 넓어졌다. 다들 쉽게 건넜다.<br><br>발톱 둘린 구멍 둘 밑을 지날 때만 숨을 죽였다. 위에서 기다리다 지친 한숨 소리가 내려왔다. 빛으로 사냥하는 것도 공치는 날이 있다.`,
        ng:`구멍을 올려다보는데 구멍 하나에서 눈이 마주 내려다봤다.<br><br>올려다보는 얼굴은 빛 속에서 잘 보인다. 이쪽 얼굴이 그랬다.<br>그 구멍의 빛이 이쪽을 따라 움직이기 시작했다. 빛이 아니라 시선이었다. 어둠으로만 내달렸다. 방을 나올 때까지 빛 하나가 등을 쫓아왔다. 문지방까지. 문 안으로는 빛이 못 들어온다. 그래서 문이 있는 거다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
    ] },

  { at:'S1', t:'점액 복도 — 미끄러운 길',
    x:`표본실 구역 복도가 점액으로 덮였다. 벽도 바닥도. 그것들이 지나다니며 바른 것이다.<br><br>
    밟으면 미끄러지고, 미끄러지면 소리가 나고, 소리가 나면 바른 임자가 온다. 점액은 복도 안쪽으로 갈수록 두껍다. 신선하다는 뜻이다.<br>
    동료들 신발이 벌써 두 번 울었다. 찌익, 하고.<br><br>
    경신술사 발은 안 미끄러진다. 누르지 않는 발은 밀리지도 않는다.`,
    o:[
      { l:'① 점액 위를 무게 없이 미끄러지듯 걷는다.', k:'evade', dc:24, wake:1,
        ok:`미끄러짐을 막지 않고 미끄러짐을 탔다. 발을 점액 위에 얹고 밀리는 대로 몸을 실었다.<br><br>걷기와 지치기 사이의 걸음. 소리가 안 났다. 점액이 우는 건 버틸 때다. 버티지 않으니 울 일이 없다.<br>복도 끝까지 세 번의 긴 미끄럼으로 갔다.<br><br>미끄러운 바닥이 빠른 바닥이 됐다. 적이 깔아 둔 것도 디디면 길이다. 동료들에게는 이쪽 지난 자리를 밟으라 했다. 점액이 눌려 길이 나 있었다.`,
        ng:`세 번째 미끄럼에서 점액 밑 턱에 발이 걸렸다.<br><br>몸이 붕 떠서 등으로 떨어졌다. 복도가 찌이익 울었다. 점액 속에서.<br>안쪽에서 바른 임자가 나왔다. 젖은 몸이 벽을 타고 왔다. 일어나려는데 등이 점액에 붙어 안 떨어졌다. 동료가 잡아 뗐다. 옷 등판이 복도에 남았다. 임자가 그 등판을 한참 들여다보는 사이 다들 빠져나왔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 점액이 마른 자리만 이어 디딘다.', k:'steady', dc:24,
        ok:`점액도 마른다. 벽 틈 바람이 닿는 자리마다 가장자리가 하얗게 굳었다.<br><br>굳은 자리만 이어 디뎠다. 사이가 멀면 벽 굳은 데에 손을 짚어 건넜다.<br>느렸지만 한 번도 안 미끄러졌다.<br><br>복도를 나와서 알았다. 마른 자리가 이어진 건 우연이 아니었다. 바람길을 따라 말랐고, 바람길은 숨구멍으로 이어졌다. 숨구멍 앞에서 길이 끝났다. 들여다보지 않고 지나쳤다. 그런 건 안 들여다보는 게 경력이다.`,
        ng:`굳은 줄 알고 디딘 자리가 겉만 굳어 있었다. 껍질이 꺼지며 속 점액이 발목을 삼켰다.<br><br>뽑는데 쭈욱, 하고 복도가 다 듣게 울었다.<br>임자가 왔다. 발목이 덜 빠진 채로 벽 틈에 몸을 구겨 넣었다. 임자가 꺼진 껍질 자리를 오래 어루만졌다. 제 점액이 상한 게 언짢은 모양이었다. 발목의 점액은 사흘을 씻어도 냄새가 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
    ] },

  { at:'S1', t:'감지판 복도 — 무게를 재는 바닥',
    x:`연구동 복도 바닥에 감지판이 깔렸다. 시설이 살아 있던 때의 보안 장치다. 아직 불이 들어와 있다.<br><br>
    무게가 실리면 경보가 운다. 경보가 울면 복도 끝 격벽이 닫힌다. 그리고 경보 소리에 오는 것들이 있다. 장치는 그것들까지 계산에 넣지 못했다.<br>
    판과 판 사이 틈은 손가락 두 개. 디딜 데가 못 된다.<br><br>
    경신술사한테 무게를 재는 바닥은 시험지다. 백지로 내면 된다.`,
    o:[
      { l:'① 감지판 위를 무게 없이 지나간다.', k:'evade', dc:25,
        ok:`판을 밟되 무게를 안 줬다. 발바닥과 판 사이에 내공을 깔았다. 몸이 그 위에 떠 있는 셈.<br><br>판의 불빛이 발밑에서 깜빡이지도 않았다. 백지 답안지. 장치는 아무도 안 지나갔다고 적었다.<br>복도 끝에서 동료들을 봤다. 건널 수 없는 얼굴들.<br><br>격벽 옆 벽장에서 장치 열쇠를 찾아 던져 줬다. 장치를 끈 복도를 다들 그냥 걸어왔다. 이쪽만 어렵게 건넌 셈이 됐다. 손해 본 기분은 아니다.`,
        ng:`스물두 번째 판에서 발뒤꿈치가 반 박자 늦게 떠졌다. 무게가 눈금 하나만큼 실렸다.<br><br>경보가 울었다. 복도가 빨갛게 깜빡이고 격벽이 내려오기 시작했다.<br>굴러서 격벽 밑을 빠졌다. 동료들은 못 들어왔다. 경보 소리에 온 것들이 복도 반대편을 채우는 게 격벽 틈으로 보였다. 격벽이 닫혔다. 돌아서 합류하는 데 한나절 걸렸다. 혼자 걷는 시설은 두 배로 넓었다.`,
        win:{ exp:22, dream:2 }, lose:{ mind:-18, spirit:-18 } },
      { l:'② 죽은 판부터 가려 길을 잇는다.', k:'sense', dc:24,
        ok:`판마다 불빛을 봤다. 성한 판은 불이 고르고 죽은 판은 불이 멎었거나 떤다.<br><br>죽은 판 아홉, 떠는 판 셋. 죽은 판만 이어서 길이 났다. 떠는 판은 안 믿었다. 떠는 건 반쯤 산 거다.<br>다들 죽은 판만 밟고 건넜다.<br><br>마지막 떠는 판 하나가 다 건넌 뒤에 혼자 경보를 반쯤 울리다 꺼졌다. 잠꼬대 같았다. 복도 끝 격벽이 반 뼘 내려오다 말았다. 서두르길 잘했다.`,
        ng:`죽은 줄 알았던 판 하나가 죽은 척이었다. 불만 나간 채 속은 살아 있었다.<br><br>경보가 복도를 찢었다. 격벽이 내려왔다. 다들 뛰었다. 마지막 동료가 격벽 밑으로 미끄러져 들어올 때 발 하나 차이였다.<br>경보 소리에 온 것들이 격벽을 밤새 두드렸다. 두드리다, 나중에는 긁었다. 긁다, 나중에는 조용해졌다. 조용한 게 제일 나빴다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'S1', t:'수직 통풍로 — 들이쉬는 관',
    x:`수직 통풍로를 가로질러야 한다. 지름이 몸 세 개. 건너편에 계속 가는 관이 있다.<br><br>
    통풍로는 숨을 쉰다. 저 아래 무언가의 호흡에 맞춰 공기가 쏟아져 내려갔다가 치솟는다. 들이쉴 때 통풍로는 모든 것을 아래로 당긴다.<br>
    아래는 깊다. 그리고 따뜻하다. 올라오는 바람이 체온이다.<br><br>
    건너는 데 두 걸음. 그 두 걸음이 숨의 어느 틈에 있느냐가 전부다.`,
    o:[
      { l:'① 내쉬는 바람을 타고 건너뛴다.', k:'evade', dc:26,
        doom:{ title:'수직 통풍로', what:'통풍로 아래로 빨려 들어갑니다', dc:20, sec:36,
          text:`내쉬는 바람 꼭대기에서 뛰었다. 바람이 등을 받쳐 줬다. 반까지는.<br><br>반에서 숨이 바뀌었다. 예고 없이. 바람이 떠받치던 손을 거두고 발목을 당겼다.<br>건너편 관 테두리에 손끝이 닿았다 미끄러졌다. 몸이 통풍로 어둠 속으로 내려간다. 벽을 긁어도 손에 걸리는 게 없다. 아래의 따뜻한 바람이 점점 가까워진다. 숨 냄새가 짙어진다.<br><br>위에서 동료들이 밧줄을 던졌다. 밧줄 끝이 어둠 속에서 흔들린다.`,
          dieText:`통풍로는 숨을 쉰다.<br><br>쉬는 것들은 가끔 사레가 들린다. 그걸 셈에 못 넣었다.<br>한참 아래에서 통풍로가 길게, 만족스럽게 내쉬었다. 올라온 바람이 조금 더 따뜻해져 있었다.`,
        },
        ok:`숨을 세 번 보냈다. 들이쉼 여섯, 내쉼 넷. 내쉼이 시작되고 하나 반에서 뛰는 게 답이었다.<br><br>바람이 등을 밀어 줬다. 두 걸음 거리가 한 걸음 반이 됐다. 건너편 관에 손부터 들어갔다.<br>몸을 당겨 넣고 뒤돌아 밧줄을 걸어 줬다. 동료들은 밧줄로 건넜다.<br><br>마지막 동료가 건널 때 아래에서 숨이 한 번 어긋났다. 사레들린 것처럼. 밧줄이 팽팽하게 당겨졌다 돌아왔다. 밧줄 없이 건넌 건 이쪽 하나로 끝나서 다행이었다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 관 테두리를 돌아 안쪽 손잡이로 건넌다.', k:'steady', dc:24,
        ok:`통풍로 안벽에 정비용 손잡이가 반 바퀴 둘러 있다. 녹슬었지만 박혀 있다.<br><br>들이쉴 때는 손잡이를 쥐고 돌이 됐다. 내쉴 때만 옆으로 한 칸씩. 바람이 당길 때 버티는 것보다 바람이 밀 때 가는 게 힘이 덜 든다.<br>반 바퀴를 돌아 건너편 관에 들어갔다.<br><br>손잡이 네 개가 쥐는 중에 흔들렸다. 다음 사람을 위해 흔들린 번호를 외쳐 알려 줬다. 셋째, 일곱째, 열째, 열셋째. 시설의 정비공이 들었으면 수첩에 적었을 것이다. 정비공은 이제 없지만.`,
        ng:`일곱째 손잡이가 뽑혔다. 들이쉬는 중에.<br><br>한 손으로 매달린 채 바람에 다리가 아래로 끌렸다. 신발 한 짝이 벗겨져 어둠으로 내려갔다.<br>한참 뒤에 아래에서 아주 짧게, 씹는 소리가 났다. 내쉼을 기다려 남은 반 바퀴를 건넜다. 맨발 쪽 발바닥이 녹슨 테두리에 긁혀 피가 났다. 피 냄새가 바람을 타고 아래로 내려갔다. 서둘러 자리를 떴다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'S1', t:'유리 바다 — 깨진 표본실',
    x:`대형 표본실이 통째로 깨졌다. 바닥이 유리 조각 바다다. 발 디딜 맨바닥이 없다.<br><br>
    유리 밟는 소리는 멀리 간다. 이 구역에 둥지 튼 것들이 그 소리로 손님을 안다.<br>
    조각 사이사이 깨지지 않은 병 몇 개가 섬처럼 서 있다. 그리고 유리가 잘게 갈린 가루 길이 한 줄 나 있다. 뭔가 배로 밀고 다닌 자국이다.<br><br>
    경신술사 발에는 유리도 안 운다. 다만 마흔 걸음 내내 그래야 한다.`,
    o:[
      { l:'① 유리 위를 소리 없이 디뎌 건넌다.', k:'evade', dc:25, wake:1,
        ok:`조각 하나하나를 보지 않았다. 보면 늦는다. 발바닥에 눈을 맡겼다.<br><br>닿는 순간 조각이 기울려는 방향을 발바닥이 읽고, 그 방향으로 무게를 흘려보냈다. 조각은 눌리지도 돌지도 않았다.<br>마흔 걸음. 유리 바다가 끝까지 잠잠했다.<br><br>건너고 나서 발바닥을 봤다. 상처 하나 없다. 유리를 밟은 게 아니라 유리가 허락한 자리만 빌려 디딘 것이다. 바닥과 흥정하는 법을 발이 먼저 배웠다.`,
        ng:`서른 걸음째에 밟은 조각 밑에서 다른 조각이 튀었다. 쨍, 하고.<br><br>가루 길 쪽에서 미는 소리가 왔다. 빠르게. 배로 유리를 밀며 오는 것.<br>남은 열 걸음을 뛰었다. 유리가 줄줄이 울었다. 문턱을 넘는 순간 그것이 가루 길에서 머리를 들었다. 유리 가루가 덮인 머리였다. 유리 바다의 임자는 유리로 몸을 입고 있었다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 내공으로 동료를 업어 두 몫을 한 발로 옮긴다.', k:'evade', dc:25, cost:{ qi:34 },
        ok:`다친 동료를 업었다. 두 사람 무게를 내공으로 감아 한 사람 발에 실었다.<br><br>무거워진 만큼 더 천천히. 조각이 받는 무게가 실리는 시간을 늘여서 나눴다. 급히 실린 한 몫보다 천천히 실린 두 몫이 조용하다.<br>두 번 왕복해 둘을 옮겼다.<br><br>세 번째는 없었다. 남은 동료들은 이쪽이 디딘 자리에 헝겊을 깔아 가며 제 발로 건넜다. 유리 바다에 헝겊 길이 한 줄 났다. 가루 길과 나란히. 서로 안 겹치게.`,
        ng:`업힌 동료가 중간에 통증으로 몸을 틀었다. 무게가 한쪽으로 쏠렸다.<br><br>발밑 조각이 울었다. 하나가 아니라 밟고 선 자리 전체가.<br>가루 길의 임자가 왔다. 동료를 업은 채로 뛰었다. 유리가 튀고 울고 깨졌다. 문턱을 넘어 둘이 같이 굴렀다. 업힌 동료가 등에서 말했다. 미안하다고. 유리 소리 반은 제 몫이라고. 반이 아니라 반의반쯤이라고 해 줬다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'③ 헝겊과 짐을 깔아 일행의 길을 먼저 놓는다.', k:'bond', dc:24,
        ok:`외투와 담요와 빈 자루를 다 꺼냈다. 유리 위에 한 장씩 깔았다.<br><br>이쪽이 소리 없이 앞서가며 깔고, 동료들이 그 위를 밟고, 마지막 사람이 걷어서 앞으로 넘겼다. 길이 이쪽들과 같이 움직였다.<br>마흔 걸음을 헝겊 여덟 장으로 건넜다.<br><br>다 건너고 외투를 입는데 등판에 유리 가루가 박혀 반짝였다. 별 같다고 동료가 말했다. 털어 내는 데 한참 걸리는 별이었다.`,
        ng:`여섯 장째 담요가 조각 더미 위에서 미끄러졌다. 밟고 선 동료째로.<br><br>동료가 넘어지며 유리 바다에 손을 짚었다. 소리와 피가 같이 났다.<br>임자가 오기 전에 동료를 끌어 일으켜 남은 길을 뛰었다. 담요는 버렸다. 문틈으로 봤다. 임자가 담요를 뒤집어 보고 있었다. 사람 냄새 나는 빈 껍질을. 한참을 그러고 있었다. 담요가 시간을 번 셈이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-16 } }
    ] },

  { at:'S1', t:'산 안개 — 숨을 아끼는 길',
    x:`산성 피가 웅덩이째 증발하는 구역이다. 안개가 허리 높이로 깔렸다. 들이쉬면 목이 탄다.<br><br>
    안개 위로 머리를 내밀고 걸으면 되지만, 그 높이의 공기는 그것들도 쓴다. 냄새가 실려 간다.<br>
    안개 밑으로 기면 숨을 못 쉰다. 구역 끝까지 예순 걸음.<br><br>
    경신술사는 한 숨으로 먼 길을 간다. 숨이 긴 게 아니라 쓰는 데가 적어서다.`,
    o:[
      { l:'① 한 숨을 예순 걸음에 나눠 쓰며 안개 밑을 간다.', k:'evade', dc:25,
        ok:`안개 위에서 숨을 가슴 가득 채웠다. 그리고 안개 밑으로 들어갔다.<br><br>걸음에서 숨 쓸 일을 다 뺐다. 힘쓰는 걸음은 숨을 먹는다. 흐르는 걸음은 안 먹는다. 예순 걸음을 흘렀다.<br>구역 끝 맑은 공기에서 숨을 뱉었다. 뱉은 숨이 뜨거웠다.<br><br>목 안이 하루 종일 칼칼했다. 안개 밑에서도 피부로 스민 모양이다. 그래도 목숨 값으로는 싸다.`,
        ng:`마흔 걸음째에 발이 웅덩이 가장자리를 밟았다. 안개가 확 일었다.<br><br>짙은 안개 한 모금이 코로 들어왔다. 목이 타는 것 같았다. 기침이 터지려는 걸 혀를 깨물어 눌렀다.<br>남은 스무 걸음을 반쯤 정신없이 갔다. 구역을 나와 토하듯 숨을 쉬었다. 목소리가 사흘 쉬었다. 사흘 동안 손짓으로 말했다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 안개의 높낮이를 읽어 숨 쉴 섬을 잇는다.', k:'steady', dc:24, wake:1,
        ok:`안개도 바닥을 따른다. 바닥이 솟은 데는 안개가 얕다. 그런 데서는 고개만 숙이면 맑은 공기다.<br><br>솟은 자리 다섯을 눈으로 이었다. 섬에서 섬으로, 숨에서 숨으로.<br>섬마다 반 숨씩 채우며 예순 걸음을 갔다. 급할 게 없는 길이 됐다.<br><br>숨을 아끼는 법 위에 숨을 나누는 법이 얹혔다. 긴 길은 한 숨으로 가는 게 아니라 숨 쉴 자리를 미리 놓고 가는 것이다. 길 보는 눈이 하나 더 생겼다.`,
        ng:`셋째 섬이 섬이 아니었다. 솟은 바닥인 줄 알았던 게 엎드린 것의 등이었다.<br><br>디딘 순간 등이 꺼지며 안개가 소용돌이쳤다. 그것이 안개 속에서 일어섰다.<br>숨도 못 채우고 남은 길을 뛰었다. 안개를 들이켜며. 구역을 나와 한참 기침했다. 기침 소리를 듣고 또 뭐가 올까 봐 입을 틀어막고 기침했다. 눈물 콧물이 다 났다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-16 } }
    ] },

  { at:'S1', t:'맥박 복도 — 벽이 뛰는 자리',
    x:`여왕 가까운 구역이다. 벽이 뛴다. 느리게, 크게. 시설 전체가 한 심장에 이어진 것 같다.<br><br>
    복도의 그것들은 그 맥박에 맞춰 산다. 맥박이 뛸 때 움직이고, 사이에 멈춘다. 다 같이. 춤처럼.<br>
    박자에 안 맞는 것은 금방 들킨다. 이 복도에서 박자에 안 맞는 건 이쪽들뿐이다.<br><br>
    경신술사는 남의 박자에 걸음을 묻을 줄 안다. 이번 박자는 벽에서 온다.`,
    o:[
      { l:'① 맥박에 걸음을 묻어 그것들 사이를 지난다.', k:'evade', dc:26,
        ok:`벽에 손끝을 대고 맥박을 받았다. 쿵. 사이. 쿵.<br><br>뛸 때 걷고 사이에 멈췄다. 그것들과 같은 박자로. 복도의 그것들 사이를 지나는데 아무도 돌아보지 않았다. 박자가 같은 것은 풍경이다.<br>복도 끝에서 박자를 빠져나왔다.<br><br>빠져나온 다음에도 심장이 한동안 그 박자로 뛰었다. 쿵. 사이. 쿵. 몸에 남의 맥이 묻어 온 것이다. 씻어 내는 데 반나절 걸렸다. 다 안 씻겼을지도 모른다.`,
        ng:`복도 한가운데서 맥박이 반 박자 빨라졌다. 여왕 쪽에서 무슨 일이 있었는지.<br><br>이쪽 걸음만 헌 박자에 남았다. 그것들이 일제히 멈춰 이쪽을 봤다. 풍경이 아니게 된 것을.<br>달렸다. 그것들이 새 박자로 쫓아왔다. 쿵쿵. 쿵쿵. 격벽 틈으로 빠져 바위틈 같은 데 숨었다. 벽의 맥박이 틈 안까지 울렸다. 숨는 내내 그 박자를 들었다. 지금도 가끔 들린다.`,
        win:{ exp:22, dream:2 }, lose:{ mind:-20, spirit:-20 } },
      { l:'② 맥박의 근원이 어느 쪽인지 벽을 짚어 가린다.', k:'gaze', dc:25,
        ok:`맥박에도 상류와 하류가 있다. 벽 두 곳에 손을 대고 어느 쪽이 먼저 뛰는지 쟀다.<br><br>왼쪽 벽이 반의반 박자 빨랐다. 여왕은 왼쪽이다. 길은 오른쪽으로 잡았다.<br>맥박이 점점 얕아지는 쪽으로 걸었다. 벽이 조용해질수록 그것들도 성글어졌다.<br><br>완전히 조용한 벽에 닿았을 때 뒤를 봤다. 지나온 복도가 아직 뛰고 있었다. 시설의 절반은 심장이고 절반은 시체다. 시체 쪽이 사람 다닐 길이다.`,
        ng:`두 벽의 박자가 똑같았다. 가릴 수가 없었다.<br><br>한참 재는 사이 등 뒤 벽이 새로 뛰기 시작했다. 세 번째 박자. 근원이 움직인 것이다. 이쪽으로.<br>재기를 버리고 박자 없는 쪽으로 뛰었다. 등 뒤에서 벽들이 차례로 깨어나 뛰는 소리가 따라왔다. 복도 전체가 심장이 되기 전에 빠져나왔다. 벽에 댔던 손바닥이 밤새 욱신거렸다. 박자대로.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S1', t:'냉동고 — 얼음 밑의 잠',
    x:`시설 냉동 창고다. 장치가 반쯤 살아서 바닥에 얼음이 한 자 두께로 깔렸다.<br><br>
    얼음 밑에 그것이 보인다. 큰 것. 얼어붙은 채다. 눈을 뜨고. 착륙 때 들어와 여기서 멈춘 모양이다.<br>
    얼음은 금 가는 소리를 멀리 보낸다. 그리고 금은 온기를 따라간다. 사람 발은 온기다.<br><br>
    건너편 문까지 서른 걸음. 얼음 밑의 눈이 길을 따라 나 있다. 다 이쪽 길을 보고 있다.`,
    o:[
      { l:'① 온기를 발에 안 남기고 얼음을 건넌다.', k:'evade', dc:26,
        doom:{ title:'냉동고', what:'얼음 밑으로 끌려 들어갑니다', dc:20, sec:38,
          text:`스무 걸음까지 얼음은 조용했다. 스물한 걸음째에 발밑에서 쩍, 소리가 났다.<br><br>금이 아니었다. 얼음 밑에서 올라온 소리였다. 발밑의 눈이 움직였다. 얼어붙은 게 아니라 얼음을 입고 있던 것이다.<br>얼음이 꺼지며 찬물보다 찬 손이 발목을 감았다. 몸이 얼음 밑으로 끌려 내려간다. 얼음 천장 너머로 동료들의 그림자가 일렁인다.<br><br>그것의 눈이 바로 앞에 있다. 반갑다는 눈이다. 오래 기다렸다는 눈.`,
          dieText:`얼음 밑에서 몇 년을 기다렸는지 모른다.<br><br>기다림이 끝났다.<br>얼음은 다시 얼었다. 이번에는 밑에 둘이 있다. 하나는 눈을 뜨고, 하나는 감고.`,
        },
        ok:`신발을 벗고 헝겊을 세 겹 감았다. 온기가 얼음에 바로 닿지 않게. 그리고 걸음마다 발을 얼음에 반 숨만 두고 거뒀다.<br><br>얼음은 금 하나 없이 서른 걸음을 받아 줬다.<br>문턱에 올라 돌아봤다. 얼음 밑의 눈이 이쪽이 아니라 이쪽이 걸어온 길을 보고 있었다. 길에 온기가 안 남아서, 어디로 갔는지 모르는 눈이었다.<br><br>발이 시려서 한참 주물렀다. 시린 발이 산 발이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 얼음이 두꺼운 자리를 소리로 가려 걷는다.', k:'sense', dc:25,
        ok:`작은 조각을 얼음 위로 미끄러뜨렸다. 구르는 소리가 두꺼운 데서는 낮고 얇은 데서는 맑다.<br><br>낮은 소리 자리만 이어 걸었다. 두꺼운 얼음은 온기도 천천히 받는다.<br>얼음 밑의 눈 위를 지날 때는 조각 소리도 멈췄다. 다들 숨을 죽이고 그 구간을 넘었다.<br><br>문을 닫기 전에 마지막으로 봤다. 미끄러뜨린 조각들이 얼음 위 여기저기 멈춰 있었다. 밑에서 보면 별자리 같을 것이다. 그것이 심심하지 않기를.`,
        ng:`조각 하나가 얇은 자리에서 멈췄다. 가지러 갈 수도 없고 소리는 이미 났다.<br><br>그 자리 밑에서 얼음이 안쪽부터 울기 시작했다. 누가 얼음을 두드리는 소리. 천천히, 꾸준히.<br>남은 길을 서둘렀다. 서두른 발에 온기가 실렸다. 등 뒤로 금 가는 소리가 따라왔다. 문을 닫는 순간까지. 닫고 나서도 문 밑으로 냉기가 혀처럼 들어왔다 나갔다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
    ] },

  { at:'S2', t:'늪 위 질주 — 잎에서 잎으로',
    x:`양치 늪이 앞을 막았다. 물 반 잎 반. 큰 잎들이 수면에 떠 있다.<br><br>
    잎은 사람을 못 받친다. 받치는 건 잎이 가라앉기 전까지의 한순간뿐이다.<br>
    물속에 긴 것들이 다닌다. 잎이 눌리는 그림자를 밑에서 보고 있다.<br><br>
    경신술사는 가라앉기 전에 다음 잎에 가 있으면 된다는 걸 안다. 말로는 쉽다.`,
    o:[
      { l:'① 내공을 몰아 잎에서 잎으로 늪을 달린다.', k:'evade', dc:26, cost:{ qi:38 }, wake:1,
        ok:`내공을 발끝에 몰고 첫 잎을 찼다. 잎이 가라앉는 속도보다 발이 떠나는 속도가 빨랐다.<br><br>잎 열아홉 장. 눈은 세 장 앞을 보고 발은 지금 장을 스쳤다. 물속 긴 것들이 눌린 그림자를 쫓아왔지만 그림자는 늘 세 장 뒤에 있었다.<br>건너편 둔덕에 내려섰다.<br><br>달리는 동안 몸이 비었다. 무게도 생각도 없이 길만 남았다. 그 빈 몸을 한 번 겪고 나면 다시는 못 잊는다고 들었다. 맞는 말이었다.`,
        ng:`열네 장째 잎이 반 장이었다. 찢어진 잎.<br><br>발이 물을 짚었다. 반 뼘. 그 반 뼘에 물속 긴 것이 닿았다. 발바닥을 스치는 비늘.<br>차고 올라 남은 잎을 정신없이 건넜다. 둔덕에 구르며 닿았다. 뒤에서 잎 열아홉 장이 차례로 물밑으로 당겨져 내려갔다. 긴 것들이 화풀이하는 모양이었다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-14 } },
      { l:'② 가라앉는 잎을 미리 셈해 쉬는 잎을 고른다.', k:'steady', dc:24,
        ok:`잎도 다 같은 잎이 아니다. 뿌리 줄기가 밑에 걸린 잎은 반쯤 디딜 만하다.<br><br>그런 잎 다섯 장을 멀리서 가려 뒀다. 다섯 장을 쉼표 삼아, 사이사이는 빠르게.<br>쉼표마다 반 숨씩 고르며 건넜다. 물속 긴 것들은 쉼표 잎 밑에는 못 들어왔다. 줄기가 얽혀 있어서.<br><br>건너고 보니 그 다섯 장만 잎 가장자리가 닳아 있었다. 먼저 건넌 누군가도 같은 잎을 골랐던 것이다. 그이가 어디까지 갔는지는 모른다. 잎은 다섯 장 다 남아 있었다. 좋은 징조로 치기로 했다.`,
        ng:`쉼표 둘째 장의 줄기가 삭아 있었다. 디딘 순간 잎째 돌았다.<br><br>허리까지 빠졌다. 물속에서 긴 것이 다리를 감았다 풀었다. 재 보는 것이다. 먹을 만한가.<br>동료가 장대를 뻗었다. 잡고 나왔다. 바지에 비늘 자국이 눌려 있었다. 감았던 자리에. 먹을 만하다는 결론이 나기 전에 나와서 다행이었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
    ] },

  { at:'S2', t:'철사 위 — 울타리 꼭대기 길',
    x:`울타리가 늪지대를 가로질러 건너편 둔덕까지 이어진다. 밑은 물과 진창이다.<br><br>
    맨 위 철사 한 줄이 길이다. 팽팽하다. 흔들리면 운다. 울면 무리가 온다. 무리는 울타리 우는 소리를 저녁 종처럼 안다.<br>
    줄 위 서른 걸음. 밑의 진창에는 발자국들이 기다린다. 세 발가락.<br><br>
    경신술사한테 줄은 길이다. 우는 줄이라는 것만 다르다.`,
    o:[
      { l:'① 줄이 울지 않게 줄 위를 걷는다.', k:'evade', dc:26, wake:1,
        ok:`줄이 우는 건 눌렸다 튕길 때다. 누르지 않으면 튕길 것도 없다.<br><br>발바닥 가운데로 줄을 받고, 무게는 내공이 받았다. 줄은 이쪽을 바람 정도로 알았을 것이다.<br>서른 걸음을 걸었다. 줄은 끝까지 팽팽한 침묵이었다.<br><br>내려서서 줄을 돌아봤다. 흔들림 하나 없다. 지나간 자리가 없는 길. 자국 없는 걸음이 여기서는 예의가 아니라 목숨이다. 그 두 가지가 같아지는 데까지 왔다.`,
        ng:`스물다섯 걸음째에 바람이 불었다. 줄이 바람에 제가 먼저 울었다.<br><br>이쪽 탓이 아닌데 무리한테는 그게 그거다. 저녁 종이 울렸으니까.<br>진창 쪽에서 세 발가락들이 모여드는 소리가 났다. 남은 다섯 걸음을 뛰어 둔덕 수풀로 굴렀다. 무리가 울타리 밑에 모여 빈 줄을 올려다봤다. 바람한테 속은 걸 모르는 채. 바람한테 고마운 건 이쪽이고.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 } },
      { l:'② 줄의 장력을 미리 읽어 우는 구간을 가린다.', k:'sense', dc:24,
        ok:`줄을 손끝으로 아주 살짝 눌러 봤다. 구간마다 팽팽함이 다르다. 말뚝이 삭은 구간은 줄이 늘어져서 잘 운다.<br><br>늘어진 구간 둘을 외웠다. 거기서는 걸음을 더 줄이고 숨도 줄였다.<br>팽팽한 구간에서는 제 걸음으로 갔다. 줄 전체를 한 가지 조심으로 건너는 것보다 빠르고 조용했다.<br><br>줄에도 지도가 있었다. 당겨 보지 않아도 손끝 하나면 그려지는 지도. 다음 줄부터는 그리는 시간이 반으로 줄 것이다.`,
        ng:`읽는 중에 말뚝 하나가 손끝 무게에 기울었다. 삭은 게 아니라 뽑혀 있던 말뚝.<br><br>줄 전체가 출렁이며 길게 울었다. 저녁 종이 제대로 울렸다.<br>줄 타기를 접고 진창 가장자리를 달려 돌았다. 무리가 종소리 난 자리로 모이는 사이에. 돌아가는 길이 세 배였고, 진창이 신발을 두 번 벗겨 먹었다. 두 번 다 도로 꺼냈다. 세 발가락 자국 옆에서.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
    ] },

  { at:'S2', t:'바람 아래 — 코앞의 무리',
    x:`수풀 너머에 무리가 쉬고 있다. 바람이 이쪽 등에서 저쪽으로 분다. 최악의 방향이다.<br><br>
    돌아가려면 반나절. 가로지르면 백 걸음. 백 걸음 내내 이쪽 냄새가 먼저 가서 인사할 것이다.<br>
    바람은 가끔 죽는다. 수풀이 잠잠해지는 몇 숨.<br><br>
    경신술사는 바람 죽는 틈을 걸음으로 잇는다. 냄새는 바람 없이는 못 걷는다.`,
    o:[
      { l:'① 바람이 죽은 틈만 이어 무리 옆을 지난다.', k:'hide', dc:25,
        ok:`수풀 끝이 멎는 걸 보고 움직였다. 바람이 죽으면 걷고, 살아나면 그 자리의 수풀이 됐다.<br><br>무리 옆 쉰 걸음 거리를 그렇게 지났다. 하나가 코를 들었을 때는 바람이 막 죽은 뒤였다. 코에 닿는 건 제 무리 냄새뿐이었을 것이다.<br>백 걸음이 끝났다.<br><br>지나고 나서 바람이 길게 살아났다. 이쪽 냄새가 뒤늦게 무리에 닿았겠지만, 냄새만 가고 몸은 없는 소식이다. 무리가 빈 수풀을 뒤지는 소리를 등 뒤로 들었다.`,
        ng:`바람 죽은 틈이 생각보다 짧았다. 걸음 중간에 바람이 살아났다.<br><br>냄새가 실려 갔다. 무리 전체가 일어서는 소리. 수풀에 몸을 던지고 굳었다.<br>무리가 냄새의 길을 거슬러 왔다. 바로 옆 수풀까지. 콧김이 잎을 흔드는 게 보였다. 그때 저쪽 늪에서 물새가 날아올랐고, 무리가 그쪽으로 몰려갔다. 물새한테 빚졌다. 평생 물새는 안 잡아먹기로 했다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-18 } },
      { l:'② 내공으로 백 걸음을 바람보다 빨리 끊는다.', k:'evade', dc:26, cost:{ qi:36 },
        ok:`바람이 등에서 어깨를 민다. 냄새가 실려 가는 속도는 그 바람 속도다.<br><br>그보다 빨리 달리면 냄새가 이쪽 뒤에 처진다. 내공을 터뜨려 백 걸음을 한 호흡에 끊었다.<br>무리 옆을 지날 때 이쪽 냄새는 아직 서른 걸음 뒤에서 오고 있었다.<br><br>수풀을 벗어나 속도를 풀었다. 처졌던 냄새가 뒤늦게 도착해 이쪽을 지나쳐 갔다. 제 냄새한테 추월당하는 기분은 묘했다. 무리는 끝까지 아무것도 몰랐다.`,
        ng:`여든 걸음째에 발밑에서 마른 가지가 터졌다. 속도가 소리를 만들었다.<br><br>무리가 소리에 일어났다. 냄새보다 빠른 건 소리였다. 그걸 셈에서 뺐다.<br>남은 스무 걸음에 추격이 붙었다. 둔덕 바위 틈까지 반 발 차이로 들어갔다. 틈 밖에서 발톱이 바위를 긁는 소리가 한참 났다. 바위한테도 빚졌다. 갚을 길 없는 빚이 자꾸 는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'S2', t:'진창 — 자국이 말하는 땅',
    x:`숙영지로 돌아가는 길에 진창이 넓게 펼쳐졌다. 밟으면 자국이 깊게 남는 땅.<br><br>
    자국은 방향을 말한다. 숙영지 쪽으로 난 사람 발자국은 무리에게 지도가 된다. 무리는 자국을 읽는다. 끝까지 따라 읽는다.<br>
    돌아가는 길은 없다. 밤이 오고 있다.<br><br>
    경신술사 발은 진창에도 자국을 안 판다. 다섯 명 중에 그런 발은 하나뿐이다.`,
    o:[
      { l:'① 자국 없이 건너가 건너편에서 디딤돌을 놓아 준다.', k:'evade', dc:25, wake:1,
        ok:`이쪽이 먼저 자국 없이 건넜다. 진창 위를 스치듯.<br><br>건너편 돌무더기에서 넓적한 돌을 날라 진창에 박았다. 징검다리. 동료들이 돌만 밟고 건넜다.<br>마지막에 돌을 하나씩 걷어 치웠다. 사람 지난 흔적은 돌 눌린 자국 몇 개뿐. 그건 방향을 말하지 않는다.<br><br>자국을 안 남기는 것에서 남의 자국을 지워 주는 것으로. 혼자 쓰던 재주가 다섯 명의 재주가 되는 길을 하나 찾았다.`,
        ng:`돌을 놓는 중에 이쪽 발이 처음으로 진창에 잡혔다. 돌 무게까지 더해진 탓이다.<br><br>자국 하나가 깊게 났다. 숙영지 방향으로.<br>지울 방법이 없었다. 밤에 무리가 그 자국을 읽으러 왔다. 자국 하나로는 지도가 안 되는지 진창 가장자리를 밤새 서성이다 갔다. 하나였기에 망정이지 하는 얘기를 아무도 입 밖에 안 냈다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-16 } },
      { l:'② 모두의 자국을 거꾸로 걷게 해 방향을 속인다.', k:'steady', dc:24,
        ok:`자국을 안 남길 수 없다면 거짓말을 남기면 된다. 다들 뒤로 걸었다.<br><br>발끝과 발꿈치가 바뀐 자국은 반대 방향을 가리킨다. 숙영지를 등지고 가는 지도가 그려졌다.<br>진창이 끝나는 바위부터는 제대로 걸어 숙영지로 돌았다.<br><br>새벽에 무리가 자국을 읽고 반대쪽으로 몰려가는 소리를 들었다. 발자국이 한 말을 그대로 믿는 것들이다. 순진한 데가 있다. 그 순진함이 언제까지 갈지는 모르지만.`,
        ng:`뒤로 걷던 동료 하나가 진창 구덩이에 빠졌다. 허리까지.<br><br>건지는 동안 구덩이 둘레가 온통 제대로 된 자국 밭이 됐다. 거짓말 한가운데 진실이 뭉텅이로 찍혔다.<br>무리는 영리했다. 뭉텅이 자국에서 거꾸로 자국의 거짓을 알아챘다. 숙영지 쪽을 반쯤 읽어 냈다. 그날 밤 보초를 두 배로 세웠다. 아무도 제대로 못 잤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S2', t:'큰 것의 물 — 수면 위 외길',
    x:`승강기 섬으로 가는 마지막 물길이다. 잔잔한 수면이 백 걸음. 다리도 뗏목도 없다.<br><br>
    이 물은 큰 것의 물이다. 물결 하나면 온다. 저번에 건너편 기슭에서 큰 것이 반나절을 꼼짝 않고 서 있는 걸 봤다. 기다리는 법을 아는 것이다.<br>
    지금 수면에 큰 것은 없다. 없다는 게 더 무섭다.<br><br>
    경신술사가 물 위를 달릴 수 있는 거리의 끝이 백 걸음이다. 딱 끝.`,
    o:[
      { l:'① 물결 없이 수면 백 걸음을 내달린다.', k:'evade', dc:26,
        doom:{ title:'큰 것의 물', what:'물 밑으로 끌려 들어갑니다', dc:20, sec:35,
          text:`일흔 걸음까지 물은 유리였다. 일흔한 걸음째에 유리 밑에 그림자가 떴다.<br><br>수면과 나란히, 같은 속도로. 처음부터 밑에서 따라오고 있었던 것이다. 물결을 기다린 게 아니라 지치기를 기다린 것.<br>일흔아홉 걸음째에 발끝이 반 치 깊게 디뎌졌다. 그걸로 충분했다. 물이 산처럼 일어서며 몸이 공중에 떴다가, 거꾸로 물 밑으로 끌려 들어간다.<br><br>물속은 생각보다 밝다. 위로 멀어지는 수면이 은박지처럼 반짝인다. 그 반짝임 사이로 동료들 그림자가 뛰어다닌다.`,
          dieText:`백 걸음이 끝이라는 건 맞는 셈이었다.<br><br>그 물이 백 걸음짜리 물이 아니었을 뿐이다.<br>수면은 금방 유리로 돌아갔다. 승강기 섬은 그대로 거기 있다. 물 건너에. 백 걸음 너머에.`,
        },
        ok:`달리기 전에 신발을 벗어 동료에게 맡겼다. 맨발이 물을 덜 누른다.<br><br>내공을 아껴 썼다. 처음 서른 걸음은 칠 할로, 가운데는 오 할로, 마지막 서른 걸음에 남긴 것을 다 썼다.<br>섬 기슭 바위에 올라서는 순간 등 뒤 수면이 낮게 부풀었다 가라앉았다. 아슬아슬한 마중이었다.<br><br>밧줄을 나무에 묶어 물 위로 던져 걸었다. 동료들은 밧줄에 매달려 건넜다. 물에 몸을 반 담근 채. 큰 것은 다시 안 왔다. 헛물켠 자리에는 한동안 안 오는 것들이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 내공으로 물 위에 선 채 큰 것의 자리부터 살핀다.', k:'evade', dc:25, cost:{ qi:38 },
        ok:`기슭에서 열 걸음만 물로 나가 섰다. 수면에 선 채로 물을 읽었다.<br><br>물에는 흐름이 있고 큰 것이 있는 자리는 흐름이 비켜 간다. 왼쪽 깊은 데가 비어 있었다. 비켜 가는 자리. 거기 있다.<br>오른쪽 얕은 흐름을 따라 비스듬히 백서른 걸음. 멀어도 그 길로 건넜다.<br><br>건너편에서 왼쪽 깊은 데를 봤다. 수면 밑에 산 같은 그림자가 미동도 없었다. 곧은 백 걸음은 저 산 위를 지나는 길이었다. 길은 짧은 게 아니라 비어 있는 게 좋은 길이다.`,
        ng:`물 위에 선 지 다섯 숨 만에 발밑 흐름이 바뀌었다. 비켜 가던 흐름이 이쪽으로 굽었다.<br><br>읽히는 건 이쪽이었다. 서 있는 것은 물 위에서 제일 눈에 띄는 것이다.<br>기슭으로 물러나 반나절을 기다렸다 밤에 건넜다. 밤 물은 차고 길었다. 다들 입술이 파래져서 섬에 닿았다. 떨면서도 아무도 불평하지 않았다. 낮에 그 그림자를 다 봤으니까.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } }
    ] },

  { at:'S2', t:'갈대 끝 — 흔들리면 안 되는 길',
    x:`키 큰 갈대밭이 둔덕과 둔덕 사이를 메웠다. 지나가면 갈대 끝이 흔들린다.<br><br>
    무리는 갈대밭에 안 들어온다. 밖에서 본다. 갈대 끝이 흔들리는 줄을 보고, 그 줄이 나올 자리를 입 벌리고 기다린다.<br>
    바람이 불면 온 밭이 흔들린다. 그때는 줄이 안 보인다.<br><br>
    경신술사는 갈대 사이로도 몸을 흘릴 줄 안다. 바람 없이도 줄을 안 만들 수 있나. 그게 문제다.`,
    o:[
      { l:'① 갈대를 가르지 않고 사이로 몸을 흘려 지난다.', k:'evade', dc:26,
        ok:`갈대를 밀지 않았다. 갈대가 선 모양 사이로 몸 쪽을 맞췄다. 어깨를 돌리고, 허리를 비우고.<br><br>몸이 지나가도 갈대는 제자리였다. 흔들리는 건 이쪽 옷자락뿐이고 그건 갈대 밑동 높이다. 끝은 조용했다.<br>밭을 다 지나 둔덕 그늘로 들었다.<br><br>밖에서 기다리던 무리가 보였다. 갈대밭 출구마다 하나씩 입을 벌리고 있었다. 줄이 안 나오는 밭을 보는 얼굴들. 밭이 사람을 삼켰다고 믿는 눈치였다. 반쯤은 맞는 말이 됐으면 좋겠다. 소문은 방패니까.`,
        ng:`밭 한가운데서 새 둥지를 쳤다. 갈대 사이에 걸린 둥지. 새들이 터지듯 날아올랐다.<br><br>새가 난 자리는 줄보다 또렷한 표적이다. 무리가 그 자리를 보고 짖기 시작했다.<br>둥지 자리에서 직각으로 꺾어 밭을 비스듬히 뚫었다. 무리가 기다리던 출구가 아닌 데로 나왔다. 가시덤불 쪽. 덤불을 뚫는 값으로 팔다리가 다 긁혔다. 출구를 잘못 고른 게 아니라 출구가 아닌 데라 산 거다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 바람이 밭을 흔드는 동안만 끊어 간다.', k:'gaze', dc:24, wake:1,
        ok:`바람을 봤다. 바람은 밭 저쪽 끝에서 이쪽으로 물결처럼 온다. 오는 게 보인다.<br><br>물결이 이쪽 자리를 덮는 동안만 걸었다. 온 밭이 흔들릴 때 이쪽 줄은 그 속에 묻힌다. 물결이 지나가면 갈대와 같이 멈췄다.<br>바람 다섯 물결에 밭을 다 건넜다.<br><br>바람을 기다리던 눈이 바람을 읽는 눈이 됐다. 바람이 어디서 일어나 어디로 가는지, 밭 전체가 한 장의 지도로 보였다. 그 지도는 매 순간 새로 그려진다. 읽는 눈만 있으면 평생 마르지 않는 지도다.`,
        ng:`넷째 물결이 밭 중간에서 죽었다. 바람이 이쪽까지 안 왔다.<br><br>걷던 반 걸음이 밭의 정적 속에 혼자 흔들렸다. 무리가 그 줄을 봤다.<br>짖는 소리가 밭을 둘러쌌다. 엎드려서 짐승처럼 기었다. 갈대 밑동 사이로. 밑동 높이는 밖에서 안 보인다. 반나절을 기어 밭을 빠졌다. 손바닥과 무릎이 갈대 그루터기에 다 긁혔다. 기는 법도 길이라면 길이었다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-16 } }
    ] },

  { at:'S2', t:'승강기 지붕 — 흔들리면 안 되는 상자',
    x:`낡은 승강기에 닿았다. 상자가 통로에 반쯤 걸린 채 쇠줄 하나에 매달려 있다.<br><br>
    상자에 타야 한다. 그런데 상자가 흔들리면 쇠줄이 도르래에서 운다. 그 소리가 정원 전체에 종처럼 퍼진다. 마지막 종이 될 수도 있다. 여기까지 와서.<br>
    상자 지붕으로 내려서는 길은 통로 턱에서 한 길 반.<br><br>
    경신술사가 먼저 내려 상자를 받치는 수밖에 없다. 흔들리지 않게. 다섯 명 몫으로.`,
    o:[
      { l:'① 무게 없이 지붕에 내려 상자의 흔들림을 죽인다.', k:'evade', dc:25, wake:1,
        ok:`턱에서 몸을 떨궜다. 지붕에 닿는 순간 무게를 내공으로 받아 상자에 한 톨도 안 넘겼다.<br><br>상자는 미동도 없었다. 지붕에 선 채로 동료들을 하나씩 받았다. 떨어지는 무게를 이쪽 몸이 먼저 받아 반으로 줄여 상자에 흘렸다. 상자가 아주 천천히, 울지 않을 만큼만 가라앉았다.<br>다섯이 다 탔다. 쇠줄은 끝까지 침묵했다.<br><br>무게를 받아서 나누는 것. 제 무게를 지우는 재주가 남의 무게를 받는 재주로 자랐다. 이 상자 지붕 한 평이 그 교실이었다.`,
        ng:`셋째 동료가 반 박자 일찍 뛰었다. 받을 자세가 덜 된 채로 받았다.<br><br>상자가 한 뼘 출렁였고 쇠줄이 도르래에서 길게 울었다. 종이 쳐졌다.<br>정원 곳곳에서 대답이 왔다. 울음, 발소리, 물 가르는 소리. 나머지 둘은 그냥 뛰어내렸다. 상자가 울든 말든. 다 타자마자 상자를 내렸다. 내려가는 내내 위 통로 턱에 그것들이 모여 내려다보는 소리가 들렸다. 턱을 긁는 발톱 소리도.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 쇠줄에 기름을 먹여 도르래 소리부터 재운다.', k:'steady', dc:24,
        ok:`짐에서 기름병을 꺼냈다. 등잔 기름이지만 기름은 기름이다.<br><br>통로 턱에서 쇠줄을 따라 도르래까지 기어올라 축에 기름을 먹였다. 반 병. 남은 반은 줄이 도르래에 얹히는 홈에.<br>다들 탈 때 상자가 흔들렸지만 도르래는 울지 않았다. 기름 먹은 쇠는 과묵하다.<br><br>내려가는 길도 조용했다. 낡은 승강기가 평생 처음으로 소리 없이 일한 날이었을 것이다. 마지막 일이기도 했고.`,
        ng:`기름을 먹이다 반 병을 상자 지붕에 쏟았다. 지붕이 미끄럼판이 됐다.<br><br>내려서던 동료가 지붕에서 미끄러져 상자 모서리를 잡고 매달렸다. 상자가 크게 출렁이고 쇠줄이 울었다.<br>급한 대로 다 태우고 바로 내렸다. 종소리의 대답들이 통로 위에 모이는 소리를 들으며. 상자 바닥에 다들 주저앉아 있었다. 기름 쏟은 이쪽만 서 있었다. 벌서듯이.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } },
      { l:'③ 동료마다 떨어질 자리와 박자를 정해 준다.', k:'bond', dc:24,
        ok:`지붕의 네 귀퉁이와 가운데. 다섯 자리를 정했다. 무게가 한쪽에 몰리지 않는 그림.<br><br>박자도 정했다. 상자가 미세하게 흔들렸다 돌아오는 순간, 그 되돌아오는 힘에 맞춰 내리면 흔들림이 서로 지워진다.<br>하나, 둘. 다섯이 다섯 자리에 내렸다. 상자는 숨 한 번 크기로만 출렁이고 말았다.<br><br>쇠줄은 안 울었다. 다섯 명이 한 몸처럼 움직인 값이다. 상자 안에서 누가 작게 웃었다. 다들 따라 웃었다. 소리는 안 내고. 여기서는 웃음도 몸으로만 웃는다.`,
        ng:`박자는 맞았는데 자리가 틀렸다. 넷째 동료가 남의 자리에 내렸다.<br><br>한 귀퉁이에 둘. 상자가 그쪽으로 기울며 줄이 짧게 울었다.<br>대답이 오기 전에 서둘러 내렸다. 반쯤 내려갔을 때 위에서 뭔가가 상자 지붕으로 뛰어내렸다. 쿵. 지붕 판자 하나가 휘었다. 다행히 뚫리지는 않았다. 바닥에 닿자마자 다들 상자에서 쏟아져 나왔다. 지붕 위의 것은 상자와 같이 어둠에 남겨 두고.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } }
    ] }
]);

// ── 환영술사 (illusion) · 마력 ──────────────
kJob('illusion', 'S', [
  { at:'S', t:'미끼 모양 — 두 번은 안 속는 것',
    x:`길목을 그것이 지킨다. 어제 동료 모양의 환영으로 한 번 속였다. 환영이 찢기는 걸 다들 봤다.<br><br>
    오늘 그것은 어제 그 자리에 있다. 그리고 어제처럼 고개를 돌리지 않는다. 환영이 지나가도 눈만 좇고 몸은 안 간다.<br>
    배운 것이다. 모양은 먹을 게 없다는 걸.<br><br>
    환영술사는 속임수가 낡는 속도를 안다. 여기 것들은 그 속도가 사람보다 빠르다.`,
    o:[
      { l:'① 마력으로 환영에 무게를 입혀 발소리까지 딸려 보낸다.', k:'evade', dc:25, cost:{ mana:30 },
        ok:`모양만으로는 안 된다. 환영의 발밑에 마력을 깔아 바닥을 울리게 했다.<br><br>모양이 가고, 발소리가 가고, 돌조각이 환영 발끝에 차여 굴렀다. 그것이 몸째 돌아섰다. 무게 있는 것은 먹을 것이 있다.<br>그것이 환영을 쫓는 사이 길목을 지났다.<br><br>등 뒤에서 환영이 찢기는 소리가 났다. 어제보다 오래 버텼다. 무게의 값이다. 내일은 무게로도 모자랄 것이다. 내일 몫은 내일 짓는다.`,
        ng:`무게까지는 입혔는데 냄새를 못 입혔다. 그것이 환영을 쫓다가 코를 들었다.<br><br>빈 냄새. 그것이 그 자리에 멈춰 서서 진짜 냄새를 거슬러 왔다. 이쪽으로.<br>길목을 반쯤 지난 채로 들켰다. 전력으로 달렸다. 모퉁이 세 개를 돌고 틈에 박혔다. 어깨가 발톱에 긁혀 있었다. 언제 긁혔는지도 몰랐다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-16 } },
      { l:'② 그것이 무엇으로 진짜를 가리는지 본다.', k:'gaze', dc:25,
        ok:`어제 찢긴 환영을 그것이 어떻게 간파했는지부터 봤다. 눈이 아니었다. 혀였다.<br><br>그것은 공기를 핥는다. 혀에 걸리는 게 없으면 모양은 그림이다.<br>오늘은 환영을 안 썼다. 동료들 몸에서 땀 밴 천 조각을 걷어 길목 반대편 바람목에 걸어 뒀다. 혀에 걸리는 미끼.<br><br>그것이 천 쪽으로 가는 사이 다들 지났다. 환영술사가 환영을 안 쓴 날, 제일 환영다운 일이 벌어졌다. 보이는 것만 짓는 게 아니라는 걸 배워 가는 중이다.`,
        ng:`혀를 보느라 너무 가까이 갔다. 혀가 이쪽 공기를 먼저 핥았다.<br><br>그것이 정확히 이쪽 수풀로 돌아섰다. 보는 일과 보이는 일은 한 몸이라는 걸 잊었다.<br>환영 셋을 한꺼번에 터뜨려 흩어지게 하고 그 틈에 뛰었다. 마력이 바닥까지 긁혔다. 머리가 반나절 울렸다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-18 } },
      { l:'③ 환영 없이 그것의 눈이 좇는 결을 거슬러 걷는다.', k:'evade', dc:25,
        ok:`그것의 눈은 움직임의 결을 좇는다. 왼쪽에서 오른쪽으로 흐르는 것에 빠르고, 다가오는 것에는 둔하다.<br><br>정면으로, 아주 천천히 다가가며 길목을 지났다. 커지기만 하고 흐르지 않는 것은 그것 눈에 풍경이다.<br>팔 하나 거리를 스쳐 지날 때도 눈은 이쪽을 통과해 뒤쪽 바람에 흔들리는 덤불을 좇고 있었다.<br><br>눈의 버릇을 읽으면 환영은 눈 밖이 아니라 눈 안에 짓는 것이다. 마력 한 톨 안 들었다.`,
        ng:`반쯤 다가갔을 때 동료 하나가 뒤에서 자세를 바꿨다. 흐르는 움직임.<br><br>그것의 눈이 그리로 갔다가 돌아오는 길에 이쪽을 짚었다. 커져 있는 것. 아까는 없던 것.<br>정면에서 들키면 물러날 결도 없다. 옆으로 몸을 던져 구르고 달렸다. 다들 흩어졌다 모였다. 모이는 데 오래 걸렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S', t:'가짜 벽 — 틈을 덮는 그림',
    x:`사냥 소리가 가까워진다. 숨을 데라고는 벽의 움푹한 홈 하나. 다섯이 끼면 들어가긴 한다.<br><br>
    문제는 홈이 너무 얕다는 것이다. 지나가며 고개만 돌려도 보이는 깊이.<br>
    환영술사는 벽을 그릴 줄 안다. 홈 입구에 벽 한 장. 지나가는 눈에는 이어진 벽.<br><br>
    다만 여기 것들의 눈이 어떤 눈인지는 그려 봐야 안다.`,
    o:[
      { l:'① 마력으로 벽을 그려 홈을 덮고 숨는다.', k:'hide', dc:25,
        ok:`홈에 다섯이 끼고 입구에 벽을 그렸다. 이음매 없이. 원래 벽의 금과 얼룩까지 이어서.<br><br>그것들이 지나갔다. 하나가 그린 벽 앞에 멈춰 코를 댔다. 벽에서 마력 냄새가 나는지 한참 맡았다.<br>냄새의 정체를 못 정한 채 무리를 따라갔다.<br><br>벽을 걷고 나왔다. 그린 벽에 코 자국이 젖어 있었다. 그림에 코 자국이 남을 리 없으니, 이쪽 마력이 그새 벽 흉내를 그만큼 했다는 뜻이다. 그림이 벽이 되는 순간을 코가 증명해 줬다.`,
        ng:`벽은 완벽했다. 바닥을 잊었다.<br><br>홈 앞 바닥에 다섯 켤레 발자국이 벽을 뚫고 들어간 모양으로 찍혀 있었다. 그것 하나가 발자국 끝과 벽을 번갈아 봤다.<br>벽을 밀어 보기 시작했다. 그림이 밀릴 리 없다. 밀리지 않는 게 더 수상했는지 발톱이 그림을 찢었다. 다섯이 홈에서 쏟아져 나와 달렸다. 뒤는 안 봤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 벽이 아니라 어둠을 한 겹 더 그린다.', k:'steady', dc:24,
        ok:`벽 그림은 선이 많아 들킬 데도 많다. 어둠은 선이 없다.<br><br>홈 입구에 어둠 한 겹만 깊게 덧그렸다. 홈이 더 깊어 보이게. 깊은 어둠은 눈이 들어가다 만다.<br>그것들이 지나며 홈을 봤다. 보고도 끝을 못 봤다. 끝이 안 보이는 구멍은 저쪽도 꺼린다.<br><br>다 지나간 뒤에 나왔다. 제일 간단한 그림이 제일 오래 버틴다. 어둠 한 겹. 붓질 한 번.`,
        ng:`어둠을 너무 깊게 그렸다. 지나가던 것 하나가 그 깊이에 흥미를 보였다.<br><br>깊은 구멍은 꺼리는 줄 알았는데, 이놈은 깊은 구멍에 사는 놈이었다. 제 집인 줄 알고 들어왔다.<br>어둠 한 겹 뒤에서 다섯 명과 그것이 얼굴을 마주쳤다. 비명과 발톱이 한꺼번에 터졌다. 다들 그것을 밟고 넘어 뛰었다. 한 사람은 업혀서 나왔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-34, spirit:-16 } }
    ] },

  { at:'S', t:'둘로 걷기 — 어느 쪽을 쫓나',
    x:`트인 터를 건너야 한다. 그것이 높은 데서 내려다보고 있다. 숨을 데는 없다.<br><br>
    환영술사의 오래된 수가 있다. 제 모습을 하나 더 세워 반대로 걷게 하는 것. 둘 중 하나만 쫓을 수 있다.<br>
    문제는 저것이 어느 쪽을 고르느냐다. 반반이라고들 하지만, 여기 것들은 동전이 아니다.<br><br>
    그것이 일어섰다. 고를 준비가 됐다는 뜻이다.`,
    o:[
      { l:'① 환영과 등을 맞대고 갈라져 달린다.', k:'evade', dc:26,
        doom:{ title:'둘로 걷기', what:'그것에게 물려 높은 데로 끌려 올라갑니다', dc:20, sec:40,
          text:`환영은 왼쪽, 몸은 오른쪽. 그것이 높은 데서 떨어져 내리며 골랐다.<br><br>오른쪽. 한 치의 망설임도 없이.<br>그림자가 머리 위를 덮었다. 발톱이 어깨를 꿰고 몸이 바닥에서 떨어졌다. 높은 바위 둥지 쪽으로 끌려 올라간다. 왼쪽에서 환영이 홀로 계속 걷는 게 내려다보인다. 아무도 안 쫓는 길을.<br><br>동료들이 바위를 기어오르기 시작했다. 둥지까지 반도 못 왔다.`,
          dieText:`반반이라고들 했다.<br><br>그것은 처음부터 둘 다 보지 않았다. 심장 소리를 들었다. 환영한테는 없는 것.<br>높은 바위에 빈 환영 하나가 올라와 한참 서 있다가 노을처럼 꺼졌다.`,
        },
        ok:`갈라지기 전에 심장 소리까지 그렸다. 환영 가슴에 마력으로 북 하나.<br><br>둘이 등을 맞대고 달렸다. 그것이 높은 데서 두 번 고개를 갸웃했다. 심장이 둘. 그런 사냥감은 처음일 것이다.<br>고르는 데 걸린 시간이 이쪽 목숨이었다. 터를 다 건널 때까지 그것은 못 골랐다.<br><br>마지막에 환영을 지웠다. 심장 하나가 세상에서 사라지는 걸 그것이 봤다. 한동안 저 바위에서 안 내려올 것이다. 방금 본 걸 셈하느라.`,
        win:{ exp:25, dream:3 } },
      { l:'② 그것이 지난번 사냥에서 뭘 골랐는지 떠올린다.', k:'sense', dc:24,
        ok:`어제 저것이 사냥하는 걸 멀리서 봤다. 짐승 둘 중 작은 쪽을 골랐다. 그제도 작은 쪽.<br><br>작은 것부터 치우는 버릇. 그래서 환영을 반 뼘 작게 세웠다.<br>그것이 환영을 골랐다. 환영이 찢기는 동안 터를 건넜다.<br><br>버릇은 제일 오래된 환영이다. 저쪽 머릿속에 저쪽이 그려 둔. 이쪽은 그 그림에 금 하나만 보태면 된다.`,
        ng:`버릇을 믿었는데 오늘은 큰 쪽을 골랐다. 버릇이 아니라 배고픔의 크기 문제였다.<br><br>진짜 쪽으로 떨어져 내렸다. 구르며 피했다. 바닥이 발톱에 파였다.<br>환영을 저쪽 눈앞에 바짝 당겨 터뜨렸다. 빛이 눈을 채우는 반 숨 동안 달렸다. 터를 벗어나긴 했다. 뒷목의 바람이 한동안 안 잊힌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'S', t:'윤곽 지우기 — 흐려지는 몸',
    x:`긴 복도를 그것들 사이로 지나야 한다. 숨을 데도, 돌아갈 길도 없다.<br><br>
    환영술사는 제 몸의 윤곽을 안다. 윤곽은 빛이 꺾이는 자리다. 마력으로 그 꺾임을 무디게 하면 몸이 흐려진다.<br>
    없어지는 게 아니다. 흐려질 뿐이다. 보려고 보면 보인다.<br><br>
    안 보려는 눈 앞에서만 통하는 재주다. 저것들이 지금 뭘 보려 하는지가 문제다.`,
    o:[
      { l:'① 마력으로 윤곽을 풀고 벽을 따라 흐른다.', k:'evade', dc:25, cost:{ mana:32 }, wake:1,
        ok:`몸의 가장자리에서 빛을 풀었다. 벽 색이 몸으로 스몄다.<br><br>벽을 따라 걸었다. 그것들 눈이 이쪽을 두 번 지나갔다. 두 번 다 머물지 않았다. 흐린 것은 눈에 걸리지 않고 흘러내린다.<br>복도 끝에서 윤곽을 다시 조였다.<br><br>흐려져 있는 동안 이상한 것을 알았다. 윤곽을 풀면 겁도 같이 풀린다. 무서움은 윤곽에 사는 모양이다. 내가 여기 있다, 하는 금 안에. 그 금을 지웠다 긋는 법을 이제 안다.`,
        ng:`복도 중간에서 그것 하나가 재채기를 했다. 이쪽 쪽으로. 바람이 몸의 흐림을 밀었다.<br><br>윤곽이 한순간 선명해졌다. 벽에 사람 한 장이 또렷이 섰다.<br>그것들이 일제히 봤다. 윤곽을 도로 풀 시간이 없어 그냥 달렸다. 흐린 채로 달리니 이쪽 눈에도 세상이 흐렸다. 벽 모서리에 어깨를 두 번 박았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-14 } },
      { l:'② 벽 무늬에 몸을 포개고 지나가기를 기다린다.', k:'hide', dc:24,
        ok:`벽의 얼룩과 금을 읽었다. 사람 하나 설 만큼 어수선한 자리가 있다.<br><br>그 무늬에 몸의 선을 포갰다. 팔은 금을 따라, 어깨는 얼룩에 묻고. 마력은 안 썼다. 무늬가 벌써 반은 그려 놓은 그림이라.<br>그것들이 지나갔다. 바로 앞을. 하나는 이쪽 발끝의 그림자를 밟고 갔다.<br><br>다 지나간 뒤 무늬에서 몸을 뗐다. 벽에 이쪽 모양의 땀 자국이 남았다. 벽이 사람 하나를 기억하게 됐다.`,
        ng:`무늬에 포개고 한참을 섰는데 그것들이 안 지나갔다. 복도 가운데 멈춰 서 있었다.<br><br>다리가 먼저 한계에 왔다. 떨림이 벽을 타고 울렸는지, 하나가 벽 쪽으로 고개를 틀었다.<br>무늬에서 몸을 뜯고 달렸다. 벽에 붙어 있던 반나절 치 각오가 세 숨 만에 끝났다. 무릎이 풀려 두 번 넘어졌다. 동료가 끌다시피 데려갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
    ] },

  { at:'S', t:'발소리 던지기 — 모퉁이 너머의 사람',
    x:`뒤에 그것이 붙었다. 아직 거리는 있다. 냄새가 아니라 소리로 따라오는 놈이다.<br><br>
    환영술사는 소리도 짓는다. 발소리 한 벌을 저쪽 모퉁이에 던져 두면, 소리는 그리로 걸어간다.<br>
    문제는 이쪽 진짜 발소리다. 소리 환영이 걷는 동안 진짜 발은 침묵해야 한다.<br><br>
    다섯 명의 발. 침묵은 늘 머릿수가 어렵다.`,
    o:[
      { l:'① 발소리를 왼쪽 길로 던지고 이쪽은 오른쪽으로 숨 죽여 간다.', k:'evade', dc:25,
        ok:`갈림길에서 발소리 다섯 벌을 왼쪽으로 던졌다. 보폭도 숨소리도 다섯 사람 것 그대로.<br><br>이쪽 다섯은 신을 벗어 들고 오른쪽으로 걸었다. 맨발은 발소리의 재료가 안 된다.<br>그것이 갈림길에서 왼쪽으로 꺾는 소리를 들었다. 소리가 소리를 쫓아갔다.<br><br>환영 발소리는 한참을 더 걸어가다 벼랑 앞에서 멎게 그려 뒀다. 벼랑 아래를 그것이 오래 내려다볼 것이다. 떨어진 것들이 어디 갔나 하고.`,
        ng:`왼쪽으로 던진 발소리에 그것이 안 속았다. 멈춰 서서 양쪽을 다 들었다.<br><br>오른쪽에서 동료 하나가 돌을 찼다. 진짜 소리는 환영보다 늘 선명하다.<br>그것이 오른쪽으로 왔다. 좁은 틈에 다섯이 짐짝처럼 끼어 그것이 지나가길 기다렸다. 그것은 안 지나가고 틈 앞 어둠에 앉았다. 밤새. 다섯 명이 선 채로 밤을 샜다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-16 } },
      { l:'② 일행을 먼저 보내고 소리로 뒤를 막는다.', k:'bond', dc:24,
        ok:`동료들을 먼저 보냈다. 이쪽은 뒤에 남아 소리의 벽을 쳤다.<br><br>무너지는 돌 소리, 쏟아지는 흙 소리. 길이 막혔다고 귀에 말해 주는 소리들.<br>그것이 소리의 벽 앞에서 멈췄다. 귀로 사는 것한테 소리 벽은 돌벽이다.<br>물러서는 발소리를 듣고 이쪽도 물러났다.<br><br>합류하니 동료들이 되물었다. 뒤에서 무너지는 소리가 났는데 괜찮았냐고. 그 소리가 이쪽 그림이었다. 그림이 저쪽만 속인 게 아니었다.`,
        ng:`소리 벽을 치는 중에 그것이 벽을 시험했다. 돌 하나를 소리 쪽으로 던졌다.<br><br>진짜 무너진 돌무더기라면 돌 떨어지는 소리가 났어야 했다. 이쪽 그림에는 그 대답이 없었다.<br>벽이 거짓인 걸 알고 뚫고 왔다. 던질 줄 아는 놈인 줄 몰랐다. 전력으로 도망쳐 동료들을 따라잡았다. 다 같이 한참을 더 뛰었다. 소리로 묻고 대답을 기다리는 놈. 다음에는 대답까지 그려야 한다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
    ] },

  { at:'S', t:'그림자 비틀기 — 위에서 노리는 것',
    x:`천장 어둠에 그것이 산다. 떨어져 내려 덮치는 사냥. 보이는 건 바닥의 제 그림자뿐이다.<br><br>
    그것은 그림자를 보고 떨어진다. 사람 그림자의 목 자리를. 앞서 간 이들이 그걸 어떻게 알았는지는, 복도 바닥 얼룩들이 말해 준다.<br>
    환영술사는 그림자를 옮길 줄 안다. 빛을 비틀면 그림자는 거짓말을 한다.<br><br>
    복도는 길고, 천장 어둠은 끝까지 이어진다.`,
    o:[
      { l:'① 그림자를 세 걸음 앞에 세워 걷는다.', k:'evade', dc:25,
        ok:`빛을 비틀어 그림자를 세 걸음 앞으로 보냈다. 목 자리도 세 걸음 앞이다.<br><br>복도 중간에서 그것이 떨어졌다. 그림자의 목에. 빈 바닥에.<br>바닥을 친 그것이 어리둥절해 있는 사이 옆을 지나 뛰었다. 그림자가 앞장서 달리는 꼴이 우스웠지만 웃을 숨이 아까웠다.<br><br>복도 끝에서 그림자를 제자리로 당겨 왔다. 그림자가 돌아온 어깨가 묘하게 무거웠다. 세 걸음 앞에서 대신 죽을 뻔한 무게다.`,
        ng:`복도 중간에 천장 틈으로 빛이 하나 더 들었다. 그림자가 둘이 됐다.<br><br>하나는 세 걸음 앞, 하나는 발밑에. 비튼 것과 진짜.<br>그것은 똑똑했다. 둘 중 발밑 것을 골라 떨어졌다. 몸을 던져 구르며 피했다. 등에 바람이 쾅 닿았다. 발톱은 반 뼘 비껴갔다. 구르면서 생각했다. 빛이 둘이면 그림자도 둘이라는 걸 왜 잊었나.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 바닥 얼룩들의 자리로 그것의 버릇을 읽는다.', k:'gaze', dc:25, wake:1,
        ok:`얼룩들을 이어 봤다. 다 벽에서 두 걸음 안쪽. 복도 한가운데는 얼룩이 없다.<br><br>그것은 벽 가까이로 걷는 것만 노린다. 벽 쪽이 천장 어둠이 깊어서 몸을 숨기고 떨어지기 좋으니까. 한가운데는 제 몸이 드러나는 자리라 안 덮친다.<br>다들 복도 정중앙으로, 한 줄로 걸었다. 끝까지. 천장 어둠이 따라오며 끓었지만 안 떨어졌다.<br><br>얼룩은 끝난 사람들의 기록이 아니라 산 사람한테 남긴 지도였다. 죽음의 자리를 뒤집어 읽으면 사는 자리가 나온다. 읽는 눈이 또 한 겹 떠졌다.`,
        ng:`얼룩을 읽느라 멈춰 선 자리가 하필 벽에서 두 걸음 안쪽이었다.<br><br>지도를 읽다가 지도 속 자리에 선 셈이다. 천장이 소리 없이 내려왔다.<br>동료가 소리쳐서 반 박자 먼저 굴렀다. 그것이 친 바닥이 움푹 파였다. 새 얼룩이 될 뻔한 자리에 식은땀만 몇 방울 남기고 나왔다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-16 } }
    ] },

  { at:'S', t:'절룩이는 환영 — 약한 척의 값',
    x:`무리가 따라붙은 지 한나절이다. 치지 않는다. 고르고 있다. 다섯 중 제일 약한 것을.<br><br>
    환영술사는 그 고르는 눈에 답을 줄 수 있다. 절룩이는 사람 하나를 그려 일행 뒤에 세우면 무리는 그쪽부터 친다.<br>
    환영이 찢기는 동안 다섯이 거리를 번다.<br><br>
    약한 척은 비싼 그림이다. 진짜 같을수록 빨리 찢기니까.`,
    o:[
      { l:'① 절룩이는 환영을 뒤에 세우고 그 틈에 거리를 벌린다.', k:'evade', dc:26,
        doom:{ title:'절룩이는 환영', what:'무리에게 물려 수풀로 끌려 들어갑니다', dc:20, sec:38,
          text:`환영이 절룩이며 처졌다. 무리가 환영을 둘러쌌다. 셈대로였다. 거기까지는.<br><br>우두머리가 환영을 안 물었다. 코를 대 보고 고개를 들어 일행을 셌다. 다섯. 환영까지 여섯. 숫자가 안 맞는 걸 아는 눈이었다.<br>무리가 환영을 버리고 진짜 중 제일 뒤를 쳤다. 제일 뒤는 환영을 조종하느라 처진 이쪽이었다.<br>발목이 물렸다. 수풀 안으로 끌려 들어간다. 조종이 끊긴 환영이 저만치서 우두커니 서 있다.<br><br>동료들이 수풀을 헤치며 쫓아온다. 수풀이 깊다.`,
          dieText:`약한 척은 비싼 그림이다.<br><br>제일 비싼 값은 그림값이 아니라 숫자였다. 셀 줄 아는 놈 앞에서 머릿수를 늘린 값.<br>무리는 그날 사냥을 일찍 끝냈다. 환영은 수풀 가에서 밤까지 절룩이다 꺼졌다.`,
        },
        ok:`환영을 세우기 전에 일행을 수풀 그늘로 먼저 넣었다. 무리 눈에 보이는 머릿수를 넷으로 줄여 놓고, 절룩이는 다섯째를 그렸다.<br><br>숫자가 맞았다. 우두머리가 셈을 하고도 못 찾아낼 그림.<br>무리가 환영을 에워싸는 사이 넷이 능선을 넘었다. 이쪽도 조종 줄을 끊고 따라 넘었다.<br><br>환영은 끊기는 순간까지 절룩였다. 뒤에서 무리가 빈 것을 무는 소리가 났다. 이로 그림을 씹는 소리. 오래 기억날 소리다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 약한 척 대신 다섯을 한 몸처럼 뭉쳐 걷는다.', k:'steady', dc:24,
        ok:`고르는 사냥은 흩어진 것을 고른다. 고를 수 없게 만들었다.<br><br>다섯이 어깨를 붙이고 한 덩어리로 걸었다. 바깥쪽에 큰 사람, 안쪽에 지친 사람. 덩어리는 크고, 큰 것은 비싸다.<br>무리가 한나절을 더 따라오다 셈을 접었다. 수지가 안 맞는 사냥이었다.<br><br>흩어지면 각자 빠르지만 각자 고를 만해진다. 뭉치면 느리지만 아무도 고를 만하지 않다. 느린 쪽이 다 같이 사는 쪽일 때가 있다.`,
        ng:`한 덩어리로 걷는데 개울이 나왔다. 징검돌이 한 줄. 덩어리가 풀릴 수밖에 없는 길.<br><br>무리가 그걸 기다렸다. 돌을 건너느라 한 줄이 된 순간 맨 뒤를 쳤다.<br>맨 뒤 동료가 물에 넘어지며 피했고 다들 되돌아 뛰어 둘러쌌다. 무리가 물러났다. 젖은 동료 어깨에서 피가 번졌다. 스친 상처라고 했다. 스친 상처치고 깊었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-16 } }
    ] },

  { at:'S', t:'더 큰 것의 그림자 — 시험하는 눈',
    x:`골짜기 길을 무리가 막았다. 돌아갈 길은 없고 머릿수는 저쪽이 위다.<br><br>
    여기 것들한테도 무서운 것이 있다. 가끔 땅을 울리며 지나가는 큰 것. 무리는 그 발소리에 길을 비운다.<br>
    환영술사는 큰 것을 그릴 수 있다. 그림자와 발소리와 땅울림까지.<br><br>
    문제는 무리가 영리하다는 것이다. 영리한 것들은 무서워하기 전에 시험한다.`,
    o:[
      { l:'① 마력을 다 걸어 큰 것의 그림자를 골짜기에 드리운다.', k:'evade', dc:26, cost:{ mana:36 },
        ok:`골짜기 벽에 그림자부터 올렸다. 능선 너머에서 오는 것처럼. 발소리는 땅속에 마력을 박아 울렸다.<br><br>무리가 굳었다. 우두머리가 시험했다. 짖어 본 것이다. 큰 것이 대답하는지.<br>그려 뒀다. 낮고 긴 숨소리. 바위가 떠는 울림까지.<br>무리가 길을 비웠다. 능선만 보면서.<br><br>다섯이 그 길을 지나는 동안 그림자를 한 걸음씩 가깝게 끌었다. 마지막 사람이 지나고 그림자를 능선 뒤로 거뒀다. 큰 것은 오지 않고 지나간 셈이 됐다. 무리는 오늘 밤 그 자리를 떠날 것이다.`,
        ng:`그림자와 발소리까지는 통했다. 우두머리가 마지막 시험을 했다. 바람을 맡은 것이다.<br><br>큰 것의 냄새가 없었다. 빈 바람.<br>무리가 일제히 이쪽을 봤다. 속은 걸 안 눈들. 속인 값을 받으러 왔다. 골짜기 벽을 기어올라 도망쳤다. 마력은 바닥났고 손톱이 두 개 부러졌다. 냄새. 다음에는 냄새다. 그게 제일 어려운 그림인데.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-16 } },
      { l:'② 무리가 진짜 무서워하는 게 뭔지 먼저 본다.', k:'gaze', dc:25,
        ok:`무리를 봤다. 길은 막았는데 자리가 이상했다. 골짜기 왼벽에만 붙어 있다. 오른벽 밑은 비워 두고.<br><br>오른벽 위에 구멍들이 있었다. 무리는 길을 막은 게 아니라 구멍을 피해 서 있던 것이다.<br>무서워하는 건 큰 것이 아니라 저 구멍의 임자였다.<br>구멍 쪽 벽에 긴 것이 기어 나오는 환영을 반쯤만 그렸다. 반쯤이 더 무섭다.<br><br>무리가 소리도 없이 흩어졌다. 비워진 길을 다섯이 걸어 지났다. 구멍 밑은 이쪽도 빠르게 지났다. 그림의 임자가 진짜 나올 수도 있으니까.`,
        ng:`보는 데까지는 좋았다. 구멍의 임자를 그리다가 진짜를 불렀다.<br><br>그림의 긴 것이 벽을 기는 울림을, 구멍 속 진짜가 들은 모양이다. 영역에 들어온 다른 놈인 줄 알고 나왔다.<br>진짜가 나오자 무리도 이쪽도 다 도망쳤다. 쫓기는 것들끼리 골짜기 출구에서 뒤엉켰다. 무리 하나와 어깨를 부딪고 구르기까지 했다. 서로 문 생각도 못 하고 각자 뛰었다. 그날 골짜기에서 제일 혼이 난 건 피차 마찬가지였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
    ] },

  { at:'S', t:'없는 구멍 — 쫓는 것의 발밑',
    x:`쫓긴다. 앞에 무너진 바닥이 있다. 이쪽은 안다. 좁은 턱이 왼쪽에 남은 것도.<br><br>
    쫓는 것은 모른다. 어둠 속에서 바닥만 보고 달려온다.<br>
    환영술사는 바닥을 그릴 수 있다. 없는 바닥을 구멍 위에.<br><br>
    죽이려는 게 아니다. 느리게 만들려는 것이다. 빠진 것은 기어오르는 데 시간이 걸린다.`,
    o:[
      { l:'① 구멍 위에 성한 바닥을 그리고 턱으로 빠진다.', k:'evade', dc:25, wake:1,
        ok:`달리면서 그렸다. 구멍 위에 바닥 한 장. 발자국 얼룩까지 이어서.<br><br>이쪽은 왼쪽 턱으로 꺾었다. 쫓는 것은 곧장 그림 위로 달렸다.<br>그림은 무게를 못 받는다. 떨어지는 소리가 길고, 바닥을 치는 소리가 멀었다. 깊은 구멍이었다.<br><br>턱을 다 건너고 그림을 지웠다. 구멍이 제 입을 드러냈다. 아래서 기어오르는 소리가 나기 시작했다. 시간은 벌었다. 죽인 건 아니다. 그건 중요하다. 이 재주가 무기가 되는 날, 그리는 손이 달라질 테니까.`,
        ng:`그림은 완벽했다. 쫓는 것의 눈이 문제가 아니었다. 수염이 문제였다.<br><br>구멍 가장자리에서 그것의 수염이 바람을 읽었다. 구멍이 내쉬는 찬 바람. 그림 밑의 진실.<br>그것이 구멍을 돌아 턱으로 왔다. 이쪽 길로. 좁은 턱 위에서 쫓고 쫓기는 꼴이 됐다. 턱 끝에서 몸을 날려 건넜다. 그것은 턱에 남았다. 돌아가는 수밖에 없는 턱에. 시간은 벌었는데 심장으로 냈다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-15 } },
      { l:'② 구멍의 가장자리가 어디까지 성한지 가늠한다.', k:'sense', dc:24,
        ok:`그리기 전에 봐 둬야 한다. 그림의 가장자리가 진짜 가장자리와 어긋나면 이쪽이 빠진다.<br><br>달리면서 가장자리를 읽었다. 금 간 데, 들뜬 데. 왼쪽 턱도 반은 삭아 있었다. 성한 반만 골라 디뎠다.<br>그림은 진짜 가장자리에서 손가락 하나 안쪽으로 맞춰 그렸다. 어긋남 없이.<br><br>쫓는 것이 빠지는 소리를 등 뒤로 들으며 성한 반만 밟고 건넜다. 그림은 눈으로 그리지만 가장자리는 발로 긋는다. 그 순서를 지킨 날은 안 죽는다.`,
        ng:`가늠하는 반 숨 동안 거리가 좁혀졌다. 뒷덜미에 숨이 닿을 거리.<br><br>가늠이고 뭐고 그냥 뛰었다. 턱의 삭은 반을 밟았다. 턱이 부서지며 반쯤 미끄러졌다.<br>구멍 가장자리에 매달렸다 기어올랐다. 쫓는 것은 구멍 반대편에서 이쪽을 보며 서 있었다. 안 뛰어들었다. 저쪽은 가늠을 끝낸 것이다. 가늠에서 진 쪽이 매달리는 법이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'S', t:'잔상 — 반 박자 뒤의 몸',
    x:`좁은 방에서 그것과 마주쳤다. 피할 공간이 없다. 치고 빠질 틈도 없다.<br><br>
    환영술사의 마지막 수는 몸에 거는 그림이다. 제 몸의 잔상을 반 박자 뒤에 끌고 다니는 것.<br>
    치는 쪽 눈에는 잔상이 몸으로 보인다. 발톱은 반 박자 전의 자리에 꽂힌다.<br><br>
    반 박자. 그게 이 방에서 이쪽 몫의 전부다.`,
    o:[
      { l:'① 잔상을 끌며 그것의 공격 사이로 문까지 간다.', k:'evade', dc:26, cost:{ mana:34 }, wake:1,
        ok:`마력을 살갗에 얇게 입히고 반 박자를 열었다. 몸이 먼저 가고 모습이 따라온다.<br><br>첫 발톱이 잔상을 갈랐다. 둘째도, 셋째도. 그것 눈에는 매번 맞는 사냥이었을 것이다. 손맛만 없는.<br>문까지 여섯 걸음을 세 번 베이며 갔다. 베인 건 다 그림이었다.<br><br>문을 닫고 잔상을 거뒀다. 반 박자 뒤를 사는 일은 묘했다. 세상이 반 박자 느려지는 게 아니라 이쪽이 반 박자 미래에 서 있었다. 그 자리는 생각보다 조용했다.`,
        ng:`넷째 공격이 발톱이 아니라 꼬리였다. 넓게 쓸었다.<br><br>잔상과 몸을 한꺼번에 덮는 폭. 반 박자가 소용없는 공격이 있다는 걸 몸으로 배웠다.<br>허리를 맞고 벽까지 날았다. 잔상이 흩어졌다. 마지막 남은 마력으로 연기 한 장을 터뜨리고 문으로 굴렀다. 옆구리가 당겨서 한동안 똑바로 서지 못했다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 벽을 등지고 그것의 박자부터 버틴다.', k:'steady', dc:24,
        ok:`등을 벽에 붙였다. 피할 방향을 앞으로만 좁혔다. 좁히면 읽기 쉽다.<br><br>그것의 공격에는 셈이 있었다. 둘 치고 하나 쉼. 쉼마다 반 걸음씩 문 쪽으로 몸을 옮겼다.<br>벽을 등진 게걸음으로 문까지 갔다. 박자 아홉 번.<br><br>문을 나와 생각했다. 잔상 없이 버틴 아홉 박자. 그림 없이도 반 박자는 몸에 있었다. 그림은 그 위에 얹는 것이었다. 바탕이 없으면 그림도 없다.`,
        ng:`일곱 번째 박자에서 그것이 셈을 바꿨다. 셋 치고 쉼 없이 넷째.<br><br>넷째가 어깨에 걸렸다. 벽에 등을 댄 채 맞아서 피할 데가 없었다.<br>어깨가 찢어진 채 문으로 몸을 던졌다. 동료들이 문을 당겨 닫았다. 문짝에 발톱 세 줄이 박혔다. 문 안쪽까지 끝이 나왔다. 그 끝을 다들 한참 봤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-36, spirit:-15 } }
    ] },

  { at:'S', t:'깜빡임 — 큰 눈이 감기는 사이',
    x:`동굴 같은 홀의 안쪽에 큰 것이 자리 잡았다. 자지 않는다. 눈 하나가 홀 전체를 본다.<br><br>
    그 눈도 깜빡인다. 마르니까. 깜빡임 한 번에 숨 하나 반.<br>
    환영은 저 눈에 안 통한다. 겹눈이다. 그림의 이음매를 천 개의 조각으로 나눠 본다.<br><br>
    통하는 건 깜빡임뿐이다. 눈꺼풀 안쪽까지 보는 눈은 없다.`,
    o:[
      { l:'① 깜빡임마다 한 구간씩 홀을 건넌다.', k:'evade', dc:26,
        ok:`눈을 마주 보고 섰다. 깜빡임을 기다리는 일은 눈싸움과 같다. 먼저 깜빡이는 쪽이 지는.<br><br>감기는 순간 달리고, 뜨기 전에 돌이 됐다. 숨 하나 반에 여섯 걸음씩.<br>열한 번의 깜빡임으로 홀을 건넜다.<br><br>마지막 깜빡임에 기둥 뒤로 들어가며 봤다. 뜬 눈이 방금까지 이쪽이 서 있던 자리들을 차례로 훑고 있었다. 뭔가 이동한 건 아는데 어떻게 이동했는지 모르는 눈. 겹눈 천 개가 다 같이 어리둥절한 건 장관이었다.`,
        ng:`아홉 번째 깜빡임이 반만 감겼다. 마른 눈이 덜 감긴 것이다.<br><br>반쯤 뜬 조각 눈 몇 개에 이쪽 움직임이 걸렸다.<br>홀이 울리도록 그것이 몸을 틀었다. 남은 구간을 깜빡임이고 뭐고 전력으로 달렸다. 기둥 뒤로 구르는 순간 바람이 홀을 쓸었다. 그것의 숨이었다. 기둥이 반 뼘 밀렸다. 기둥 뒤에서 아주 오래 서 있었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 깜빡임의 박자가 빨라지는 조건을 본다.', k:'gaze', dc:25, wake:1,
        ok:`깜빡임을 세지 않고 깜빡임의 이유를 봤다. 홀에 바람이 돌 때마다 눈이 빨리 마른다.<br><br>바람은 홀 입구가 내쉬는 숨이다. 입구가 숨 쉴 때 깜빡임이 잦아진다.<br>입구의 숨에 맞춰 건넜다. 깜빡임이 겹으로 오는 때만 골라서. 눈 감은 시간이 두 배로 길어졌다.<br><br>박자를 기다리는 자에서 박자를 고르는 자가 됐다. 세상의 깜빡임에는 다 이유가 있고, 이유를 쥐면 박자는 이쪽 것이다. 눈 하나를 이기고 배운 것치고는 크다.`,
        ng:`이유를 찾느라 눈을 너무 오래 마주 봤다. 겹눈은 시선도 천 조각으로 느낀다.<br><br>그것이 깜빡임을 멈췄다. 마르는 걸 참기로 한 것이다. 이쪽을 보기 위해.<br>마르는 눈과 숨는 사람의 대치. 결국 홀을 반 바퀴 돌아 다른 틈으로 빠졌다. 두 배 길을 기는 동안 등 뒤의 눈이 한 번도 안 깜빡였다. 떠날 때쯤 눈가가 허옇게 말라 있었다. 저쪽도 꽤나 괴로웠을 것이다. 위로는 안 됐지만.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'S1', t:'유리 숲 — 천 개로 비치는 몸',
    x:`표본병이 숲처럼 들어찬 방이다. 키 큰 병, 작은 병. 유리마다 이쪽이 비친다.<br><br>
    방 안쪽에 그것이 있다. 유리에 비친 상도 쫓는 놈이다. 비친 것과 진짜를 구별 못 하는 게 아니라, 구별할 때까지 다 부수는 놈이다.<br>
    환영술사한테 이 방은 무기고다. 비치는 몸이 천 개면 그림 천 장이 거저 생긴 것이다.<br><br>
    병 안의 것들이 깨어나지만 않으면.`,
    o:[
      { l:'① 비친 상들 속에 환영을 섞어 그것을 헤매게 한다.', k:'evade', dc:25,
        ok:`유리마다 비친 이쪽 상에 마력을 한 방울씩 흘렸다. 비친 상들이 저마다 반 박자씩 어긋나게 움직이기 시작했다.<br><br>천 개의 이쪽이 천 가지로 걸었다. 그것이 유리에서 유리로 돌진했다. 깨지는 병은 빈 병부터 골라 어긋나게 비춰 뒀다.<br>그것이 빈 병 열두 개를 부수는 동안 방을 가로질렀다.<br><br>문에서 마력을 거뒀다. 천 개의 상이 한꺼번에 제자리로 돌아왔다. 그것이 유리 숲 한가운데서 사방의 멀쩡한 이쪽들에 둘러싸여 멈춰 섰다. 세상에서 제일 조용한 포위였다.`,
        ng:`어긋나게 움직이던 상 하나가 든 병이 빈 병이 아니었다.<br><br>그것이 병을 부수자 안의 것이 쏟아져 나왔다. 젖은 채로, 화난 채로.<br>방이 둘의 싸움판이 됐다. 유리가 눈처럼 날았다. 그 틈에 기다시피 방을 건넜다. 날린 유리에 뺨과 손등이 그였다. 등 뒤에서 병 깨지는 소리가 한참 이어졌다. 어느 쪽이 이겼는지는 모른다. 알고 싶지도 않다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 비치지 않는 길을 골라 그림자로만 걷는다.', k:'hide', dc:24,
        ok:`비치는 게 무기면 안 비치는 게 갑옷이다. 병과 병 사이, 유리가 서로를 비춰 이쪽이 안 끼는 각이 있다.<br><br>그 각만 이어 걸었다. 유리 천 장 속에 이쪽 상이 한 장도 안 섰다.<br>그것 옆을 지나는데 그것은 유리들만 봤다. 유리 속에 아무도 없으니 방에도 아무도 없는 것이다. 그런 눈으로 사는 놈이라.<br><br>문을 나와 마지막 유리에 한 번 비쳤다. 일부러. 그것이 그 유리로 돌진하는 소리를 들으며 문을 닫았다. 작별 인사치고는 짓궂었다.`,
        ng:`각을 반쯤 이었을 때 동료가 큰 병 앞을 지났다. 동료는 각을 모른다.<br><br>유리에 사람 하나가 크게 비쳤다. 그것이 왔다.<br>동료를 밀치고 같이 굴렀다. 그것이 병을 부쉈다. 병 안의 액체가 쏟아져 바닥에 퍼졌다. 액체에서 김이 올랐다. 구르던 소매가 닿아 천이 삭았다. 끌고 뛰었다. 각이고 뭐고 둘이 비치며 뛰었다. 천만다행으로 그것은 깨진 제 병 앞을 못 떠났다. 지키던 병이었는지도 모른다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S1', t:'숙주 걸음 — 흉내의 복도',
    x:`숙주가 된 시설 사람들이 복도를 오간다. 느리게, 반쯤 풀린 걸음으로. 그것들은 숙주를 안 건드린다.<br><br>
    환영술사는 다섯 명 위에 숙주의 모습을 입힐 수 있다. 처진 어깨, 풀린 눈, 끌리는 발.<br>
    모습만으로는 모자란다. 걸음까지 숙주여야 한다. 숙주는 서두르지 않는다. 절대로.<br><br>
    복도 끝까지 이백 걸음. 서두르고 싶어지는 거리다.`,
    o:[
      { l:'① 다섯에게 숙주 모습을 입히고 풀린 걸음으로 지난다.', k:'evade', dc:26, cost:{ mana:38 },
        ok:`다섯 벌의 그림을 지었다. 어깨선을 무너뜨리고 눈의 초점을 반 뼘 풀었다.<br><br>걸음을 맞췄다. 바닥을 끌고, 목적 없이. 복도의 진짜 숙주들 틈에 섞였다.<br>그것 하나가 다섯 옆을 스쳐 지나며 하나하나 코를 댔다. 그림 위에 발라 둔 복도의 냄새만 맡고 갔다.<br><br>이백 걸음을 이백 년처럼 걸어 복도를 나왔다. 그림을 거두자 다들 허리부터 폈다. 숙주 흉내 반나절에 몸보다 마음이 더 굽어 있었다. 그만큼 그림이 깊었다는 뜻이라 자랑은 못 하겠다.`,
        ng:`백오십 걸음까지 완벽했다. 동료 하나가 발밑의 뭔가를 밟고 흠칫 피했다.<br><br>숙주는 피하지 않는다. 밟으면 밟은 채로 걷는다. 그 한 번의 산 사람 몸짓.<br>복도의 그것들이 일제히 멈췄다. 다섯 벌 그림이 소용없어진 순간 그림을 다 터뜨려 빛을 만들고 뛰었다. 복도 끝까지 오십 걸음을 평생처럼 뛰었다. 뒤에서 숙주들까지 일제히 고개를 돌리는 기척이 났다. 그게 발소리보다 무서웠다.`,
        win:{ exp:24, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 진짜 숙주 하나를 따라 걸으며 걸음을 배운다.', k:'steady', dc:24, wake:1,
        ok:`그림부터 짓지 않았다. 복도 가장자리에서 숙주 하나를 오래 봤다.<br><br>걸음만이 아니었다. 숨이 달랐다. 길고, 얕고, 몸 전체가 반 박자 늦게 따라온다. 그걸 다섯이 몸으로 익힌 다음에야 그림을 입혔다.<br>겉그림과 속걸음이 맞으니 복도가 그냥 길이 됐다.<br><br>흉내는 겉을 베끼는 게 아니라 속 박자를 빌리는 것이다. 그림 솜씨가 는 게 아니라 보는 눈이 는 날이다. 이런 날이 진짜 느는 날이다.`,
        ng:`보고 배우는 데 너무 오래 걸렸다. 보던 숙주가 걸음을 멈추더니 고개를 돌렸다.<br><br>숙주의 눈이 아니었다. 배 속 것이 숙주의 눈을 쓰고 있었다. 오래 서서 저를 보는 것을 저도 보고 있었던 것이다.<br>숙주의 입이 열리고 소리가 났다. 사람 목소리가 아닌 소리. 복도가 깨어났다. 배우다 만 걸음으로 뛰었다. 제일 안 숙주다운 꼴로. 복도는 어찌어찌 벗어났는데 그 목소리가 귀에 박혀 안 빠진다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-16 } }
    ] },

  { at:'S1', t:'관을 타는 목소리 — 소리의 샛길',
    x:`복도가 그것들로 찼다. 지나갈 수가 없다. 기다릴 시간도 없다. 공기가 점점 나빠지는 구역이다.<br><br>
    천장에 통풍관이 지나간다. 관은 소리를 나른다. 멀리, 왜곡 없이.<br>
    환영술사의 소리는 관을 타면 두 배로 산다. 관 저쪽 끝에서 나는 소리는 저쪽 끝의 일이 된다.<br><br>
    저것들을 소리로 옮겨야 한다. 어디로, 어떤 소리로. 그게 오늘의 그림이다.`,
    o:[
      { l:'① 다친 숙주의 소리를 관 저편에 흘려 그것들을 옮긴다.', k:'bond', dc:25,
        ok:`숙주가 다치면 그것들이 모인다는 걸 다들 봤다. 지킬 것이 상하면 모이는 습성.<br><br>관 입구에 대고 그 소리를 지어 불어넣었다. 젖은 기침, 끌리는 몸, 배 속 것이 내는 높은 울음.<br>복도의 그것들이 우르르 관 저쪽 끝으로 몰려갔다.<br>빈 복도를 다섯이 지났다.<br><br>관 저쪽은 막힌 창고다. 들어간 것들이 빈 창고를 뒤지는 소리가 관을 타고 되돌아왔다. 소리는 보냈던 길로 꼭 돌아온다. 빈손인 채로.`,
        ng:`소리는 완벽했다. 방향이 문제였다. 관이 중간에 갈라지는 걸 몰랐다.<br><br>소리가 두 갈래로 갔다. 반은 창고로, 반은 이쪽 등 뒤 환기실로.<br>등 뒤에서도 그것들이 나왔다. 앞뒤로 몰리는 꼴이 됐다. 옆 격실로 뛰어들어 문을 걸었다. 격실 안에서 한나절을 보냈다. 관이 어떻게 갈라지는지 벽의 배관도를 그제야 외웠다. 순서가 거꾸로 됐다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-16 } },
      { l:'② 그것들의 부름 소리를 흉내 내 서로를 부르게 한다.', k:'evade', dc:26,
        ok:`그것들이 서로를 부르는 소리가 있다. 세 음. 낮고, 높고, 긴.<br><br>며칠 들은 걸 입과 마력으로 지었다. 관에 불어넣었다. 먼 구역에서 부르는 것처럼.<br>복도의 것들이 멈칫하더니 대답했다. 세 음. 그리고 부름을 따라갔다.<br>동족의 소리는 안 의심한다. 의심하는 법을 배운 적이 없는 소리라서.<br><br>빈 복도를 지나며 생각했다. 저 소리를 지은 입은 이제 저것들의 말을 한 마디 아는 입이다. 쓸 일이 또 있을 것이다. 없기를 바라지만.`,
        ng:`세 음 중 마지막 음이 반음 흘렀다. 사람 귀로는 모를 차이.<br><br>그것들이 일제히 관을 올려다봤다. 동족의 소리인데 동족이 아닌 것. 그보다 수상한 게 없다.<br>하나가 벽을 타고 올라 관을 뜯기 시작했다. 관이 뜯기며 소리의 출처가 드러나기 전에 복도 반대쪽으로 돌아 뛰었다. 먼 길로 갔다. 공기 나쁜 구역을 숨 참고 두 번 건넜다. 머리가 깨질 듯 아팠다. 반음의 값이다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-18 } },
      { l:'③ 관의 갈래부터 손끝 울림으로 더듬는다.', k:'sense', dc:24,
        ok:`소리를 넣기 전에 관을 알아야 한다. 관에 손을 대고 손톱으로 한 번 튕겼다.<br><br>울림이 가다가 끊기는 데, 둘로 갈라지는 데가 손끝에 돌아왔다. 관은 세 갈래. 창고, 환기실, 그리고 아래층.<br>아래층 갈래에만 소리를 넣었다. 그것들이 아래층으로 내려가는 데는 시간이 걸린다. 제일 오래 비는 길.<br><br>복도를 느긋하게 지났다. 소리는 급해도 소리를 보낼 길은 급하게 고르면 안 된다. 관 하나를 두드려 본 값으로 다섯이 걸어서 지나갔다.`,
        ng:`튕긴 손톱 소리가 너무 컸다. 관은 소리를 나른다. 이쪽 소리도.<br><br>복도의 그것 하나가 관 밑으로 와서 올려다봤다. 관에 붙은 이쪽 손을.<br>손을 떼지도 못하고 돌이 됐다. 그것이 벽을 타기 시작했다. 손을 떼고 뛰었다. 관 두드리기는 틀렸고, 결국 반나절을 돌아갔다. 손톱 하나 값이 반나절이었다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-16 } }
    ] },

  { at:'S1', t:'온기를 보는 것들 — 식은 그림',
    x:`이 구역 것들은 눈이 없다. 온기를 본다. 사람은 저것들 눈에 횃불이다.<br><br>
    환영술사의 그림은 빛으로 짓는 것이라 온기가 없다. 저것들한테 환영은 처음부터 안 보이는 그림이었다.<br>
    거꾸로 하면 된다. 마력으로 온기를 짓는 것. 빈 데에 사람만 한 온기를.<br><br>
    해 본 적은 없다. 오늘이 처음이 된다.`,
    o:[
      { l:'① 사람 온기 다섯을 지어 반대쪽 복도로 걸려 보낸다.', k:'evade', dc:26,
        doom:{ title:'온기 그림', what:'둥지 쪽으로 끌려 들어갑니다', dc:20, sec:38,
          text:`온기 다섯 덩이를 지어 반대 복도로 보냈다. 그것들이 따라갔다. 여기까지는 그림대로.<br><br>마력으로 지은 온기는 이쪽 몸에서 자아낸 것이었다. 실이 달려 있었다. 온기와 이쪽을 잇는, 가늘고 따뜻한 실.<br>그것들 중 가장 늙은 놈이 그 실을 거슬러 왔다. 온기의 뿌리 쪽으로.<br>차가운 손가락들이 어깨를 감았다. 둥지 쪽으로 끌려간다. 온기의 뿌리는 좋은 먹이이기 전에 좋은 화덕이다. 알을 데울.<br><br>동료들이 복도의 불통을 던져 그것들의 눈을 어지럽히고 있다.`,
          dieText:`온기를 지어 본 건 처음이었다.<br><br>처음 짓는 그림에는 서명이 남는다는 걸 몰랐다.<br>둥지 가장 깊은 데가 그날부터 조금 따뜻해졌다. 알들이 반 뼘 일찍 깨어날 것이다.`,
        },
        ok:`온기를 짓되 이쪽 몸에서 뽑지 않았다. 복도의 깨진 전열기에서 뽑아 늘였다.<br><br>기계의 온기 다섯 덩이가 사람 꼴로 반대 복도를 걸어갔다. 그것들이 우르르 따라갔다.<br>식은 다섯은 이쪽 복도를 지났다. 손끝 하나 안 데우고.<br><br>지나고 나서 전열기의 온기를 거뒀다. 반대 복도 끝에서 온기 다섯이 한꺼번에 식는 순간, 그것들이 일제히 두리번대는 기척이 벽 너머로 전해졌다. 다섯 사람이 세상에서 꺼진 줄 알 것이다. 그렇게 알고 살게 두자.`,
        win:{ exp:25, dream:3 } },
      { l:'② 몸의 온기를 바닥으로 흘려 재처럼 식어 걷는다.', k:'sense', dc:25,
        ok:`온기를 숨길 수는 없다. 옮길 수는 있다. 발바닥으로, 바닥의 찬 쇠로.<br><br>걸을 때마다 몸의 열을 한 줌씩 바닥에 흘렸다. 바닥은 넓어서 한 줌쯤은 금방 품는다.<br>그것들 사이를 식은 몸으로 지났다. 저것들 눈에 이쪽은 꺼져 가는 불씨 정도였을 것이다. 불씨는 사냥감이 아니다.<br><br>구역을 나와 몸을 데우는 데 한참 걸렸다. 이가 딱딱 부딪혔다. 추위는 빌린 것이라 돌려주면 그만인데, 몸이 그 셈을 늦게 받아들였다.`,
        ng:`열을 흘리는 속도가 몸이 만드는 속도를 못 따라갔다. 심장이 뛸수록 몸은 데워진다.<br><br>구역 한가운데서 이쪽이 다시 횃불이 됐다. 제일 가까운 놈이 고개를 틀었다.<br>뛰었다. 뛰면 몸은 더 뜨거워진다. 횃불이 아니라 봉화가 되어 구역을 내달렸다. 출구 격벽을 넘고 닫았다. 격벽 너머에서 그것들이 벽에 몸을 비비는 소리가 났다. 벽에 남은 이쪽 온기를 핥는 소리였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'S1', t:'여왕의 앞 — 그림이 벗겨지는 자리',
    x:`여왕의 방 앞 복도다. 공기가 무겁다. 마력이 긴 옷자락처럼 바닥에 끌린다.<br><br>
    여기서는 환영이 안 선다. 지어 올리는 족족 여왕 쪽으로 빨려 풀린다. 여왕은 그림을 먹는다. 아니, 그림의 재료를.<br>
    환영술사가 맨몸이 되는 자리. 평생 입던 옷이 벗겨지는 자리.<br><br>
    그래도 지나야 한다. 길이 여기뿐이니까.`,
    o:[
      { l:'① 그림 없이, 배운 모든 걸음만으로 지난다.', k:'steady', dc:26, wake:1,
        ok:`마력을 다 내려놓았다. 그림 없는 환영술사로 복도에 섰다.<br><br>남은 건 그림을 지으며 곁눈으로 배워 온 것들이었다. 시선이 가는 결, 발소리가 죽는 자리, 숨이 묻히는 박자. 그림의 재료들.<br>재료만으로 복도를 지났다. 여왕의 방 앞을 지나는 동안 안쪽에서 큰 숨이 한 번 이쪽을 더듬고 갔다. 먹을 그림이 없어서, 그냥 지나갔다.<br><br>그림이 벗겨지고 남은 것이 이쪽의 진짜 크기였다. 생각보다 작지 않았다. 그림은 이 위에 다시 입으면 된다. 벗을 줄 아는 자만 입은 것의 임자다.`,
        ng:`버릇이 문제였다. 복도 중간에서 저도 모르게 윤곽을 풀려고 마력을 켰다.<br><br>켜는 순간 마력이 실처럼 뽑혀 여왕의 방으로 흘러갔다. 이쪽 위치가 실 끝에 달려 갔다.<br>방 안에서 뭔가 거대한 것이 몸을 트는 소리가 났다. 복도를 전력으로 뛰었다. 벽이 울리고 문틀이 떨렸다. 구역을 벗어나고도 마력 한 올이 계속 그쪽으로 당겨지는 느낌이 남았다. 실이 아직 안 끊긴 것 같아 소름 돋는 밤이 며칠 갔다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-18 } },
      { l:'② 마력을 미끼로 한 줌 떼어 멀리 던져 두고 지난다.', k:'evade', dc:26, cost:{ mana:40 },
        ok:`어차피 빨릴 마력이면 값을 받고 내주기로 했다.<br><br>마력 한 줌을 뭉쳐 복도 반대쪽 끝 배관 틈에 던져 박았다. 천천히 풀리게. 여왕의 당기는 힘이 그쪽으로 쏠렸다.<br>마력의 강물이 복도 저쪽으로 흐르는 동안, 이쪽 다섯은 빈 물길을 거슬러 지났다.<br><br>던진 마력이 다 풀릴 즈음 복도를 벗어났다. 여왕은 한 줌을 먹고 다섯을 놓쳤다. 셈으로는 이쪽이 이겼는데, 마력 한 줌이 뜯겨 나간 자리가 이가 빠진 것처럼 한동안 허전했다.`,
        ng:`던진 한 줌이 너무 컸다. 여왕이 그 맛에 깨어났다.<br><br>방문이 안쪽에서 울리기 시작했다. 더 내놓으라는 소리.<br>당기는 힘이 복도 전체로 퍼졌다. 머리카락이 그쪽으로 쏠리고 걸음이 뒤로 끌렸다. 기다시피 복도를 벗어났다. 나와서 보니 다섯 다 코피가 나 있었다. 마력 없는 동료들까지. 그 방 앞에서는 사람 자체가 한 줌인 모양이다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'S1', t:'닫힌 척 — 등 뒤의 격벽',
    x:`추격이 붙었다. 복도 끝 격벽은 진작 고장 나 반쯤 열린 채 멈춰 있다.<br><br>
    닫을 수 없는 문. 하지만 닫힌 것처럼 보일 수는 있다.<br>
    환영술사가 맨 뒤에 선다. 다섯이 다 빠진 다음, 열린 틈 위에 닫힌 격벽을 그린다.<br><br>
    그림이 버티는 동안만 진짜 거리가 벌어진다. 버티는 시간이 얼마일지는 쫓는 놈의 눈에 달렸다.`,
    o:[
      { l:'① 틈을 지나자마자 닫힌 격벽을 그려 세운다.', k:'evade', dc:25, wake:1,
        ok:`마지막으로 틈을 빠지며 돌아서서 그렸다. 닫힌 격벽 한 장. 긁힌 자국과 녹까지, 옆 격벽을 그대로 베껴서.<br><br>쫓던 것이 그림 앞에 멈췄다. 발톱으로 한 번 그었다. 그림은 소리를 돌려줬다. 쇠 긁히는 소리. 그 대답에 그것이 물러섰다.<br>긁으면 쇳소리가 나는 것까지가 격벽이니까.<br><br>모퉁이 셋을 지날 때까지 그림이 버텼다. 그림에 소리를 심은 건 처음이었다. 보이는 것에 들리는 것을 포개면 그림은 두 배로 산다. 오늘 벽 하나가 그걸 가르쳤다.`,
        ng:`그림은 섰는데 바람이 문제였다. 열린 틈으로 복도 바람이 지나갔다.<br><br>닫힌 벽에서 바람이 새어 나오는 것. 그것의 털이 그 바람에 흔들렸다.<br>그림을 손으로 찢듯 뚫고 들어왔다. 모퉁이 하나 거리밖에 못 벌었다. 전력으로 뛰어 환기구로 다섯이 쑤셔 들어갔다. 마지막 발이 들어가는 순간 발꿈치 뒤에서 이빨이 닫히는 소리가 났다. 신발 뒤축이 반 뼘 얇아져 있었다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-14 } },
      { l:'② 동료들을 먼저 보내고 틈에 서서 그림과 몸을 겹친다.', k:'bond', dc:25,
        ok:`동료 넷을 먼저 보냈다. 이쪽은 틈 한가운데 서서, 제 몸 위로 닫힌 격벽을 그렸다.<br><br>벽이 된 채로 서 있었다. 쫓던 것이 벽 앞에 코를 대고 섰다. 숨이 그림 너머로 이쪽 얼굴에 닿았다.<br>벽에서 사람 냄새가 났을 것이다. 하지만 복도 전체에 사람 냄새가 흘렀으니, 벽도 그 냄새를 입었을 뿐.<br>그것이 돌아섰다. 벽이 된 채로 그 등을 배웅했다.<br><br>그림을 벗고 틈을 빠졌다. 동료들이 모퉁이에서 새파란 얼굴로 기다리고 있었다. 벽 노릇 한 셈 치고는 심장값이 과했다.`,
        ng:`벽이 된 지 다섯 숨 만에 그것이 벽을 밀어 보았다.<br><br>격벽은 밀리지 않는다. 사람은 밀린다. 반 뼘 밀렸다.<br>밀리는 벽. 세상에 없는 것이 생긴 순간 그것이 알았다. 그림째 몸을 날려 피했다. 발톱이 그림을 찢고 어깨를 스쳤다. 틈을 구르며 빠져 동료들 쪽으로 뛰었다. 다 같이 환기실에 숨어 밤을 보냈다. 어깨의 세 줄 상처에 동료가 약초를 붙여 줬다. 벽 노릇의 품삯이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, spirit:-16 } }
    ] },

  { at:'S1', t:'알 모양 — 어미가 세는 방',
    x:`둥지 방을 질러가야 한다. 알이 줄지어 놓였고, 어미가 주기적으로 돌며 알을 센다.<br><br>
    돌고 나가면 다음 순찰까지 한참. 문제는 방이 넓고 다섯은 느리다는 것. 순찰 중에 걸릴 수밖에 없는 거리다.<br>
    환영술사의 답은 하나다. 순찰 동안 다섯이 알이 되는 것. 웅크린 몸 위에 알의 모습을 입히는 것.<br><br>
    어미는 알을 센다. 숫자가 느는 것을 어떻게 받아들일지가 문제다.`,
    o:[
      { l:'① 다섯을 알 모양으로 덮고 어미의 셈을 지난다.', k:'evade', dc:26,
        doom:{ title:'알 모양', what:'어미에게 물려 둥지 안쪽으로 끌려갑니다', dc:20, sec:36,
          text:`다섯이 웅크리고 알 그림을 덮었다. 어미가 돌기 시작했다.<br><br>세다가 멈췄다. 숫자가 는 것을 안 것이다. 그런데 화내지 않았다. 늘어난 알 앞에 서더니, 혀로 핥기 시작했다. 제 알로 받아들인 것이다.<br>핥다가 맛이 다른 것을 알았다. 어미가 그림째 이쪽을 물어 올렸다. 둥지 안쪽, 알들이 제일 빽빽한 데로 끌고 간다. 따뜻하고 어두운 쪽으로.<br>품으려는 건지 먹으려는 건지 모르겠다. 어느 쪽이든 둥지 안쪽은 안 된다.<br><br>동료들이 알 그림을 벗고 일어나 어미의 뒤에서 소리를 지르고 있다.`,
          dieText:`어미는 숫자가 는 것에 화내지 않았다.<br><br>품이 큰 어미였다. 그게 더 나빴다.<br>둥지 제일 깊은 데에 알이 하나 늘었다. 다른 알보다 크고, 밤이 되면 가끔 소리가 나는 알이.`,
        },
        ok:`알을 먼저 봤다. 크기도 빛깔도 제각각이다. 똑같은 알 다섯 개가 더 수상하다.<br><br>다섯 벌을 다 다르게 그렸다. 금 간 것 하나, 작은 것 하나, 진흙 묻은 것 둘.<br>어미가 돌았다. 셈이 늘어난 자리마다 코를 댔다. 금 간 알 앞에서 오래 머물더니, 혀로 금을 한 번 쓸고 지나갔다. 제가 품다 금 낸 알로 아는 모양이었다.<br>순찰이 끝나고 어미가 나갔다.<br><br>그림을 벗고 방을 건넜다. 금 간 알 역을 맡았던 동료는 한동안 말이 없었다. 혀가 지나간 자리가 그림 너머로도 뜨거웠다고, 나중에 한마디 했다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 어미의 순찰 길을 읽어 셈 밖의 구석으로 돈다.', k:'steady', dc:25,
        ok:`어미의 순찰에는 길이 있었다. 알이 놓인 줄을 따라 도는 길. 알 없는 구석은 안 돈다.<br><br>셈에 안 드는 구석을 이어 그렸다. 벽을 따라, 알 없는 바닥만.<br>어미가 셈에 바쁜 동안 다섯이 구석에서 구석으로 옮겨 방을 돌았다. 알 그림은 한 장도 안 썼다.<br><br>나와서 알았다. 제일 센 그림은 안 그린 그림일 때가 있다. 어미의 눈이 가는 데를 알면, 안 가는 데가 다 길이다.`,
        ng:`구석 하나에 알 껍데기가 쌓여 있었다. 빈 줄 알았던 구석이 부화한 것들의 자리였다.<br><br>껍데기 더미 뒤에서 갓 깬 것들이 고개를 들었다. 작아도 입은 입이다. 울기 시작했다.<br>어미가 셈을 버리고 왔다. 다섯이 흩어져 방을 가로질렀다. 어미는 울음 자리부터 챙겼다. 그 덕에 문까지는 닿았다. 마지막 동료 등에 갓 깬 것 하나가 매달려 있었다. 떼어 내 바닥에 내려 줬다. 죽이지는 않았다. 어미가 봤다. 그게 나중에 어떤 셈이 될지는 모르겠다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'S2', t:'미끼 짐승 — 에워싸고 시험하는 무리',
    x:`무리에게 걸렸다. 수풀 지대. 거리를 두고 에워싸는 중이다.<br><br>
    환영술사의 답은 사냥감을 하나 주는 것이다. 통통한 네발짐승 한 마리. 무리의 눈을 끌 만큼 실하게.<br>
    다만 이 무리는 시험한다. 한 마리가 먼저 다가가 찔러 본다. 반응을 본다. 그 시험을 통과해야 그림이 사냥감이 된다.<br><br>
    찔렀을 때 도망치는 것. 그게 답이다. 그림이 도망칠 줄 알아야 한다.`,
    o:[
      { l:'① 도망칠 줄 아는 짐승을 지어 무리를 끌고 간다.', k:'evade', dc:26, cost:{ mana:36 }, wake:1,
        ok:`짐승을 지었다. 모습만이 아니라 성미까지. 겁 많고, 귀가 밝고, 왼쪽 뒷다리를 전에 다친.<br><br>시험꾼이 다가가 찔렀다. 짐승이 화들짝 뛰어 절룩이며 달아났다. 다친 다리를 감싸는 몸짓까지.<br>무리 전체가 사냥으로 넘어갔다. 절룩이는 것은 무리를 못 이긴다. 무리가 제일 잘 아는 셈이라, 제일 깊이 속는 셈이다.<br>반대쪽으로 다섯이 빠졌다.<br><br>그림에 성미를 넣은 건 처음이다. 모습은 눈을 속이고 성미는 머리를 속인다. 겁 많은 짐승 한 마리를 지어 놓고, 정작 이쪽 겁이 반으로 줄었다. 겁도 넣을 줄 알면 뺄 줄도 알게 되는 모양이다.`,
        ng:`성미까지 지었는데 발자국을 잊었다. 도망치는 짐승 발밑에 자국이 안 찍혔다.<br><br>시험꾼이 두 걸음 쫓다가 멈췄다. 바닥을 봤다. 고개를 들어 울었다.<br>무리가 사냥을 멈추고 돌아섰다. 자국 없는 짐승보다 자국 있는 다섯이 정직한 사냥감이다. 수풀을 뚫고 한참을 쫓겼다. 개울을 두 번 건너고야 떨어졌다. 다 젖은 채로 서로를 봤다. 다음부터 발자국 담당을 하나 두기로 했다. 농담이 아니라.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 시험꾼이 어느 놈인지 먼저 가려낸다.', k:'gaze', dc:25,
        ok:`에워싼 무리를 하나씩 봤다. 다들 이쪽을 보는데 하나만 우두머리를 본다. 신호를 기다리는 놈. 그놈이 시험꾼이다.<br><br>시험꾼은 젊고 급했다. 급한 놈은 시험도 급하게 한다.<br>그림 짐승을 시험꾼 바로 앞에, 급소를 보이며 세웠다. 급한 놈은 시험을 건너뛰고 물었다. 그림을 문 입이 빈 채로 닫혔다.<br>시험꾼이 허둥대는 사이 무리의 줄이 흐트러졌고, 그 틈을 다섯이 빠졌다.<br><br>무리는 시험꾼을 세워 두고도 시험꾼의 성미까지는 못 고른다. 고르는 건 이쪽이 했다.`,
        ng:`시험꾼을 가려냈는데 우두머리가 이쪽 시선을 느꼈다. 보는 자를 보는 자.<br><br>우두머리가 낮게 울자 무리의 줄이 바뀌었다. 시험꾼이 뒤로 빠지고 늙은 둘이 앞으로 왔다. 시험 없이 바로 모는 진형.<br>그림이고 뭐고 다섯이 등을 맞대고 수풀 빈틈으로 돌파했다. 가시에 긁히고 뿌리에 걸려 넘어지며 뚫었다. 무리는 수풀 끝까지만 쫓고 돌아갔다. 제 땅의 금을 아는 것들이다. 그 금이 어딘지 이제 이쪽도 안다. 비싸게 배웠다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-16 } }
    ] },

  { at:'S2', t:'다른 곳의 파문 — 물을 속이는 일',
    x:`물길을 건너야 한다. 큰 것의 물이다. 물결을 읽는 것한테 들키지 않고 다섯이 건널 방법은 없다.<br><br>
    환영술사는 생각을 뒤집었다. 들키지 않는 게 아니라, 다른 데서 들키면 된다.<br>
    마력으로 짓는 파문. 물 저쪽 끝에, 짐승 떼가 건너는 것 같은 큰 파문을.<br><br>
    큰 것이 그리로 가는 동안 이쪽은 이쪽대로 건넌다. 물은 넓고 큰 것은 하나니까.`,
    o:[
      { l:'① 저쪽 물에 파문을 그리고 이쪽을 건넌다.', k:'evade', dc:26,
        doom:{ title:'다른 곳의 파문', what:'물 밑으로 끌려 들어갑니다', dc:20, sec:35,
          text:`저쪽 끝에 파문 여럿을 띄웠다. 물살이 그쪽으로 쏠렸다. 큰 것이 움직였다. 셈대로.<br><br>다섯이 물에 들어 반쯤 건넜을 때, 물이 이상하게 조용해졌다.<br>큰 것이 파문에 닿기도 전에 돌아선 것이다. 가짜 파문에는 없는 것이 있었다. 물 밑의 울림. 발이 바닥을 구르는 진동. 저것은 수면이 아니라 바닥으로 듣고 있었다.<br>그리고 지금, 바닥을 구르는 진짜 발 열 개가 물 한가운데 있다.<br>물이 산처럼 일어나며 제일 뒤의 이쪽을 삼켰다. 물 밑으로 끌려 내려간다.<br><br>앞의 넷이 돌아서서 물을 거슬러 온다. 오지 말라고 소리치고 싶은데 물이 입을 막는다.`,
          dieText:`수면을 속였다. 물은 수면만이 아니었다.<br><br>바닥까지 속일 그림은 아직 못 배웠다.<br>물은 금방 잔잔해졌다. 저쪽 끝의 가짜 파문만 주인 없이 한참 번지다 꺼졌다.`,
        },
        ok:`파문만 그리지 않았다. 바닥에 마력 덩이를 가라앉혀 울림까지 지었다. 짐승 떼의 발 구름.<br><br>수면의 파문과 바닥의 울림이 같은 자리에서 났다. 큰 것이 전속력으로 그리로 갔다. 물이 갈라지는 게 여기서도 보였다.<br>그 틈에 다섯이 건넜다. 가슴까지 오는 물을, 뒤도 안 보고.<br><br>건너편 기슭에 오르자마자 그림을 다 거뒀다. 저쪽에서 큰 것이 빈 물을 몇 바퀴 도는 소리가 났다. 수면과 바닥이 같이 속은 날이다. 물 전체를 속이려면 물 전체에 그려야 한다. 비싸지만 확실한 셈법.`,
        win:{ exp:25, dream:3 } },
      { l:'② 큰 것이 어느 깊이로 듣는지부터 가늠한다.', k:'sense', dc:25,
        ok:`돌을 하나 던져 봤다. 수면만 울리게, 얕게. 큰 것이 반응하는 데까지 숨 다섯.<br><br>이번엔 묵직한 돌을 깊이 가라앉혔다. 바닥이 울리게. 반응까지 숨 둘.<br>바닥으로 듣는 놈이다. 수면 파문은 곁다리고.<br>그래서 바닥 울림만 그려 멀리 보냈다. 수면은 건드리지도 않았다. 큰 것이 바닥 소리를 쫓아간 사이, 발을 바닥에서 반 뼘 띄우듯 조심조심 건넜다.<br><br>무엇으로 듣는지 알면 무엇을 속일지 안다. 그림은 그다음이다. 돌 두 개 값으로 배웠으니 헐값이다.`,
        ng:`가늠하는 돌이 두 개째에서 큰 것의 흥미를 샀다. 먹이가 아니라 반복되는 소리 자체에.<br><br>이쪽 기슭으로 왔다. 물가의 돌 던진 자리를 머리로 들이받았다. 기슭이 무너져 내렸다.<br>다섯이 물가에서 멀찍이 물러나 한나절을 돌았다. 상류의 얕은 여울로. 여울은 무릎물이라 큰 것이 못 온다. 멀리 돌았지만 그게 맞는 길이었는지도 모른다. 가늠하다 들킨 게 아니라 가늠 덕에 못 올 길을 안 간 거라고, 서로 그렇게 정리해 줬다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'S2', t:'없는 구멍 — 울타리의 거짓 문',
    x:`무리가 울타리 안쪽까지 들어왔다. 다섯은 울타리 밖으로 나가야 한다. 구멍은 하나뿐이고 무리가 그 길목을 안다.<br><br>
    환영술사는 울타리에 구멍을 하나 더 그릴 수 있다. 철사가 끊기고 벌어진, 그럴듯한 구멍.<br>
    무리가 가짜 구멍으로 모이면 진짜 구멍이 빈다.<br><br>
    문제는 가짜 구멍에 먼저 닿은 놈이 그걸 통과하려 들 때다. 그림은 통과가 안 된다.`,
    o:[
      { l:'① 가짜 구멍을 먼 쪽에 그리고 진짜 구멍으로 빠진다.', k:'evade', dc:25,
        ok:`울타리 먼 쪽에 구멍을 그렸다. 끊긴 철사 끝이 바람에 흔들리는 것까지.<br><br>구멍 너머에 수풀이 흔들리는 그림도 보탰다. 방금 뭔가 빠져나간 것처럼.<br>무리가 그리로 몰렸다. 놓친 사냥감의 뒤를 쫓는 건 참을 수 없는 일이라.<br>첫 놈이 그림 구멍에 머리를 박는 소리가 들렸다. 진짜 철사에. 그 비명이 혼란을 두 배로 만들었다.<br><br>그 사이 진짜 구멍으로 다섯이 빠졌다. 울타리 밖에서 구멍을 돌아봤다. 잠깐, 고마웠다. 구멍한테도 울타리한테도.`,
        ng:`가짜 구멍은 통했는데 바람이 그림 속 흔들리는 철사를 진짜 철사와 어긋나게 흔들었다.<br><br>우두머리가 그 어긋남을 봤다. 무리의 반을 가짜에 남기고 반을 돌렸다.<br>진짜 구멍에서 무리 반과 마주쳤다. 구멍을 사이에 두고 밀고 밀리는 몸싸움이 났다. 다섯이 다 빠지긴 했는데 마지막 동료 장딴지에 이빨 자국이 났다. 울타리 밖까지 쫓아오지는 않았다. 울타리가 무리의 금인 모양이다. 금을 그어 준 옛사람들에게 처음으로 고마웠다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 그림 구멍에 바람 소리까지 입혀 완성한다.', k:'steady', dc:25, wake:1,
        ok:`구멍은 눈으로만 보는 게 아니다. 구멍으로는 바람이 분다. 소리가 샌다.<br><br>그림 구멍에 바람 소리를 입혔다. 철사 끊긴 틈을 지나는 바람의 휘파람. 밤새 들어 온 그 소리 그대로.<br>무리는 소리부터 믿었다. 눈보다 귀가 먼저 가는 것들이라.<br>무리 전체가 소리 나는 구멍으로 몰렸고, 다섯은 조용한 진짜 구멍으로 빠졌다.<br><br>구멍을 그린 게 아니라 구멍의 증거들을 그렸다. 모습, 소리, 바람. 증거가 셋이면 없는 것도 있는 것이 된다. 그림이 아니라 사실을 짓는 법. 환영술의 다음 층이 거기 있었다.`,
        ng:`바람 소리까지는 좋았다. 소리의 방향이 틀렸다. 바람은 그날 울타리 안에서 밖으로 불었는데, 그림의 휘파람은 밖에서 안으로 부는 소리였다.<br><br>우두머리가 구멍 앞에서 코를 들고 한참 섰다. 소리와 바람이 서로 거짓말을 하고 있었다.<br>속지 않은 우두머리가 무리를 물려 울타리 전체를 순찰 돌기 시작했다. 진짜 구멍 쪽으로도. 결국 순찰 사이 좁은 틈에 다섯이 급하게 빠졌다. 마지막 동료 옷이 철사에 걸려 찢어졌다. 소리에는 방향이 있다. 수업료로 옷 한 벌.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-16 } }
    ] },

  { at:'S2', t:'안개 속 거인 — 반쯤만 그리는 것',
    x:`새벽 안개가 양치 숲에 깔렸다. 무리가 숙영지 냄새를 잡고 좁혀 온다.<br><br>
    안개는 환영술사의 종이다. 맨 공중에 그리는 것보다 열 배 쉽고 열 배 그럴듯하다.<br>
    여기서 큰 것을 그린다. 무리가 제일 무서워하는, 물을 흔드는 그 큰 것을.<br><br>
    다 그리면 안 된다. 안개 속에서는 다 보이는 게 가짜다. 반쯤만. 나머지는 저쪽 머리가 그리게.`,
    o:[
      { l:'① 안개에 큰 것의 반쪽만 그려 무리를 돌려세운다.', k:'evade', dc:26, cost:{ mana:38 },
        ok:`목덜미의 능선 하나. 안개 위로 솟은 등의 일부. 그리고 느린 호흡에 밀려 퍼지는 안개의 소용돌이.<br><br>그게 다였다. 나머지는 무리의 머릿속에서 자랐다. 이쪽이 그린 것보다 세 배는 크게.<br>무리가 소리도 없이 물러났다. 큰 것 앞에서는 짖지도 않는다.<br>안개가 걷히기 전에 숙영지를 옮겼다.<br><br>반만 그리고 반은 받아 낸 그림. 가장 큰 환영은 남의 머릿속에 세우는 것이고, 거기 세운 것은 이쪽 마력이 꺼져도 안 꺼진다. 그 무리는 이제 안개만 끼면 그 등을 볼 것이다.`,
        ng:`능선과 등까지는 좋았다. 욕심을 내서 숨소리를 보탰다.<br><br>큰 것의 숨소리를 들어 본 적이 없다는 게 문제였다. 지어낸 숨소리는 늪 새의 울음과 반쯤 닮아 있었다.<br>우두머리가 멈칫하더니, 안개를 향해 짖었다. 대답이 없자 무리가 다시 좁혀 왔다. 그림을 버리고 다섯이 안개 속으로 흩어져 뛰었다. 안개는 이쪽도 가려 줬다. 종이가 방패도 되는 날이었다. 모이는 데 반나절 걸렸지만 다 모였다.`,
        win:{ exp:24, dream:2 }, lose:{ mind:-20, spirit:-16 } },
      { l:'② 무리가 큰 것을 피하는 진짜 몸짓부터 본다.', k:'gaze', dc:25,
        ok:`그리기 전에 봐 둔 것이 있다. 이틀 전 큰 것이 지날 때 무리가 어떻게 피했는지.<br><br>무리는 달아나지 않았다. 바닥에 배를 붙이고 돌이 됐다. 달아나는 것부터 잡히니까.<br>그래서 큰 것을 그리지 않았다. 무리 너머 수풀에, 바닥에 배를 붙인 다른 무리를 그렸다. 돌이 된 짐승들을.<br>좁혀 오던 무리가 그 그림을 봤다. 그리고 저들도 일제히 배를 붙였다. 뭐가 오는지 몰라도, 선배들이 엎드리면 엎드리는 거다.<br><br>엎드린 무리 사이로 다섯이 걸어서 빠졌다. 큰 것 없이 큰 것의 그림자만 쓴 날. 보이는 것 말고 반응을 그리는 법을 배웠다.`,
        ng:`몸짓을 떠올리는 데 시간이 걸렸다. 그동안 무리의 반이 바람 쪽으로 돌아 들어왔다.<br><br>냄새 포위가 끝난 뒤였다. 그림 한 장으로 돌릴 수 있는 판이 아니었다.<br>숙영지 짐을 반 버리고 늪 쪽으로 뚫었다. 무리는 늪 가장자리까지만 쫓았다. 물을 흔드는 것의 땅에는 저들도 안 들어간다. 늪 무릎물에 서서 무리와 대치한 새벽. 안개가 걷힐 때까지 서로 바라만 봤다. 버린 짐 생각은 아무도 입 밖에 안 냈다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S2', t:'불빛 — 어둠에 뜨는 점들',
    x:`밤이다. 승강기까지 마지막 평지를 건너야 한다. 밤에 뜨는 사냥꾼들의 시간.<br><br>
    저것들은 빛을 쫓는다. 밤의 움직이는 빛은 다친 벌레, 떨어진 불씨, 길 잃은 먹이다.<br>
    환영술사는 어둠에 점을 찍을 수 있다. 깜빡이는, 흐르는, 달아나는 점들.<br><br>
    점이 어디로 흐르게 할지. 오늘 밤의 그림은 그게 전부다.`,
    o:[
      { l:'① 불빛 점들을 평지 반대편으로 흘려 보낸다.', k:'evade', dc:25, wake:1,
        ok:`점 일곱 개를 어둠에 띄웠다. 반딧불처럼 깜빡이며, 다친 것처럼 낮게, 평지 반대편으로.<br><br>밤 사냥꾼들이 점을 쫓아갔다. 공중에서 덮치고, 빈 입을 다시고, 다음 점을 쫓았다.<br>점 일곱이 사냥꾼 전부를 끌고 가는 동안 다섯이 어둠 속을 건넜다.<br><br>마지막 점은 늪 위에서 꺼지게 그렸다. 물에 떨어진 불씨처럼. 사냥꾼들이 늪 위를 한참 맴돌다 흩어졌다. 점 하나가 어디서 꺼지느냐까지가 그림이다. 꺼진 자리에 답이 없어야 그림이 안 들킨다.`,
        ng:`점들은 잘 흘렀다. 문제는 동료의 쇠붙이였다. 달빛이 허리띠 고리에 한 번 튕겼다.<br><br>진짜 빛 한 번이 가짜 빛 일곱 개보다 밝았다.<br>사냥꾼 둘이 꺾어 돌아왔다. 다들 엎드려 굳었고, 이쪽이 급하게 점 하나를 동료 머리 위에서 멀리 끌어냈다. 하나는 속아 따라갔다. 하나는 안 속고 내려와 바닥을 훑었다. 숨 멎는 반 바퀴를 돌고야 떠났다. 그날 밤부로 쇠붙이는 전부 헝겊에 싸게 했다. 빛나는 건 이쪽 그림만으로 족하다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 } },
      { l:'② 일행을 한 줄로 묶고 점 하나를 등대 삼아 걷는다.', k:'bond', dc:24,
        ok:`어둠 속 행군은 흩어지는 게 제일 무섭다. 허리끈으로 다섯을 한 줄로 이었다.<br><br>맨 앞 이쪽 발끝에만 보이는 흐린 점 하나를 띄웠다. 땅바닥 높이, 밖에서는 수풀에 가려 안 보이는 등대.<br>그 점만 보고 한 줄이 걸었다. 소리도 불빛도 없이, 끈의 당김만으로.<br>평지를 다 건너 끈을 풀었다.<br><br>뒤의 동료가 말했다. 점이 있는 줄도 몰랐다고. 끈이 당기는 대로만 걸었다고. 그거면 됐다. 등대는 맨 앞 하나만 보면 되는 물건이다.`,
        ng:`반쯤 건넜을 때 셋째와 넷째 사이 끈이 걸려 풀렸다. 넷째와 다섯째가 어둠에 처졌다.<br><br>세울 수도 부를 수도 없었다. 소리는 안 된다.<br>발끝 점을 조심스레 뒤로 흘려보냈다. 처진 둘이 그 점을 보고 따라붙었다. 그런데 사냥꾼 하나도 그 점을 봤다. 마지막 쉰 걸음은 여섯이 달렸다. 다섯 사람과 하나. 승강기 터 바위 밑으로 굴러들며 점을 꺼 버렸다. 사냥꾼이 빈 어둠을 몇 바퀴 돌고 갔다. 끈 매듭은 다음부터 두 번 묶는다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-15 } },
      { l:'③ 점을 쓰기 전에 사냥꾼들의 눈 높이부터 본다.', k:'hide', dc:24,
        ok:`날개 소리를 따라 올려다봤다. 저것들은 높이 돌며 아래를 훑는다. 훑는 눈은 위에서 아래로. 수풀 그늘의 안쪽까지는 못 꽂힌다.<br><br>점 그림도 안 썼다. 평지 가장자리의 수풀 그늘 띠를 이어 돌았다.<br>길은 반 바퀴 멀었지만 눈 밑은 한 번도 안 지나갔다.<br>건너편에서 보니 평지 한가운데로 질렀으면 세 번은 훑혔을 밤이었다.<br><br>그림은 아껴 뒀다. 안 쓴 그림은 마력도 안 들고 들킬 일도 없다. 제일 싼 그림은 늘 그늘이다.`,
        ng:`그늘 띠가 중간에 끊겼다. 벼락 맞아 쓰러진 나무 자리. 맨땅 스무 걸음.<br><br>건너뛰는 수밖에 없었다. 셋까지는 넘어갔다. 넷째에서 위의 날개가 멈칫했다.<br>급한 대로 점 하나를 띄워 반대로 흘렸다. 날개가 그리로 갔다. 나머지가 맨땅을 구르듯 건넜다. 아낀 그림을 결국 썼다. 아낀 보람은 있었다. 급할 때 남아 있었으니까. 그걸로 셈을 맞추기로 했다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } }
    ] },

  { at:'S2', t:'무늬 입히기 — 양치 잎의 옷',
    x:`낮의 이동이다. 양치 잎 그늘이 얼룩덜룩 내려앉은 숲길. 무리의 영역 한가운데를 지나야 한다.<br><br>
    환영술사는 다섯의 몸에 무늬를 입힐 수 있다. 양치 그늘과 똑같은 얼룩을. 서면 수풀이고 걸으면 그늘이 흔들리는 것처럼 보이게.<br>
    다만 무늬는 배경과 같이 흔들려야 한다. 바람이 잎을 흔들 때 무늬가 가만히 있으면, 그게 제일 눈에 띈다.<br><br>
    바람 부는 숲. 쉽지 않은 옷이다.`,
    o:[
      { l:'① 바람에 맞춰 흔들리는 얼룩 무늬를 다섯에 입힌다.', k:'hide', dc:26, cost:{ mana:34 },
        ok:`무늬를 입히고, 무늬의 흔들림을 숲의 바람에 이었다. 잎이 흔들리면 무늬도 같은 결로 흔들리게.<br><br>다섯이 얼룩이 되어 걸었다. 무리 둘이 길을 가로질러 갔다. 하나가 이쪽을 정면으로 보고도 지나쳤다. 바람에 흔들리는 그늘을 누가 세겠는가.<br>영역 한가운데를 그렇게 통과했다.<br><br>옷을 벗기고 보니 다들 이상한 표정이었다. 걷는 내내 제 손발이 안 보여서, 몸이 숲에 녹은 것 같았다고. 그 말이 맞다. 좋은 무늬는 입은 사람부터 속인다.`,
        ng:`무늬는 완벽했다. 냄새가 남았다. 다섯 사람의 땀 냄새가 얼룩무늬를 입고 걸어 다녔다.<br><br>맞바람이 무리 쪽으로 분 순간, 코들이 일제히 들렸다. 보이지 않는데 냄새 나는 것. 저것들한테는 유령이다.<br>유령을 찾는 사냥이 시작됐다. 눈이 아니라 코로만 좁혀 오는 포위는 무늬로 못 막는다. 개울로 뛰어들어 물길로 반 리를 내려갔다. 냄새가 물에 씻긴 뒤에야 떨어져 나갔다. 다 젖은 채 무늬만 멀쩡했다. 다음에는 냄새부터다. 늘 다음에는, 이다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 무늬 없이 그늘이 제일 짙은 길만 이어 걷는다.', k:'evade', dc:25,
        ok:`해의 자리를 보고 그늘 지도를 머리에 그렸다. 짙은 그늘은 큰 잎 아래, 쓰러진 줄기 밑, 바위 뒤.<br><br>짙은 데서 짙은 데로만 이었다. 옅은 그늘을 건널 때는 바람이 잎을 크게 흔드는 순간에 맞췄다. 흔들리는 그늘 속 한 조각이 되어.<br>무늬 한 장 없이 영역을 통과했다.<br><br>마력은 그대로 남았다. 저녁에 다친 동료 상처를 비추는 불빛 그림에 썼다. 아낀 것은 꼭 쓸 데가 생긴다. 그림도 그렇다.`,
        ng:`그늘 지도는 맞았는데 해가 문제였다. 구름이 걷히며 숲의 그늘이 통째로 옅어졌다.<br><br>짙은 그늘이 사라진 한낮의 숲 한가운데 다섯이 서 있었다.<br>제일 가까운 쓰러진 줄기 밑까지 뛰었다. 무리 하나가 그 움직임을 봤다. 줄기 밑에 다섯이 짐짝처럼 포개져 해가 기울기를 기다렸다. 반나절. 다리에 쥐가 나도 못 펴는 반나절이었다. 해와 구름까지가 그늘 지도다. 하늘을 빼먹은 지도는 반쪽이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
    ] },

  { at:'S2', t:'수면의 달 — 큰 것의 눈앞',
    x:`밤 물가. 승강기 섬으로 가는 마지막 얕은 물을 건너는데, 물 한가운데서 큰 것이 떠올랐다.<br><br>
    달이 물에 떠 있다. 큰 것의 눈도 반쯤 물 위에 떠 있다. 이쪽 다섯은 허리 물에 선 채 굳었다.<br>
    달아나면 물결이 말한다. 서 있으면 숨이 말한다. 시간은 저쪽 편이다.<br><br>
    환영술사의 손에 남은 건 수면이라는 종이 한 장. 그리고 달.`,
    o:[
      { l:'① 수면에 달을 하나 더 띄워 눈을 흔든다.', k:'evade', dc:26,
        doom:{ title:'수면의 달', what:'물 밑으로 끌려 들어갑니다', dc:20, sec:35,
          text:`둘째 달을 큰 것의 반대쪽 수면에 띄웠다. 물에 뜬 달이 둘. 흔들리는 눈이 그쪽으로 돌았다.<br><br>다섯이 조금씩 움직였다. 셋째 걸음에서 진짜 달이 구름에 들어갔다.<br>수면에 달이 하나만 남았다. 가짜만. 구름 아래 세상에서 혼자 빛나는 달.<br>큰 것이 모든 것을 알았다. 눈이 가짜 달에서 이쪽으로 꺾이는 데 반 숨도 안 걸렸다.<br>물이 산이 되어 덮쳤다. 제일 가까이 있던 이쪽이 물 밑으로 끌려 들어간다. 수면 위의 가짜 달이 깨진 유리처럼 일렁이는 게 물속에서 보인다.<br><br>동료들이 물을 치며 온다. 물을 치면 안 되는데. 그 생각만 든다.`,
          dieText:`종이가 한 장이면 하늘도 한 장이어야 했다.<br><br>구름까지는 그릴 생각을 못 했다.<br>물가에 신발 두 짝이 나란히 떠밀려 왔다. 달은 새벽까지 하나였다.`,
        },
        ok:`달을 그대로 베끼지 않았다. 조금 더 밝고 조금 더 큰 달을 큰 것의 등 뒤 수면에 띄웠다.<br><br>물에 사는 눈은 수면의 빛에 약하다. 눈이 뒤로 돌아가는 순간, 다섯이 물살보다 느리게 옆으로 흘렀다.<br>큰 것이 두 달 사이에서 머리를 오래 오갔다. 그동안 다섯은 여울을 건너 섬 기슭 바위 뒤에 닿았다.<br><br>가짜 달을 천천히, 구름에 가리듯 꺼뜨렸다. 급히 끄면 그게 또 수상하니까. 하늘이 꺼뜨린 것처럼. 큰 것은 달이 진 줄 알고 물밑으로 돌아갔다. 오늘 밤 저 물에는 달이 두 번 졌다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 물결 하나 없이 선 채로 큰 것이 지나가길 기다린다.', k:'steady', dc:25, wake:1,
        ok:`그림을 안 꺼냈다. 다섯이 물에 선 채 말뚝이 되기로 했다.<br><br>숨을 물 높이 아래로 낮추고, 물살이 다리를 지나가게 뒀다. 막지 않으면 물결이 안 생긴다. 물속 말뚝에 물결이 없듯.<br>큰 것이 다섯 말뚝 사이를 지나갔다. 비늘이 다리를 스쳤다. 숨이 멎는 감촉. 그래도 말뚝은 말뚝이라 아무도 안 움직였다.<br>그것이 깊은 물로 돌아간 뒤에야 여울을 마저 건넜다.<br><br>그림 없이 버틴 밤. 환영술의 바닥에는 이게 있었다. 아무것도 안 짓고 아무것도 안 되는 것. 비어 있는 것은 어떤 눈에도 안 걸린다. 제일 어려운 그림은 백지였다.`,
        ng:`넷까지는 말뚝이 됐다. 다섯째 동료의 이가 딱딱 부딪혔다. 밤물이 차서.<br><br>그 잔떨림이 수면에 가는 물결을 그렸다. 큰 것의 머리가 돌았다.<br>이쪽이 급하게 물새 내려앉는 그림을 먼 수면에 던졌다. 첨벙 소리까지. 큰 것이 그리로 가는 사이 다섯이 여울을 반쯤 뛰다시피 건넜다. 물결이고 뭐고 다 그린 셈이 됐지만 섬에는 닿았다. 떨던 동료가 미안해했다. 추위는 죄가 아니라고 해 줬다. 다음부터는 제일 추위 타는 사람을 가운데 세우기로 했다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 } }
    ] }
]);

// ── 척후병 (scout) · 무력 ────────────────────
kJob('scout', 'S', [
  { at:'S', t:'열 걸음 앞 — 먼저 밟는 자리',
    x:`척후병은 무리보다 열 걸음 앞을 걷는다. 늘 그랬다. 여기서도 그렇다.<br><br>
    다른 점이 하나 있다. 여기서 열 걸음 앞은, 덫이 먼저 닿는 자리라는 뜻이다. 이빨이 먼저 닿는 자리라는 뜻이기도 하다.<br>
    바닥이 이상하다. 디딘 자리마다 아주 늦게, 아주 조금 꺼진다. 눌림을 기억하는 바닥.<br><br>
    기억한 눌림이 어디로 전해지는지는 모른다. 알게 될 것이다. 열 걸음 앞에서 먼저.`,
    o:[
      { l:'① 꺼지는 바닥의 결을 발로 읽으며 안전한 금을 긋는다.', k:'evade', dc:24, wake:1,
        ok:`발끝으로 바닥을 조금씩 눌러 봤다. 꺼지는 자리와 안 꺼지는 자리. 안 꺼지는 자리는 돌이 받치고 있다.<br><br>돌 받친 자리만 이어 금을 그었다. 뒤의 무리가 금 안쪽만 밟았다.<br>구역을 다 지나고 돌아보니, 금 바깥 꺼진 자국들이 다 한 방향으로 기울어 있었다. 눌림이 흘러간 방향. 그 끝의 어둠에서 뭔가가 헛물켜고 있을 것이다.<br><br>앞을 걷는 일이 몸으로 재는 일에서 금을 긋는 일로 바뀌었다. 이쪽 발이 겪은 것이 뒤의 네 사람에겐 지도가 된다. 열 걸음 앞은 그러라고 있는 자리였다.`,
        ng:`읽으며 가는데 바닥이 중간에 결을 바꿨다. 돌 받친 자리가 끊겼다.<br><br>마지막 눌림이 크게 전해졌다. 어둠 저쪽에서 대답이 왔다. 바닥 밑을 긁으며 오는 소리.<br>금이고 뭐고 다들 뛰었다. 구역 끝 바위 지대에 올라서자 소리가 바위 앞에서 멈췄다. 바위 밑까지 와서 한참 서성였다. 금을 반만 그린 날이다. 반 그린 금은 안 그린 것만 못할 뻔했다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 던질 것들로 바닥을 먼저 때려 본다.', k:'sense', dc:24,
        ok:`주머니의 돌을 아꼈다 여기서 썼다. 열 걸음 간격으로 던져 바닥을 때렸다.<br><br>소리가 둘로 갈렸다. 둔탁한 데와 울리는 데. 울리는 데는 밑이 비었다.<br>둔탁한 자리만 이어 길을 냈다. 던진 돌 아홉 개가 길 하나를 그렸다.<br><br>마지막 돌이 떨어진 울리는 자리는, 다 건넌 다음에 꺼졌다. 천천히, 입을 다무는 것처럼. 돌 아홉 개 값으로 다섯 명이 지나갔다. 싼 값이다.`,
        ng:`넷째 돌이 울리는 자리에 떨어진 순간, 바닥이 돌을 삼켰다.<br><br>그리고 뱉었다. 돌이 이쪽으로 도로 날아왔다. 똑바로.<br>고개를 틀어 피했지만 어깨를 맞았다. 바닥 밑의 것이 던질 줄 아는 놈이었다. 돌 시험은 접고 벽을 타고 돌았다. 어깨에 돌 자국이 사흘 갔다. 제가 던진 돌에 맞은 척후는 전설에도 없을 것이다. 아무한테도 말 안 하기로 했다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } },
      { l:'③ 뒤의 무리에게 걸음 신호 체계부터 맞춘다.', k:'bond', dc:23,
        ok:`출발 전에 손 신호를 맞췄다. 주먹은 멈춤, 손바닥은 엎드림, 두 손가락은 이쪽 발자국만 밟고 전진.<br><br>구역 내내 말 한마디 없이 움직였다. 이쪽이 멈추면 네 사람이 반 박자 안에 멈췄다.<br>중간에 바닥이 한 번 크게 꺼질 뻔했다. 주먹 하나로 다섯이 동시에 굳었다. 눌림이 끊기자 바닥도 조용해졌다.<br><br>구역을 나와서 누가 말했다. 다섯이 한 몸 같았다고. 척후는 눈과 발만이 아니라 손가락 두 개로도 일한다. 오늘 그 손가락이 다섯 목숨을 끌고 왔다.`,
        ng:`신호는 맞췄는데 어둠이 문제였다. 구역 중간부터 손이 안 보였다.<br><br>멈춤 신호를 못 본 동료가 두 걸음을 더 왔다. 꺼지는 자리로.<br>끌어내긴 했는데 눌림이 길게 전해졌다. 바닥 밑이 깨어나는 소리를 들으며 남은 길을 뛰었다. 어둠 속 신호는 손이 아니라 끈이어야 했다. 허리끈을 풀어 다섯을 이었다. 처음부터 그랬어야 했다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-16 } }
    ] },

  { at:'S', t:'발자국 — 셋이 아니라 넷',
    x:`물가 진흙에 그것들 발자국이 찍혀 있다. 무리 셋이 지나갔다. 다들 그렇게 셌다.<br><br>
    척후병은 다시 셌다. 보폭이 셋. 깊이는 넷. 한 놈이 다른 놈 발자국을 정확히 밟으며 걸었다.<br>
    수를 숨기는 무리. 사냥감한테 셋으로 보이고 싶은 무리.<br>
    숨긴 넷째가 지금 어디 있느냐가 문제다. 발자국은 저쪽으로 갔다. 넷째도 같이 갔다는 보장은 어디에도 없다.`,
    o:[
      { l:'① 깊이가 다른 자국을 따라 넷째의 갈림 지점을 찾는다.', k:'sense', dc:25, wake:1,
        ok:`자국을 한 발씩 짚어 갔다. 서른 걸음째에 깊이가 돌아왔다. 셋은 셋의 무게가 됐다.<br><br>넷째가 빠진 자리. 거기서 좌우를 봤다. 왼쪽 바위에 물 묻은 발자국 반 개.<br>넷째는 왼쪽 바위 뒤에 있다. 길목을 지키러 돌아간 것이다. 이쪽들이 갈 길목을.<br>길을 버리고 물가를 거슬러 돌았다. 길목의 넷째는 빈 길을 밤새 지켰을 것이다.<br><br>자국은 걸어간 기록이 아니라 걸어갈 계획이기도 하다. 읽는 쪽이 거기까지 읽으면, 쓴 쪽의 계획은 종이짝이 된다.`,
        ng:`깊이를 재며 따라가는 데 정신이 팔렸다. 자국이 이쪽을 어디로 끌고 가는지를 늦게 봤다.<br><br>자국은 물가 절벽 밑으로 이어졌다. 위를 올려다본 순간 절벽 턱에서 그림자가 떨어져 내렸다.<br>넷째였다. 자국을 읽는 것까지 계산에 넣고 턱에서 기다린 것이다. 구르며 피하고 다들 물로 뛰어들어 벗어났다. 넷째는 물에 안 들어왔다. 젖은 채로 깨달았다. 이쪽이 자국을 읽는 동안 저쪽은 이쪽을 읽고 있었다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 수를 숨기는 무리라면 길을 통째로 바꾼다.', k:'evade', dc:24,
        ok:`수를 숨기는 사냥은 매복 사냥이다. 매복은 길을 아는 자리에 한다.<br><br>그래서 길을 버렸다. 물가 길도, 능선 길도. 제일 험한 바위 비탈로 올랐다. 짐승도 사람도 안 다니는, 길이 아닌 길.<br>비탈 중턱에서 내려다봤다. 버린 길 두 군데 수풀에서 그것들이 일어나 서성이는 게 보였다. 셋 하고도 하나.<br><br>매복은 길에만 산다. 길을 안 걸으면 매복은 그냥 수풀에 앉은 짐승이다. 다리는 고생했지만 셈은 이쪽이 이겼다.`,
        ng:`길을 버리고 비탈로 돌았는데, 저쪽 우두머리가 그것까지 읽었다.<br><br>비탈 위쪽에 넷째가 먼저 올라와 있었다. 수를 숨기는 무리는 길 버리는 사냥감도 안다는 뜻이다.<br>좁은 비탈에서 마주쳤다. 밀고 밀리다 이쪽이 비탈 아래로 몸을 던져 굴렀다. 다들 흩어져 내려와 물을 건너서야 떨어냈다. 팔꿈치와 무릎이 다 깨졌다. 다음 수는 길을 버리는 척하고 길로 가는 것이다. 수 싸움이 한 층 더 올라갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-34, mind:-14 } }
    ] },

  { at:'S', t:'먹힌 표식 — 돌아가는 길',
    x:`갈 때 남긴 표식을 확인하며 돌아가는 길이다. 꺾인 가지, 포갠 돌, 긁은 금.<br><br>
    셋째 표식부터 이상하다. 포갠 돌이 한 걸음 옆으로 옮겨져 있다. 꺾인 가지는 다른 가지가 꺾여 있다. 비슷하게. 그러나 다르게.<br>
    표식을 옮긴 것이 있다. 옮긴 표식은 다 같은 쪽으로 길을 튼다. 골짜기 쪽으로.<br><br>
    골짜기에 뭐가 기다리는지는 안 봐도 안다. 표식을 읽을 줄 아는 것이 거기서 기다린다는 것만으로 충분하다.`,
    o:[
      { l:'① 가짜 표식을 따르는 척 걷다가 직전에 능선으로 꺾는다.', k:'evade', dc:25,
        ok:`옮겨진 표식을 모르는 척 따라 걸었다. 골짜기 입구까지.<br><br>입구 직전, 바람이 등 뒤로 도는 자리에서 일제히 능선으로 꺾었다. 신호는 미리 맞춰 뒀다.<br>골짜기 안쪽에서 뭔가가 한참 기다리다 움직이는 소리가 났다. 늦게. 따르는 척이 통한 것이다.<br>능선을 타고 숙영지에 닿았다.<br><br>표식을 옮길 줄 아는 놈은 표식을 믿는 사냥감만 잡는다. 믿는 척하는 사냥감은 처음이었을 것이다. 다음번엔 저쪽도 척, 까지 읽겠지만. 그건 다음번 일이다.`,
        ng:`따르는 척이 반쯤 통했다. 골짜기 입구에서 꺾는 순간, 입구 양쪽 수풀이 동시에 일어났다.<br><br>기다리는 자리가 골짜기 안이 아니라 입구였다. 꺾는 것까지 셈에 넣은 자리.<br>포위가 닫히기 전 틈으로 다섯이 몸을 던졌다. 구르고 일어나 능선까지 내달렸다. 마지막 동료 배낭이 발톱에 찢겨 안의 것이 반쯤 쏟아졌다. 줍지 못했다. 표식 싸움에서 지면 짐부터 잃는다. 다음은 사람이다. 그 생각에 밤새 뒤척였다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-15 } },
      { l:'② 표식을 옮긴 솜씨에서 그것의 키와 수를 읽는다.', k:'gaze', dc:25,
        ok:`옮겨진 돌을 봤다. 돌에 긁힌 자국 없이 통째로 들려 옮겨졌다. 손이 있는 놈. 꺾인 가지의 높이는 이쪽 어깨 위. 키가 크다.<br><br>그리고 표식마다 솜씨가 같았다. 하나다. 무리가 아니라.<br>하나면 정면은 안 된다. 하나면 매복도 하나다. 골짜기 반대쪽 사면은 비었다는 뜻.<br>그 사면으로 돌았다. 조용히 지나갔다.<br><br>돌아보며 생각했다. 손 있고 키 크고 표식을 읽고 쓰는 것. 그런 것이 혼자 산다. 혼자 사는 이유가 있을 것이다. 그 이유와는 평생 안 마주치고 싶다.`,
        ng:`솜씨를 읽느라 표식 하나를 너무 오래 들여다봤다. 포갠 돌 밑에 그것의 냄새가 남아 있었고, 이쪽 냄새도 지금 거기 남는 중이었다.<br><br>그날 밤 숙영지 둘레에 표식이 생겼다. 포갠 돌 다섯 개. 사람 수대로.<br>세는 것이다. 이쪽을. 옮기는 데서 끝나지 않고 찾아와 세고 가는 것. 돌을 걷어차 버리고 밤새 불침번을 두 배로 섰다. 아침에 돌이 다시 포개져 있었다. 여섯 개로. 여섯째가 무슨 뜻인지 아무도 입 밖에 내지 않았다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-18 } }
    ] },

  { at:'S', t:'두드림 신호 — 따라 하는 것',
    x:`벽 두드림으로 신호를 정했다. 한 번은 전진, 두 번은 대기, 세 번은 후퇴 집결.<br><br>
    갈라진 길에서 둘씩 나뉘어 정찰하고, 신호로 모이기로 했다.<br>
    반 시진 뒤, 세 번 두드림이 왔다. 집결. 그런데 잠시 뒤 다른 방향에서도 세 번이 왔다.<br><br>
    신호는 하나여야 한다. 둘 중 하나는 벽 너머에서 듣고 배운 것이다. 반 시진 만에 배운 것이다.`,
    o:[
      { l:'① 어느 쪽이 진짜인지 확인하러 가까운 쪽부터 간다.', k:'evade', dc:26,
        doom:{ title:'세 번 두드림', what:'벽 틈 안으로 끌려 들어갑니다', dc:20, sec:40,
          text:`가까운 신호 쪽으로 갔다. 모퉁이를 돌자 두드림이 바로 벽 틈 안에서 났다. 세 번. 정확한 박자로.<br><br>틈 안은 어둠이다. 동료가 다쳐서 안에서 두드리나. 몸을 기울여 들여다본 순간, 어둠 속에서 팔이 나왔다.<br>마디 긴 팔이 멱살을 쥐고 틈 안으로 당긴다. 어깨가 끼이고, 버틴 발이 바닥을 긁는다.<br>틈 안쪽에서 두드림이 계속된다. 세 번. 세 번. 이제 그 소리가 뭘 부르는 소리인지 안다. 나머지 사람들을 부르는 소리다. 이쪽이 쓰던 신호로.<br><br>저쪽 복도에서 동료들이 뛰어오는 발소리가 들린다. 신호를 듣고 오는 것이다. 오지 말라고 소리쳤다. 소리가 틈에 먹힌다.`,
          dieText:`신호는 반 시진 만에 배워졌다.<br><br>신호의 임자는 반 시진 만에 미끼가 됐다.<br>그날 밤 시설 곳곳에서 세 번 두드림이 울렸다. 밤새. 아무도 대답하러 가지 않았다. 그것만이 배운 값이었다.`,
        },
        ok:`가까운 쪽으로 가되, 신호를 하나 더 얹었다. 넷째 두드림. 정하지 않은 수.<br><br>진짜 동료라면 침묵하거나 되물을 것이다. 배운 놈이라면 따라 할 것이다.<br>벽 너머에서 넷 두드림이 돌아왔다. 똑같이. 배운 놈이다.<br>그 방향을 버리고 반대쪽으로 가 동료들과 모였다. 거기도 네 번을 시험했다. 침묵이 돌아왔다. 사람이다.<br><br>신호는 정해진 수만큼만 쓰는 게 아니다. 정하지 않은 수가 열쇠가 되는 날이 있다. 오늘부터 신호에 비밀 하나를 늘 남겨 두기로 했다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 신호를 버리고 끈 연결로 바꾼다.', k:'bond', dc:24,
        ok:`소리 신호는 끝났다. 배우는 놈 앞에서 소리는 다 저쪽 것이 된다.<br><br>남은 밧줄과 허리끈을 다 이었다. 갈라진 두 길의 입구에 끈을 걸고, 당김 수로 말하기로 했다. 끈은 벽 너머에서 못 배운다. 못 본다.<br>끈 당김으로 둘씩 짝을 불러들였다. 다 모였다.<br><br>모인 뒤에도 벽 너머에서 세 번 두드림이 간간이 났다. 빈 신호가 빈 복도를 부르는 소리. 대답 없는 신호는 금방 멎을 줄 알았는데 꽤 오래갔다. 끈기 있는 놈이다. 그 끈기가 소름 돋지만, 이쪽 끈이 더 질겼다.`,
        ng:`끈을 잇는 사이 동료 둘이 먼저 신호 쪽으로 움직였다. 끈 연결을 모르고.<br><br>가짜 신호 쪽으로. 뛰어가 소리 대신 돌을 던져 앞을 막았다. 돌 떨어지는 소리에 동료들이 멈췄고, 벽 틈의 것도 이쪽 위치를 들었다.<br>틈에서 나온 긴 팔이 허공을 몇 번 쓸었다. 다들 엎드려 기어서 물러났다. 모이는 데는 성공했는데 등이 다 식은땀이다. 신호를 바꿀 때는 바꾼다는 신호부터 보냈어야 했다. 신호의 신호. 머리가 복잡해지는 밤이다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'S', t:'앞서 간 척후 — 남의 표식 읽기',
    x:`벽 모퉁이에 표식이 있다. 이쪽 것이 아니다. 앞서 들어온 다른 조의 척후가 남긴 것.<br><br>
    금 세 개와 점 하나. 모르는 체계다. 그러나 척후의 표식은 어느 조든 뼈대가 같다. 방향, 수, 경고.<br>
    표식은 복도를 따라 이어진다. 점이 하나씩 늘면서. 마지막 표식에서 점이 넷. 그리고 그 뒤로는 표식이 없다.<br><br>
    점이 뭘 세는 것이었는지. 넷에서 무슨 일이 있었는지. 그걸 읽는 게 오늘 일이다.`,
    o:[
      { l:'① 점의 간격과 자리로 그 척후의 셈을 복원한다.', k:'sense', dc:25,
        ok:`표식들 사이 거리를 걸음으로 쟀다. 점 하나에 모퉁이 하나. 점은 모퉁이 수였다.<br><br>마지막 표식의 점 넷. 넷째 모퉁이가 위험하다는 경고가 아니라, 넷째 모퉁이까지 갔다는 기록.<br>그런데 금 세 개가 마지막 표식에서만 비스듬했다. 비스듬한 금. 서두른 손. 쫓기며 새긴 것이다.<br>넷째 모퉁이를 크게 돌아 피했다. 다섯째 모퉁이 바닥에 그 척후의 칼이 떨어져 있었다. 집어서 챙겼다. 돌아가면 어느 조 것인지 찾아 줄 것이다.<br><br>남의 표식을 끝까지 읽어 주는 것. 그게 척후끼리의 장례다.`,
        ng:`셈을 복원하는 데 반은 맞고 반은 틀렸다. 점은 모퉁이 수가 맞았다. 금 세 개가 문제였다.<br><br>금은 셋이 남았다는 뜻이었다. 다섯 조가 둘을 잃고 셋. 그 셋이 어디로 갔는지를 안 읽었다.<br>넷째 모퉁이에서 그 셋과 마주쳤다. 사람인 채가 아니었다. 벽에 반쯤 붙어서, 이쪽 표식 체계로 벽을 긁고 있었다. 뒷걸음으로 물러나 다른 길로 돌았다. 그 긁는 소리가 오래 따라왔다. 금 세 개. 이제 그 표식은 못 쓴다. 이쪽 조 체계를 오늘 다 새로 짰다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-18 } },
      { l:'② 표식이 끊긴 자리부터는 모든 걸 처음부터 잰다.', k:'steady', dc:24,
        ok:`남의 표식은 넷째 모퉁이까지만 믿기로 했다. 그 뒤는 백지.<br><br>백지부터는 이쪽 법대로 갔다. 돌 던져 소리 재고, 모퉁이마다 거울 조각으로 먼저 보고, 열 걸음마다 이쪽 표식을 새로 새기고.<br>느렸다. 반나절에 복도 여섯 개. 대신 한 번도 안 놀랐다.<br><br>마지막 복도에서 앞선 조의 생존자 하나를 찾았다. 환기구에 숨어 사흘을 버틴 사람. 이쪽 표식 새기는 소리를 듣고 사람인 줄 알았다고 했다. 표식은 길만 남기는 게 아니었다. 소리로도 말하고 있었다.`,
        ng:`백지라고 정하고도 몸이 표식을 따라갔다. 버릇이다. 넷째 모퉁이 너머의 금 하나를 보고 발이 먼저 그쪽으로 꺾였다.<br><br>그 금은 척후의 금이 아니었다. 발톱 자국이었다. 비슷하게 그인.<br>꺾은 복도 끝에서 그것이 기다리고 있었다. 금을 긋고 기다리는 놈. 다들 왔던 길로 전력으로 물러났다. 마지막 동료가 넘어지며 발목을 삐었다. 업고 뛰었다. 버릇이 사람 잡는다는 말을 몸으로 배웠다. 백지는 발까지 백지여야 한다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'S', t:'맞은편 척후 — 보는 자를 보는 자',
    x:`능선 너머로 길을 정하려고 바위에 엎드려 아래를 살폈다. 한참 보다가 알았다.<br><br>
    골짜기 건너편 바위에도 뭔가 엎드려 있다. 이쪽을 보고 있다. 움직이지 않고, 꾸준히.<br>
    무리의 척후다. 짐승 무리에도 앞서 보는 놈이 있다. 저놈이 돌아가 알리면 무리가 온다.<br>
    저쪽도 같은 생각을 하고 있을 것이다. 이쪽이 돌아가 알리기 전에.<br><br>
    척후 대 척후. 돌아가는 발이 빠른 쪽이 이긴다. 또는, 돌아가지 못하게 하는 쪽이.`,
    o:[
      { l:'① 무력을 끌어올려 능선 뒤로 단숨에 빠져 먼저 알린다.', k:'evade', dc:25, cost:{ might:32 },
        ok:`눈을 뗀 순간이 출발이다. 바위에서 미끄러져 내려와 능선 뒤 사면을 내달렸다.<br><br>다리에 무력을 다 실었다. 바위를 뛰어넘고 덤불을 뚫었다. 숙영지까지 한 호흡.<br>알리고 바로 이동했다. 무리가 골짜기를 넘어왔을 때 숙영지는 식은 모닥불 자리만 남아 있었다.<br><br>능선 위에서 그 척후가 빈 자리를 내려다보는 게 멀리 보였다. 저쪽 눈에도 이쪽이 보였을 것이다. 다음 숙영지로 걸어가는 다섯이. 쫓아오지는 않았다. 척후는 안다. 들킨 사냥은 끝난 사냥이다.`,
        ng:`내달리는 사면에 돌밭이 숨어 있었다. 돌이 구르며 사면 전체가 울었다.<br><br>그 소리가 골짜기에 메아리쳤다. 이쪽 위치와 방향이 소리로 그려졌다.<br>무리는 숙영지가 아니라 이쪽 퇴로를 질러 왔다. 알리러 가는 길이 쫓기는 길이 됐다. 마지막엔 벼랑 틈새로 뛰어내리다시피 해서 따돌렸다. 무릎이 깨지고 알리는 건 반 시진 늦었다. 늦은 반 시진 동안 숙영지가 얼마나 위태로웠는지는 생각 안 하기로 했다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 이쪽이 못 본 척 자리를 지켜 저쪽을 묶는다.', k:'hide', dc:25, wake:1,
        ok:`못 본 척했다. 시선을 저쪽 바위를 스쳐 먼 데로 흘리고, 하품까지 한 번 했다.<br><br>본 척후는 움직이지만 안 본 척후는 기다린다. 저쪽은 이쪽이 더 볼 때까지 엎드려 있어야 했다. 척후끼리는 그게 법이다.<br>그 사이 뒤의 동료 하나가 기어 내려가 숙영지에 알렸다. 이쪽은 해가 기울 때까지 바위에서 먼 산만 봤다.<br>저쪽도 꼬박 그 시간을 엎드려 보냈다.<br><br>어두워진 뒤 미끄러져 내려와 합류했다. 무리는 밤새 안 왔다. 척후가 못 돌아가는 무리는 장님이다. 몸으로 묶는 법 말고 시선으로 묶는 법을 배웠다. 싸우지 않고 묶는 법을.`,
        ng:`못 본 척이 반나절을 갔다. 문제는 저쪽이 더 잘 참는다는 것이었다.<br><br>해가 기울며 이쪽 그림자가 바위 밖으로 길게 흘렀다. 자세가 무너진 것까지 그림자가 다 말해 줬다.<br>저쪽이 그 순간 사라졌다. 돌아간 것이다. 이쪽도 구르듯 내려와 알렸다. 무리와 이동이 거의 동시에 시작됐다. 밤새 쫓기며 걸었다. 참을성 싸움에서 진 값이 꼬박 하룻밤이다. 다음에는 그림자까지 셈에 넣는다. 해는 척후 편도 짐승 편도 아니다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S', t:'길목 하나 — 먼저 지나가는 몸',
    x:`다섯이 다 지나야 하는 좁은 길목이다. 양쪽이 벽, 위가 어둠. 매복이 있다면 여기다.<br><br>
    돌을 던져 봤다. 조용하다. 하지만 여기 것들은 돌에 안 속는다. 돌은 피 냄새가 안 나니까.<br>
    척후병의 일은 정해져 있다. 먼저 지나가 보는 것. 몸으로 묻는 것.<br><br>
    다들 말리는 눈으로 봤다. 말리는 눈에 고개만 끄덕이고 길목 앞에 섰다. 이게 직업이다.`,
    o:[
      { l:'① 벽에 붙어 전속력으로 먼저 지난다.', k:'evade', dc:26,
        doom:{ title:'길목', what:'위의 어둠으로 끌려 올라갑니다', dc:20, sec:38,
          text:`벽에 붙어 달렸다. 길목 반까지. 위의 어둠은 조용했다. 너무 조용했다.<br><br>조용한 이유가 있었다. 소리 내는 입이 벌써 내려오는 중이라서.<br>어깨에 걸린 것이 갈고리인지 발톱인지 볼 틈도 없이 몸이 떠올랐다. 벽이 아래로 흘러내려 간다. 위의 어둠이 입을 벌린 것처럼 가까워진다.<br>손에 쥔 돌 하나를 길목 밖으로 던졌다. 신호다. 들어오지 말라는.<br><br>동료들이 그 돌을 보고도 들어온다. 벽을 타고, 서로를 받치고. 말 안 듣는 것들. 고마운 것들.`,
          dieText:`몸으로 묻는 게 척후의 일이다.<br><br>물었고, 대답을 들었다. 대답을 전할 수 없는 자리에서 들었을 뿐이다.<br>길목 바닥에 돌 하나가 떨어져 있다. 들어오지 말라는 신호. 넷은 그 신호대로 먼 길을 돌았다. 그게 마지막 정찰 보고가 됐다.`,
        },
        ok:`달리기 전에 벽을 골랐다. 왼벽은 이끼가 성하다. 위에서 뭐가 다니면 이끼가 상한다. 오른벽 이끼가 상해 있었다.<br><br>왼벽에 붙어 달렸다. 길목 끝에서 뒤돌아 위를 봤다. 오른벽 위 어둠에서 뭔가가 빈 오른길을 내려친 참이었다.<br>동료들에게 신호했다. 왼벽. 한 명씩. 지금.<br>다섯이 다 왼벽으로 지났다. 위의 것은 끝까지 오른벽만 쳤다. 버릇대로.<br><br>몸으로 묻되 묻기 전에 벽부터 읽는 것. 질문을 고르는 것도 묻는 일의 반이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 길목의 바닥 자국부터 샅샅이 읽는다.', k:'sense', dc:24,
        ok:`길목 바닥에 엎드려 비스듬히 봤다. 긁힌 자국들이 다 길목 한가운데 모여 있다. 가장자리는 깨끗하다.<br><br>위에서 내려치는 것의 사정거리가 가운데라는 뜻이다. 벽에 바짝 붙으면 안 닿는다.<br>한 명씩, 벽에 등을 긁으며 게걸음으로 지났다. 위의 어둠이 몇 번 들썩였지만 내려치지는 않았다. 닿지 않는 걸 저도 아는 것이다.<br><br>다 지나고 가운데로 빈 배낭 하나를 던져 봤다. 배낭이 바닥에 닿기 전에 사라졌다. 위로. 소리도 없이. 다섯이 말없이 서로를 봤다. 바닥을 읽은 반 시진이 그 배낭이었다.`,
        ng:`자국을 읽는 동안 길목 안쪽에 너무 들어가 있었다. 읽는 자세는 엎드린 자세다. 엎드린 것은 느리다.<br><br>위의 어둠이 내려왔다. 소리가 아니라 바람으로 알았다.<br>구르며 빠졌는데 종아리에 긴 상처가 났다. 스친 것만으로 이 깊이. 동료들이 끌어냈다. 결국 길목은 못 쓰고 반나절을 돌았다. 피 흘린 척후가 못 쓴다고 한 길은 아무도 토 달지 않는다. 그게 위로라면 위로였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-34, mind:-14 } }
    ] },

  { at:'S', t:'바람 자리 — 냄새의 진형',
    x:`이동 중이다. 바람이 자꾸 방향을 바꾼다. 골짜기 지형이 바람을 비틀어 댄다.<br><br>
    냄새로 사냥하는 것들의 땅에서 바람은 지도보다 중요하다. 바람이 이쪽 냄새를 어디로 나르느냐가 곧 포위망이다.<br>
    척후병이 바람을 읽고 대형을 짠다. 냄새가 흐르는 쪽에 빈 땅이 오게.<br><br>
    바람이 또 바뀌었다. 오늘만 여섯 번째다.`,
    o:[
      { l:'① 바람이 바뀔 때마다 대형의 머리를 돌려 잡는다.', k:'evade', dc:25,
        ok:`손등에 침을 바르고 걸으며 바람을 읽었다. 바뀔 때마다 손짓 하나로 대형을 틀었다.<br><br>냄새는 늘 절벽 쪽, 물 쪽, 바위 지대 쪽으로만 흘러갔다. 코 달린 것들이 안 사는 쪽으로.<br>여섯 번 바뀐 바람에 여섯 번 대형을 틀었다. 길은 구불구불해졌지만 냄새 길은 한 번도 수풀 쪽으로 안 났다.<br><br>해 질 녘, 수풀 지대를 벗어나며 돌아봤다. 수풀 곳곳에서 코 벌름대는 소리가 났다. 하루 종일 지척에 있었던 것이다. 냄새만 안 갔을 뿐. 바람 읽기 여섯 번이 여섯 번의 전투를 지웠다.`,
        ng:`다섯 번째까지는 읽었다. 여섯 번째 바람이 문제였다. 골짜기가 좁아지며 바람이 소용돌이로 바뀌었다.<br><br>냄새가 사방으로 퍼졌다. 숨길 방향 자체가 없어졌다.<br>수풀 곳곳에서 일제히 코 드는 기척이 났다. 대형이고 뭐고 전력으로 골짜기를 빠져나갔다. 뒤에서 쫓는 소리가 세 방향에서 모였다가, 저들끼리 길목에서 엉키는 소리가 났다. 소용돌이 바람은 저쪽 코에도 사방이었던 것이다. 운이었다. 운은 척후 일지에 못 적는다. 적을 수 없는 날이 제일 무서운 날이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 아예 냄새가 고이는 저지대를 피해 능선 길로 올린다.', k:'steady', dc:24,
        ok:`바람과 씨름하는 대신 바람의 성질을 썼다. 냄새는 무겁다. 가라앉아 저지대에 고인다.<br><br>길을 능선으로 올렸다. 능선 바람은 세고 한결같다. 냄새가 고일 틈 없이 하늘로 쓸려 갔다.<br>다리는 고됐다. 오르내림이 세 배. 대신 코 달린 것들은 하루 종일 저지대 수풀에서만 부스럭댔다.<br><br>해 질 녘 야영 자리도 능선 바로 아래 바람받이에 잡았다. 밤새 냄새가 계곡 반대쪽으로만 흘렀다. 코를 이기는 법은 코보다 높이 있는 것이었다. 다리가 뻐근한 만큼 잠은 깊었다.`,
        ng:`능선 길은 냄새를 지웠다. 대신 모습을 내줬다. 능선 위의 다섯은 하늘을 등진 다섯 그림자였다.<br><br>저지대의 것들이 코 대신 눈을 들었다.<br>그림자 다섯이 가는 방향을 다 읽혔다. 다음 골짜기 입구에 마중이 나와 있었다. 싸움을 피해 벼랑 쪽으로 틀고, 벼랑 틈을 타고 내려 돌았다. 손바닥이 다 까졌다. 냄새를 지우면 모습이 남고 모습을 지우면 냄새가 남는다. 둘 다 지우는 길은 느린 길뿐이다. 내일은 느리게 가기로 했다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
    ] },

  { at:'S', t:'높은 자리 — 두 개의 전망대',
    x:`지형을 봐야 한다. 제일 높은 바위기둥이 눈에 들어왔다. 꼭대기에 서면 사방이 한눈이다.<br><br>
    문제는 그런 자리를 이쪽만 좋아하는 게 아니라는 것. 기둥 아래 똥 무더기와 뼈 부스러기. 날개 달린 것의 홰다.<br>
    지금은 비어 있다. 사냥 나간 시간.<br>
    언제 돌아오는지 모르는 홰에 올라가 지도를 그려야 한다. 빨리 그리는 수밖에 없다.`,
    o:[
      { l:'① 무력으로 단숨에 올라 지형을 눈에 박고 내려온다.', k:'evade', dc:25, cost:{ might:34 },
        ok:`기둥에 붙어 무력을 팔다리에 돌렸다. 숨 열 번 만에 꼭대기.<br><br>눈을 크게 떴다. 골짜기 셋, 물길 하나, 숲의 끊긴 자리, 바위 지대. 외우는 게 아니라 통째로 눈에 박았다.<br>숨 스물에 다 봤다. 내려오는 길에 날개 소리가 멀리서 왔다.<br>바닥에 닿아 덤불로 구르는 것과 그것이 홰에 내려앉는 것이 거의 같았다.<br><br>덤불 속에서 방금 눈에 박은 것을 흙바닥에 그렸다. 지도가 됐다. 홰 주인은 제 자리에서 사방을 보고 있을 것이다. 좋은 자리란 그런 것이다. 잠깐 빌렸다.`,
        ng:`숨 열 번에 오르긴 올랐다. 꼭대기에 올라선 순간 알았다. 홰가 빈 게 아니었다.<br><br>반대쪽 턱에 새끼가 한 마리 엎드려 있었다. 눈이 마주쳤다. 새끼가 울었다.<br>어미가 오는 날개 소리가 지평선에서 바로 머리 위까지 오는 데 숨 다섯이 안 걸렸다. 뛰어내리다시피 기둥을 미끄러져 내려왔다. 등짝을 바람이 한 번 후려쳤다. 발톱이 반 뼘 비껴간 바람이었다. 지도는 반쪽만 그렸다. 반쪽 지도로 이틀을 걸었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-34, mind:-14 } },
      { l:'② 홰의 임자가 사냥하는 방향부터 보고 시간을 잰다.', k:'gaze', dc:25, wake:1,
        ok:`바로 안 올라갔다. 덤불에서 홰를 한 식경 봤다.<br><br>뼈 부스러기가 기둥 동쪽에만 쌓여 있다. 동쪽을 보고 먹는다. 사냥도 동쪽. 돌아올 때도 동쪽에서 온다.<br>서쪽 사면으로 올라 동쪽 하늘만 살피며 지도를 그렸다. 동쪽 하늘에 점이 뜨는 순간 내려오면 된다. 점에서 홰까지는 한참이니까.<br>느긋하게 다 그리고 점이 뜰 때 내려왔다.<br><br>높은 자리는 오르는 재주보다 내려올 때를 아는 재주다. 임자의 버릇이 그 시계다. 시계부터 읽고 오르는 법. 척후 수첩에 한 줄 늘었다.`,
        ng:`동쪽만 보다가 당했다. 그날따라 임자가 서쪽으로 사냥을 나갔던 것이다.<br><br>버릇은 버릇이지 약속이 아니다.<br>서쪽에서 소리 없이 미끄러져 들어온 그림자가 홰에 앉고서야 알았다. 기둥 중턱, 오도 가도 못 하는 높이에서. 바위 틈에 몸을 구겨 넣고 임자가 조는 밤까지 기다렸다. 한나절을 바위와 한 몸으로 살았다. 내려와서 그린 지도에는 그 기둥에 표시를 하나 보탰다. 다시는 안 올라갈 자리라는 표시.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S', t:'보폭 셈 — 불 꺼진 어둠',
    x:`횃불이 꺼졌다. 다시 켤 수 없는 어둠이다. 불빛에 모이는 것들의 땅이라 켜서도 안 된다.<br><br>
    들어올 때 척후병은 셌다. 입구에서 갈림까지 이백사십 걸음, 왼쪽 꺾어 백십 걸음, 물소리 나는 데서 오른쪽.<br>
    눈이 없으면 수가 눈이다.<br><br>
    다섯이 한 줄로 어깨에 손을 얹었다. 맨 앞에서 척후병이 센다. 하나. 둘.`,
    o:[
      { l:'① 외운 보폭 수로 어둠을 걸어 되돌아간다.', k:'steady', dc:25, wake:1,
        ok:`센 걸음을 거꾸로 풀었다. 물소리에서 왼쪽, 백십, 오른쪽, 이백사십.<br><br>보폭이 흔들리면 수가 다 틀어진다. 걸음을 자로 썼다. 같은 길이, 같은 박자.<br>중간에 뭔가가 일행 옆을 스쳐 지나갔다. 비린 바람. 셈을 멈추지 않았다. 백구십이, 백구십삼.<br>이백사십에서 손을 뻗으니 입구의 찬 바람이 닿았다.<br><br>어둠 속에서 몸이 자가 되고 걸음이 눈이 됐다. 수를 몸에 새기는 버릇이 이런 날을 위한 것이었다. 새긴 수는 어둠이 못 지운다.`,
        ng:`백십 걸음 구간에서 동료가 돌에 걸려 넘어졌다. 줄이 끊기고 셈도 끊겼다.<br><br>몇 걸음을 잃었는지 모르는 게 제일 나쁘다. 어둠 속에서 수를 잃으면 장님에 귀머거리다.<br>다시 물소리까지 되짚어 가서 처음부터 셌다. 두 배 길을 걸었다. 비린 바람이 이번엔 두 번 스쳤다. 두 번째는 머리카락이 닿을 거리였다. 입구에 닿았을 때 다들 주저앉았다. 이제 넘어져도 각자 수를 잇기로 했다. 다섯이 다 세면 하나쯤 넘어져도 수는 산다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-16 } },
      { l:'② 벽을 더듬는 손과 걸음 수를 겹쳐 확인하며 간다.', k:'evade', dc:24,
        ok:`수만 믿지 않았다. 왼손은 벽을 읽었다. 들어올 때 스친 벽의 순서. 젖은 구간, 거친 구간, 금 간 데.<br><br>수와 벽이 맞으면 가고, 어긋나면 멈춰서 맞췄다. 두 줄이 서로를 확인하는 셈.<br>갈림에서 벽이 먼저 말해 줬다. 수보다 세 걸음 일찍. 들어올 때보다 보폭이 줄어 있었던 것이다. 어둠이 걸음을 줄인다.<br><br>입구까지 수와 벽이 열한 번 서로를 고쳐 줬다. 자는 하나보다 둘이다. 어둠에서는 더더욱.`,
        ng:`벽을 더듬던 손에 벽이 아닌 것이 닿았다. 미지근하고, 숨 쉬는 것.<br><br>벽에 붙어 자던 것이다. 손을 뗐지만 늦었다. 그것이 깨어나는 소리가 어둠을 긁었다.<br>수고 벽이고 다 버리고 어둠 속을 내달렸다. 운 좋게 입구의 빛이 보였다. 운이 나빴으면 더 깊은 쪽이었을 것이다. 다들 입구에 쏟아져 나와 한참 숨만 쉬었다. 벽 읽는 손에도 장갑이 필요하다는 것. 오늘의 교훈치고는 비쌌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S', t:'퇴로 — 무너지는 돌아갈 길',
    x:`척후병의 첫 법은 길을 틀 때마다 퇴로를 세는 것이다. 지금 퇴로는 하나. 들어온 돌다리.<br><br>
    그 돌다리가 방금 소리를 냈다. 돌 갈리는 소리. 다리 밑에서 뭔가가 다리를 허물고 있다.<br>
    일부러 허무는 것이다. 들어온 것들이 못 나가게. 여기 것들은 그런 것까지 한다.<br><br>
    정찰이고 뭐고 없다. 퇴로가 죽으면 전진도 없다. 다리까지 전력으로 삼백 걸음.`,
    o:[
      { l:'① 무력을 다해 다리가 끊기기 전에 일행을 몰아 건넌다.', k:'evade', dc:26, cost:{ might:36 },
        ok:`맨 뒤에서 몰았다. 다친 동료를 반쯤 업다시피 끌며.<br><br>다리 초입에 닿았을 때 다리 가운데가 이미 한 뼘 내려앉아 있었다. 밑에서 돌 뽑는 소리가 빨라졌다. 저쪽도 급하다.<br>한 명씩 건네고 마지막에 이쪽이 뛰었다. 가운데를 디딘 순간 그 칸이 빠졌다. 무력을 터뜨려 남은 거리를 날았다.<br>등 뒤에서 다리가 통째로 내려앉았다.<br><br>건너편에서 다리 밑을 봤다. 허물던 것이 무너진 돌 틈에서 이쪽을 올려다보고 있었다. 눈이 마주쳤다. 저쪽 셈이 반 박자 늦었다. 딱 반 박자.`,
        ng:`삼백 걸음 중 이백에서 길이 꺾이며 좁아졌다. 다섯이 한 줄로 늘어진 만큼 늦어졌다.<br><br>다리에 닿았을 때 가운데 두 칸이 없었다.<br>밧줄을 걸고 한 명씩 틈을 넘겼다. 마지막 이쪽 차례에 다리 머리 쪽 돌까지 빠지기 시작했다. 밧줄에 매달려 건넜다. 발밑으로 다리가 다 내려앉았다. 매달린 채 그 소리를 다 들었다. 끌어올려진 뒤에도 손이 밧줄을 안 놓으려 했다. 손가락을 하나씩 펴 줘야 했다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-16 } },
      { l:'② 둘을 먼저 보내 다리 목을 잡게 하고 나머지를 돌린다.', k:'bond', dc:25,
        ok:`제일 빠른 둘을 먼저 보냈다. 다리 목을 잡고 밧줄을 걸어 두는 임무.<br><br>나머지 셋은 이쪽이 지름길로 돌렸다. 들어오며 봐 둔 바위 틈새 길. 험하지만 백 걸음이 준다.<br>둘이 다리 목에서 밧줄을 걸었고, 셋이 틈새로 빠져나와 합류했다. 다리가 반쯤 허물어졌어도 밧줄 하나면 건넌다.<br>다 건너고 밧줄을 거뒀다.<br><br>퇴로는 지키는 게 아니라 나눠 맡는 것이다. 먼저 보낸 둘의 등이 그날따라 커 보였다. 척후가 다섯이면 퇴로도 다섯 몫이다.`,
        ng:`먼저 보낸 둘이 다리 목에서 그것과 마주쳤다. 다리를 허물던 것이 다리 위로 올라와 있었다.<br><br>둘이서 버틸 상대가 아니다. 비명 같은 호각 소리.<br>나머지 셋이 전력으로 달려 합류해 다섯이 됐다. 다섯이 되니 그것이 물러나 다리 밑으로 돌아갔다. 수를 세는 놈이다. 그 뒤로 급하게 건넜다. 먼저 보낸 둘 중 하나가 팔을 물렸다. 깊지는 않은데, 둘만 보낸 이쪽 셈이 더 아팠다. 다음부터 선발대는 셋이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-16 } },
      { l:'③ 다리를 포기하고 새 퇴로부터 찾는다.', k:'steady', dc:24,
        ok:`무너지는 다리에 목숨을 거는 건 셈이 아니다. 다리를 버렸다.<br><br>들어오며 접어 둔 패를 폈다. 물소리가 났던 동쪽 균열. 물이 나가는 길은 사람도 나간다.<br>균열을 타고 내려가니 물길이 바위 밑으로 흘렀다. 허리를 굽히면 지나갈 높이. 반 시진을 걸어 바깥 골짜기로 나왔다.<br><br>다리 쪽에서는 밤새 돌 허무는 소리가 났다. 아침에 보니 다리 자리가 비어 있었다. 저쪽은 이쪽이 아직 안에 갇힌 줄 알 것이다. 갇힌 사냥감을 찾아 안을 뒤지는 동안, 이쪽은 밖에서 아침을 먹었다. 퇴로는 늘 둘 세는 것. 첫 법은 역시 첫 법이다.`,
        win:{ exp:20, dream:3, item:'맑은 물' }, lose:{ mind:-16, spirit:-16 },
        ng:`동쪽 균열로 갔는데 물길이 불어 있었다. 들어올 때보다 비가 온 것이다.<br><br>바위 밑 길이 반쯤 물에 잠겼다. 지나가려면 얼굴만 내놓고 기어야 한다.<br>물속에 뭐가 사는지 모르는 채로 그 길을 갔다. 중간에 다리에 뭔가 스쳤다. 미끄럽고 긴 것. 아무도 소리 안 내고 기었다. 나와서 보니 다들 입술을 깨물어 피가 나 있었다. 새 퇴로도 퇴로는 퇴로였다. 공짜가 아니었을 뿐.` }
    ] },

  { at:'S1', t:'벽의 배관도 — 반쯤 녹은 지도',
    x:`시설 벽에 배관도가 붙어 있다. 구역 전체의 지도. 산 안개에 반쯤 녹아 글자가 흘러내렸다.<br><br>
    척후병한테는 반쪽 지도도 지도다. 남은 선과 기호에서 뼈대를 세우면 된다.<br>
    급한 건 두 가지. 여왕의 구역이 어디인가. 그리고 거길 안 거치고 다음 격벽까지 가는 길이 있는가.<br><br>
    복도 저쪽에서 뭔가 끌리는 소리가 온다. 지도 읽을 시간이 길지 않다.`,
    o:[
      { l:'① 남은 선으로 전체 뼈대를 복원해 길을 긋는다.', k:'sense', dc:25, wake:1,
        ok:`녹은 지도에서 안 녹은 것부터 찾았다. 배관은 물을 나른다. 물은 아래로 흐른다. 남은 선의 기울기만으로 위아래가 섰다.<br><br>큰 관이 모이는 데가 심장부. 글자는 녹았어도 선 굵기가 말해 줬다. 거기가 여왕 구역이다.<br>가는 관 하나가 심장부를 비껴 바깥 벽을 타고 돌았다. 정비 통로가 따라 붙는 관이다.<br>그 길을 머리에 새기고 자리를 떴다. 끌리는 소리가 모퉁이를 돌기 직전이었다.<br><br>지도의 반이 녹아도 지도가 죽는 게 아니다. 읽는 쪽이 반을 채우면 된다. 척후는 지도의 나머지 반쪽이다.`,
        ng:`뼈대를 세우는 데 반은 성공했다. 문제는 지도가 옛날 것이라는 점이었다.<br><br>그어 둔 정비 통로 길이 중간에 끊겨 있었다. 착륙 때 무너진 구간. 지도에는 없는 현재.<br>끊긴 자리에서 되돌아 나오다 끌리는 소리와 정면으로 마주쳤다. 젖은 것이 복도 폭을 다 채우며 오고 있었다. 옆 격실로 뛰어들어 반나절을 숨었다. 지도는 과거다. 발이 확인하기 전까지는. 그 당연한 걸 격실 어둠 속에서 되새겼다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-16 } },
      { l:'② 지도를 천에 베껴 그리고 자리를 뜬다.', k:'evade', dc:24,
        ok:`외우는 것보다 베끼는 게 남는다. 숯 조각으로 천 조각에 선만 빠르게 옮겼다.<br><br>글자는 버리고 선과 굵기만. 그리는 손과 망보는 눈을 반씩 썼다.<br>끌리는 소리가 가까워지기 전에 베낌을 끝내고 옆 복도로 빠졌다.<br>그날 밤 천 지도를 다섯이 둘러앉아 읽었다. 다섯 눈이 보니 혼자 놓친 게 나왔다. 환기 수직로 표시. 비상 사다리가 있는.<br><br>지도는 머리에 넣으면 한 사람 것이고 천에 넣으면 다섯 사람 것이다. 그 차이가 이런 데서는 목숨 네 개 차이다.`,
        ng:`베끼는 데 욕심을 냈다. 글자까지 옮기려다 시간을 다 썼다.<br><br>끌리는 소리가 복도에 들어섰다. 젖은 것이 벽의 지도와 지도 앞의 이쪽을 같이 봤다.<br>천을 움켜쥐고 뛰었다. 반쯤 베낀 지도는 선이 중간에 다 끊겨 있었다. 끊긴 지도로 이틀을 더듬었다. 욕심이 지도를 반 토막 냈다. 선 먼저, 글자는 버리고. 베낌에도 순서가 있다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
    ] },

  { at:'S1', t:'먼저 드는 머리 — 통풍구 정찰',
    x:`일행이 갈 통풍구 길. 누가 먼저 머리를 넣느냐는 물을 것도 없다. 척후병 일이다.<br><br>
    관은 세 갈래로 갈린다고 벽의 도면이 말해 줬다. 도면이 말해 주지 않는 것은 어느 갈래에 뭐가 사느냐다.<br>
    관 입구에서 안쪽 냄새를 맡았다. 쇠 냄새, 먼지 냄새, 그리고 아주 옅게, 비린 것.<br><br>
    비린 게 어느 갈래인지만 알면 된다. 그걸 알려면 들어가야 한다.`,
    o:[
      { l:'① 세 갈래 분기점까지 먼저 기어 들어가 확인한다.', k:'evade', dc:26,
        doom:{ title:'통풍구 정찰', what:'통풍구 안쪽으로 끌려 들어갑니다', dc:20, sec:36,
          text:`분기점까지는 갔다. 세 갈래 입구에 코를 대고 비린 쪽을 가렸다. 왼쪽. 확인 끝.<br><br>돌아서 기려는데 관이 좁아 몸을 돌릴 수 없다. 뒷걸음으로 기어야 한다. 뒷걸음은 느리다.<br>왼쪽 갈래에서 비린 바람이 훅 밀려왔다. 바람이 아니라 숨이었다. 코앞까지 와 있던 것의.<br>발목이 아니라 어깨가 잡혔다. 앞에서. 왼쪽 관 안으로 끌려 들어간다. 뒷걸음용으로 뻗어 둔 다리가 관 벽을 허우적대며 긁는다.<br><br>관 밖에서 동료들이 다리 긁는 소리를 듣고 있다. 신호 체계에 없는 소리를.`,
          dieText:`어느 갈래에 뭐가 사는지 알아냈다.<br><br>알아낸 것을 전할 수 없는 깊이에서 알아냈을 뿐이다.<br>그날부터 그 통풍구 입구에는 돌이 쌓였다. 넷이 쌓았다. 길 하나를 막는 값으로는 큰 돌무덤이었다.`,
        },
        ok:`들어가기 전에 몸 돌릴 자리부터 셈했다. 도면의 분기점은 관이 모이는 데라 폭이 넓다. 거기서만 돌 수 있다.<br><br>분기점까지 기어 세 입구에 코를 댔다. 비린 건 왼쪽. 가운데는 먼지, 오른쪽은 찬 바람. 오른쪽이 바깥으로 통한다.<br>넓은 분기점에서 몸을 돌려 입구로 돌아 나왔다.<br>일행을 이끌고 오른쪽 갈래로 다 빠졌다. 왼쪽 입구를 지날 때 다들 숨을 참았다. 안쪽 어둠에서 비린 숨이 한 번, 길게 새어 나왔다.<br><br>먼저 드는 머리는 돌아 나올 자리부터 세어 두는 머리여야 한다. 그 순서만 지키면 머리는 몇 번이고 먼저 들 수 있다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 관을 두드려 세 갈래의 대답부터 듣는다.', k:'sense', dc:25,
        ok:`들어가지 않고 알 수 있는 데까지는 밖에서 알아내는 게 먼저다.<br><br>관 입구를 손가락 마디로 톡톡 두드렸다. 소리가 세 갈래를 타고 가서 세 가지로 돌아왔다. 왼쪽은 소리가 중간에 죽었다. 뭔가 부드러운 것이 관을 채우고 있다. 가운데는 길게 울렸다. 비었고 길다. 오른쪽은 울리다 바람 소리에 섞였다. 바깥과 통한다.<br>오른쪽으로 다섯이 기었다. 왼쪽의 부드러운 것은 끝까지 안 깨어났다.<br><br>두드림 세 번으로 정찰 하나를 끝냈다. 몸이 들어가기 전에 소리를 먼저 들여보내는 것. 소리는 잡아먹히지 않는다.`,
        ng:`두드림이 두 번째에서 실수가 됐다. 왼쪽 관의 부드러운 것이 소리에 깼다.<br><br>관 전체가 울리기 시작했다. 그것이 관 속을 이동하는 소리. 어느 갈래로 오는지 소리로는 모르겠다. 관은 소리를 사방에서 온 것처럼 만든다.<br>통풍구를 포기하고 복도로 돌았다. 먼 길로. 복도를 반쯤 갔을 때 지나온 통풍구 입구에서 그것이 머리를 내미는 걸 봤다. 이쪽을 보고 있었다. 기다렸다는 눈으로. 안 들어가길 잘했다. 그 생각만 반복하며 걸었다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S1', t:'지워지는 표식 — 산 안개의 벽',
    x:`이 구역 벽에는 표식이 안 남는다. 분필 금은 산 안개에 한 시진이면 지워진다. 긁은 금은 벽이 무르게 삭아 뭉개진다.<br><br>
    표식 없이 다니면 돌아올 때 길을 잃는다. 시설 복도는 다 비슷하게 생겼다.<br>
    남는 표식을 만들어야 한다. 이 구역의 성질로, 이 구역에서만 통하는 표식을.<br><br>
    척후병은 표식을 벽에만 남기는 게 아니라는 걸 안다. 바닥도, 천장도, 물건의 자리도 다 표식이 된다.`,
    o:[
      { l:'① 복도마다 물건의 자리를 틀어 표식으로 삼는다.', k:'evade', dc:24,
        ok:`쓰러진 의자, 굴러다니는 통, 떨어진 판자. 복도마다 있는 것들을 썼다.<br><br>갈림마다 물건 하나를 집어 가는 방향으로 머리를 돌려 놨다. 의자 등받이가 가리키는 쪽, 통의 주둥이가 보는 쪽.<br>안개는 분필을 지우지만 의자를 돌려놓지는 못한다.<br>돌아오는 길, 물건들이 차례로 길을 가리켰다. 다섯이 한 번도 안 헤매고 나왔다.<br><br>표식은 긋는 게 아니라 남기는 것이다. 이 구역의 물건으로 남기면 이 구역이 못 지운다. 남의 땅에서는 남의 것으로 쓰는 법이다.`,
        ng:`물건 표식은 좋은 수였다. 여기 것들이 물건을 안 건드린다는 전제가 틀렸을 뿐이다.<br><br>돌아오는 길, 셋째 갈림의 통이 사라져 있었다. 넷째 갈림의 의자는 방향이 바뀌어 있었다. 뭔가 끌고 다니거나 치고 지나간 것이다.<br>반쯤 표식, 반쯤 기억으로 더듬어 나왔다. 두 번 길을 잘못 들었고, 한 번은 잘못 든 복도 끝에서 젖은 숨소리를 듣고 돌아 나왔다. 물건 표식에는 물건이 못 움직일 무게가 필요하다. 다음부터는 무거운 것만 쓴다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-18, spirit:-16 } },
      { l:'② 천장 배관에 끈 조각을 묶어 높은 표식을 단다.', k:'steady', dc:24, wake:1,
        ok:`안개는 바닥에 깔린다. 높은 데는 안개가 안 닿는다.<br><br>갈림마다 천장 배관에 끈 조각을 묶었다. 가는 방향 쪽 배관에, 손이 겨우 닿는 높이로. 바닥을 훑고 다니는 것들 눈에도 안 걸리는 높이다.<br>돌아오는 길, 고개만 들면 끈이 길을 불렀다.<br><br>표식의 자리는 지우는 것의 키가 정한다. 안개의 키, 짐승의 키, 사람의 키. 그 셋보다 높거나 낮은 자리가 남는 자리다. 오늘부터 이쪽 표식에는 높이가 생겼다.`,
        ng:`끈 표식은 남았다. 너무 잘 남았다.<br><br>돌아오는 길에 보니 다섯째 끈 밑에 뭔가 서 있었다. 천장을 올려다보며. 끈을 보며.<br>낯선 것이 매달린 자리는 저것들한테도 표식이었다. 거기 모인다. 끈 밑을 피해 한 갈림을 건너뛰어 돌았고, 그 바람에 한 번 길을 잃었다. 표식은 이쪽만 읽으라는 법이 없다. 다음 끈은 더 높이, 배관 뒤쪽에 숨겨 묶기로 했다. 읽는 자만 아는 표식. 그게 완성형이다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 } }
    ] },

  { at:'S1', t:'머릿수 — 늘어나는 복도',
    x:`숙주들이 선 복도를 지나야 한다. 지나기 전에 척후병은 셌다. 왼벽에 일곱, 오른벽에 다섯. 열둘.<br><br>
    반쯤 지나서 다시 셌다. 열셋.<br>
    하나가 늘었다. 어느 쪽 벽인지, 어느 놈인지 모르게 늘었다. 새로 벽에 붙은 놈이 있거나, 따라 들어온 놈이 벽에 붙은 척 섞였거나.<br><br>
    늘어난 하나는 아직 마르지 않았을 것이다. 벽에 오래 붙은 것들은 말라 있다.`,
    o:[
      { l:'① 걸음을 늦추지 않은 채 젖은 놈을 가려낸다.', k:'gaze', dc:26,
        ok:`고개를 안 돌리고 눈만 썼다. 지나치는 숙주들의 발밑을 봤다.<br><br>마른 것들 발밑은 먼지가 소복하다. 왼벽 넷째, 발밑 먼지가 쓸려 있고 바닥에 물기가 번져 있다. 저놈이다.<br>일행에게 미리 정한 헛기침 신호를 보냈다. 넷째 앞을 지날 때 다들 벽 반대쪽으로 반 걸음 붙었다.<br>넷째의 손가락이 허공을 한 번 긁었다. 반 걸음이 모자란 거리에서.<br><br>복도 끝까지 걸음 수 하나 안 바꾸고 나왔다. 세는 버릇이 목숨을 세었다. 열둘과 열셋의 차이. 그 하나가 전부였다.`,
        ng:`발밑을 보며 걷는데 젖은 자국이 둘이었다. 하나가 아니라.<br><br>늘어난 게 둘인데 셈은 하나로 했던 것이다. 처음 셀 때 이미 하나 섞여 있었다는 뜻.<br>둘째 젖은 놈 앞에서 걸음이 저도 모르게 빨라졌다. 그 반 박자를 둘이 같이 읽었다. 양벽에서 동시에 손이 나왔다. 다들 복도 가운데로 뭉쳐 내달렸다. 마지막 동료 배낭이 뜯겨 나갔다. 복도 끝에서 세어 보니 다섯은 다 있었다. 배낭 하나 값. 세는 법을 다시 배운 값이다. 처음 셈부터 의심할 것.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 무력을 실어 다섯을 한 번에 몰아 복도를 끊는다.', k:'evade', dc:25, cost:{ might:34 },
        ok:`가려낼 시간이 없으면 시간을 없애면 된다. 손짓 하나로 다섯을 묶어 전력 돌파로 바꿨다.<br><br>이쪽이 맨 뒤. 무력을 다리에 싣고 일행을 앞으로 몰았다. 젖은 놈이 어느 벽에서 나오든 맨 뒤가 받는다.<br>나온 건 오른벽 끝. 손이 허공을 쓸었다. 이미 다 지나간 허공을.<br>복도 밖에서 문을 닫았다.<br><br>문틈으로 보니 열셋째가 벽에서 떨어져 나와 복도 가운데 서 있었다. 마른 열둘은 그대로 벽에 있고. 젖은 하나만 이쪽 문을 보고 있었다. 오래. 문고리를 한 번 더 확인했다.`,
        ng:`몰아 달리는데 복도 한가운데서 왼벽의 마른 놈 하나가 넘어지듯 쓰러졌다. 길을 막으며.<br><br>우연인지 셈인지 모르지만 다섯 걸음이 한 번에 엉켰다.<br>엉킨 틈에 젖은 놈이 벽에서 나왔다. 뒤의 이쪽이 받아 내며 굴렀다. 어깨를 긁혔다. 쓰러진 마른 놈을 뛰어넘으며 다들 빠져나왔다. 넘을 때 마른 놈의 눈이 떠 있는 걸 봤다. 쓰러진 게 아니라 누운 것이었다. 협동. 그 단어가 머리에 박혀 밤새 안 나갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'S1', t:'격실 개방 — 문 뒤의 순서',
    x:`막사로 쓸 만한 격실을 찾아야 한다. 복도에 문이 여섯. 하나씩 열어 확인하는 일. 척후병의 일이다.<br><br>
    여기 문은 함부로 열면 안 된다. 문 뒤에 뭐가 사는지 모른다. 그리고 한 번 연 문은 닫아도 연 티가 난다. 냄새가 흐르니까.<br>
    여는 순서, 여는 방법, 문 앞에 서는 자리. 전부 정해 놓고 열어야 한다.<br><br>
    여섯 문 중 막사 하나, 그게 오늘 밤의 목표다.`,
    o:[
      { l:'① 문마다 정해진 순서로 — 듣고, 비키고, 연다.', k:'evade', dc:25, cost:{ might:30 }, wake:1,
        ok:`순서를 정했다. 문에 귀 다섯 숨, 경첩 쪽 벽에 몸을 붙이고, 무력 실은 발로 문을 차 열고 바로 물러난다. 문틀 정면에는 아무도 안 선다.<br><br>첫째 문, 빈 창고. 둘째, 무너진 방. 셋째 문에서 귀가 걸렸다. 안에서 긁는 소리. 건너뛰었다.<br>넷째가 성한 격실이었다. 잠금쇠도 안에서 걸린다.<br>다섯 숨, 벽, 차고, 물러서고. 같은 순서 네 번에 막사가 나왔다.<br><br>문 하나하나는 운이지만 순서는 운이 아니다. 순서가 있으면 나쁜 운도 문틀 정면이 아니라 빈 벽을 친다. 오늘 셋째 문의 긁는 소리가 그 증거다.`,
        ng:`셋째 문에서 순서가 깨졌다. 귀 다섯 숨 동안 조용했던 것이다. 조용해서 방심한 발이 문을 찼다.<br><br>안의 것은 조용히 기다리는 놈이었다. 문이 열리자마자 문틀로 쏟아져 나왔다.<br>벽에 붙어 있던 덕에 첫 손은 피했다. 복도가 난장판이 된 채 다들 넷째 문으로 밀려 들어가 잠갔다. 안이 성한 격실인 건 순전히 운이었다. 문 너머에서 밤새 셋째 문의 것이 복도를 오갔다. 조용한 문이 제일 나쁜 문이다. 순서에 한 줄 보탰다. 조용하면 두 배로 기다릴 것.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-14 } },
      { l:'② 문 밑 틈으로 먼저 냄새와 바람을 읽는다.', k:'sense', dc:24,
        ok:`문을 열기 전에 문이 말하게 했다. 문 밑 틈에 코를 대면 방이 숨을 쉰다.<br><br>첫째 문은 먼지 냄새. 빈 방. 둘째는 곰팡이와 물. 천장이 샌 방. 셋째 문 밑에서는 미지근한 바람이 박자를 갖고 나왔다. 숨 쉬는 것이 있는 방.<br>넷째 문은 찬 먼지 냄새에 쇠 냄새. 비었고, 잠금쇠가 성하다는 뜻.<br>넷째만 열었다. 한 번에 막사를 골랐다.<br><br>문은 열기 전에도 읽을 수 있다. 문틈은 방의 콧구멍이다. 여섯 문 중 하나만 연 밤. 연 수가 적을수록 좋은 밤이다.`,
        ng:`문 밑 틈을 읽는 것까지는 좋았다. 셋째 문 틈에 코를 댄 순간, 안쪽에서도 코가 틈에 닿았다.<br><br>문 한 장을 사이에 두고 코와 코가 마주쳤다. 안의 것이 문을 안에서 밀기 시작했다.<br>문이 버티는 동안 다들 넷째 문으로 피했다. 넷째가 성한 방인 게 운이었다. 밤새 셋째 문이 울컥울컥 밀리는 소리를 들었다. 문틈 읽기는 계속하되, 코 대신 막대에 헝겊을 감아 대기로 했다. 콧등이 아직도 서늘하다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-16 } },
      { l:'③ 둘씩 짝지어 세 문을 동시에 맡긴다.', k:'bond', dc:24,
        ok:`혼자 여섯 문은 길다. 길면 밤이 먼저 온다. 둘씩 세 짝으로 나눠 한 문씩 맡겼다.<br><br>여는 법을 먼저 몸으로 보여 줬다. 귀, 벽, 발, 물러서기. 세 짝이 복도 세 문 앞에 서고, 이쪽 손짓 하나에 동시에 열었다.<br>세 문이 한 숨에 열리니 문 뒤에 뭐가 있었어도 서로가 서로의 등을 봐 줄 자리였다. 다행히 다 빈 방.<br>남은 세 문도 같은 식으로. 다섯째가 막사감이었다.<br><br>정찰은 혼자 하는 일이라고 배웠다. 여기서는 가르쳐서 나누는 일이 됐다. 척후가 다섯이 되는 밤. 나쁘지 않다.`,
        ng:`세 문 동시 개방에서 한 짝이 순서를 건너뛰었다. 귀 대기를 생략하고 바로 찬 것이다.<br><br>하필 그 문 뒤에 그것이 있었다. 둘이 감당 못 할 크기가.<br>다섯이 다 그 문으로 몰려가 막대와 어깨로 문을 도로 밀어 닫았다. 안에서 미는 힘에 복도 끝까지 밀릴 뻔했다. 잠금쇠 대신 복도의 캐비닛을 넘어뜨려 괴었다. 그 문만 빼고 남은 문에서 막사를 찾았다. 가르침이 덜 끝난 손에 문을 맡긴 이쪽 책임이다. 다음부터 첫 문은 꼭 같이 연다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
    ] },

  { at:'S1', t:'울림 삼각 — 여왕의 자리',
    x:`여왕이 어디 있는지 알아야 피해 다닌다. 벽의 맥동은 구역 전체에 퍼져서 방향을 안 알려 준다.<br><br>
    척후병의 법으로 풀기로 했다. 세 자리에서 재면 한 점이 나온다.<br>
    복도 세 모퉁이에서 벽에 귀를 대고 맥동의 세기와 빠르기를 쟀다. 숫자 여섯 개.<br><br>
    숫자는 거짓말을 안 한다. 여기서는 숫자만 거짓말을 안 한다.`,
    o:[
      { l:'① 세 측정점의 울림으로 여왕의 자리를 끊어 낸다.', k:'sense', dc:26,
        ok:`세기 셋, 빠르기 셋. 센 쪽이 가깝고 빠른 쪽이 낮다. 숫자를 바닥에 그려 놓고 선 셋을 그었다.<br><br>선이 한 점에서 모였다. 북동쪽 아래층. 큰 배관이 모이던 그 자리.<br>그날부터 이동 계획의 가운데에 그 점이 박혔다. 모든 길이 그 점에서 멀어지는 쪽으로 휘었다.<br>이틀을 다녔는데 여왕 구역 근처에도 안 갔다. 벽의 맥동이 늘 등 뒤에 있었다.<br><br>안 보이는 것도 잴 수 있다. 세 번 재면. 공포는 재지 못한 것의 이름이다. 잰 다음부터 여왕은 공포가 아니라 지도 위의 점 하나다. 멀리 둘 점.`,
        ng:`삼각은 맞았다. 점도 나왔다. 문제는 점이 움직였다는 것이다.<br><br>다음 날 같은 세 자리에서 다시 재니 점이 서쪽으로 옮겨 있었다. 여왕이 이동한다. 알을 옮기는 철인지도 모른다.<br>어제의 점을 믿고 짠 길이 오늘의 점과 겹쳤다. 복도 하나를 사이에 두고 벽 전체가 뛰는 구간을 지나게 됐다. 숨도 제대로 못 쉬고 그 구간을 건넜다. 잰 것은 과거다. 오늘의 지도는 오늘 재야 한다. 삼각 측정이 아침 일과에 들어갔다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-18 } },
      { l:'② 잰 숫자에 맞춰 일행의 이동 시간표를 짠다.', k:'steady', dc:24,
        ok:`자리만으로는 반쪽이다. 맥동은 하루 중에도 세졌다 약해졌다 한다. 재 보니 박자가 있었다. 느려지는 때가 하루 두 번.<br><br>느려지는 때 여왕 쪽 것들의 움직임도 같이 준다. 자는 것인지 조는 것인지.<br>이동을 그 두 번에 몰았다. 나머지 시간은 격실에서 쉬고, 맥동이 처지면 걷고.<br>구역 절반을 그 시간표로 건넜다. 마주친 것이 평소의 반의반이었다.<br><br>지도에 시간을 얹으면 길이 두 배로 안전해진다. 어디로, 에 언제, 를 더하는 것. 척후 보고의 마지막 줄은 늘 시간이어야 한다.`,
        ng:`시간표는 좋았는데 둘째 날 맥동이 박자를 깼다. 느려질 시간에 갑자기 빨라졌다.<br><br>구역 전체가 깨어났다. 복도마다 그것들이 쏟아져 나왔다. 무슨 일인지는 모른다. 여왕의 사정은 여왕만 안다.<br>이동 중이던 다섯이 복도 한가운데서 그 물결을 만났다. 가까운 격실로 뛰어들어 문을 걸고 한나절을 보냈다. 시간표는 유지하되 맨 윗줄에 한 줄 적었다. 박자가 깨지면 그 즉시 제자리 은신. 시간표보다 귀가 먼저다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'S1', t:'잡음 신호 — 수신자 불명',
    x:`관제실 잔해에서 무전기가 하나 살아 있었다. 잡음뿐이지만 버튼을 누르면 다른 무전기에서 소리가 난다.<br><br>
    시설에 흩어진 무전기들. 짧게 세 번 누르면 세 번 울린다. 신호로 쓸 수 있다.<br>
    시험 삼아 세 번 눌렀다. 잠시 뒤, 어디선가 세 번이 돌아왔다.<br><br>
    이 시설에 다른 생존자가 있거나. 아니면 버튼 누르는 법을 아는 뭔가가 있거나.`,
    o:[
      { l:'① 돌아온 신호의 발신지를 찾아 움직인다.', k:'evade', dc:26,
        doom:{ title:'잡음 신호', what:'무전기 소리 쪽 어둠으로 끌려 들어갑니다', dc:20, sec:38,
          text:`신호를 주고받으며 발신지를 좁혔다. 동쪽 창고 구역. 다가갈수록 응답이 빨라졌다. 반가워하는 것처럼.<br><br>창고 문틈으로 무전기가 보였다. 바닥에 놓여 있다. 그 옆에 사람은 없다.<br>무전기 버튼 위에 가늘고 마디 많은 손가락이 하나 얹혀 있다. 어둠에서 뻗어 나온.<br>함정인 걸 안 순간 등 뒤의 문이 닫혔다. 어둠이 움직이고, 손가락의 임자가 이쪽 발목을 감아 어둠 안쪽으로 끌었다. 무전기가 바닥에 뒹굴며 잡음을 토한다.<br>그 잡음에 대고 소리쳤다. 오지 마라. 동쪽은 아니다.<br><br>복도 저쪽에서 동료들의 무전기가 이쪽 비명을 세 번, 울렸다.`,
          dieText:`버튼 누르는 법만 아는 게 아니었다.<br><br>신호가 사냥감을 데려온다는 것까지 아는 놈이었다. 어디서 배웠는지는 뻔하다. 앞서 신호를 보낸 사람들에게서.<br>그날 밤에도 시설 어딘가에서 세 번 울림이 돌았다. 대답하는 무전기는 더 없었다.`,
        },
        ok:`바로 찾아가지 않았다. 신호에 셈을 걸었다. 두 번, 다섯 번, 한 번. 수를 불규칙하게 보냈다.<br><br>사람이라면 수를 따라 하거나 제 수를 보탠다. 돌아온 응답은 늘 세 번이었다. 몇 번을 보내도 세 번.<br>세 번밖에 모르는 것. 흉내지 대화가 아니다. 사람이 아니다.<br>발신지 동쪽 구역을 지도에서 지웠다. 가지 말아야 할 곳 목록 맨 위에.<br><br>신호는 내용보다 변화가 말한다. 변하지 않는 응답은 벽에서 돌아오는 메아리다. 메아리를 찾아가는 척후는 없다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 신호 체계를 일행끼리만 아는 수로 다시 짠다.', k:'bond', dc:25, wake:1,
        ok:`무전기 셋을 꺼내 일행에게 나눴다. 그리고 체계를 새로 짰다. 수가 아니라 박자로.<br><br>길게 하나 짧게 둘은 집결. 짧게 넷은 은신. 길게만 셋은 퇴각. 박자는 숫자보다 흉내가 어렵다. 세 번 울림밖에 모르는 저쪽한테는 특히.<br>둘씩 흩어져 정찰하는 이틀 동안 박자 신호가 스무 번을 오갔다. 저쪽의 세 번 울림이 몇 번 끼어들었지만 박자가 없어 바로 걸러졌다.<br><br>신호는 보내는 법이 아니라 가려 듣는 법까지가 신호다. 가짜가 섞이는 땅에서는 더더욱. 일행만 아는 박자 하나가 시설 전체의 잡음을 이겼다.`,
        ng:`새 체계를 짜고 반나절 만에 문제가 생겼다. 저쪽이 박자를 배우기 시작한 것이다.<br><br>길게 하나 짧게 둘. 집결 신호가 왔는데 보낸 사람이 없었다.<br>하마터면 빈 집결지로 모일 뻔했다. 둘이 가다가 박자 끝이 미묘하게 늘어지는 걸 알아채고 돌아섰다. 사람 손가락과 다른 손가락은 버튼 떼는 순간이 다르다.<br>체계를 다시 짰다. 이번에는 박자에 응답 문답까지 얹었다. 묻는 박자에 맞는 답 박자. 배우는 놈과의 수 싸움은 끝이 없다. 끝이 없다는 걸 아는 것부터가 수다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'S2', t:'거꾸로 정찰 — 무리의 척후를 본다',
    x:`울타리 밖에서 사흘째, 무리가 울타리를 시험한다. 밤마다 한 놈이 와서 철사를 밀어 보고 돌아간다.<br><br>
    척후병은 그 한 놈을 알아봤다. 늘 같은 놈이다. 무리의 척후다.<br>
    저놈이 미는 자리, 미는 시간, 돌아가는 길. 그걸 다 적으면 무리의 계획이 그려진다.<br>
    저쪽이 이쪽 울타리를 정찰하는 동안, 이쪽은 저쪽 정찰을 정찰한다.<br><br>
    정찰 대 정찰. 먼저 다 읽는 쪽이 이긴다.`,
    o:[
      { l:'① 사흘치 기록으로 무리가 뚫을 밤과 자리를 집어낸다.', k:'gaze', dc:26, wake:1,
        ok:`기록을 폈다. 미는 자리가 사흘 내내 동쪽으로 한 칸씩 옮겨 왔다. 삭은 말뚝 쪽으로.<br><br>미는 시간은 매일 반 식경씩 늦어졌다. 달이 늦게 뜨는 만큼. 어둠이 제일 깊은 때를 고르는 것이다.<br>그러면 답은 하나다. 나흘째 밤, 삭은 말뚝, 달 뜨기 직전.<br>그 밤 그 자리에 불을 피워 뒀다. 기름 먹인 장작으로 크게.<br>무리가 왔다가 불 앞에서 멈췄다. 계획이 깨진 무리는 그냥 짐승 떼다. 서성이다 돌아갔다.<br><br>적의 척후를 읽으면 적의 내일을 읽는다. 사흘 기록이 하룻밤 불 한 무더기로 바뀌었다. 싸움 없이 이긴 밤. 척후가 이기는 방식이다.`,
        ng:`사흘치 기록은 정확했다. 문제는 저쪽 척후가 나흘째에 이쪽을 알아챘다는 것이다.<br><br>기록하느라 사흘 밤 같은 수풀에 엎드린 냄새가 쌓여 있었다.<br>나흘째 밤, 저쪽 척후가 울타리 대신 이쪽 수풀로 똑바로 왔다. 구르며 빠져나와 울타리 안으로 넘어 들어왔다. 철사에 허벅지가 길게 긁혔다. 무리는 그날 밤 울타리 세 군데를 동시에 밀었다. 이쪽 기록을 역으로 읽힌 것이다. 밤새 뛰어다니며 막았다. 정찰 대 정찰은 자리를 옮겨 가며 하는 것. 사흘 같은 수풀은 세 밤 치 실수였다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 저쪽 척후가 돌아가는 길목에 헛 정보를 심는다.', k:'evade', dc:25,
        ok:`저놈이 밤마다 돌아가는 길이 정해져 있다. 그 길목에 그림을 그려 줬다.<br><br>울타리 서쪽 끝에 사람 발자국을 잔뜩 찍고, 모닥불 자리를 만들고, 고기 기름을 바위에 발랐다. 서쪽에 숙영지가 있다는 헛 정보.<br>저쪽 척후가 그걸 다 읽고 돌아갔다.<br>다음 날 밤 무리가 서쪽 끝을 쳤다. 빈 서쪽을. 진짜 숙영지는 동쪽 바위 틈에서 그 소리를 들으며 식은 저녁을 먹었다.<br><br>적의 눈을 가리는 것보다 좋은 것은 적의 눈에 보여 줄 것을 이쪽이 고르는 것이다. 읽는 놈한테는 읽을거리를 주면 된다.`,
        ng:`헛 정보까지는 좋았다. 너무 정성을 들인 게 탈이었다.<br><br>발자국이 너무 많고 너무 깨끗했다. 다섯 명 치고는 백 걸음 치 발자국. 저쪽 척후가 그 어긋남을 읽었다.<br>헛 정보가 거꾸로 말해 줬다. 이것은 가짜다. 가짜를 만들 만큼 겁먹었다. 그리고 가짜의 반대쪽에 진짜가 있다.<br>무리가 동쪽을 쳤다. 바위 틈 숙영지 코앞까지. 밤새 바위 뒤에서 숨죽이고 버텼다. 거짓말은 양이 아니라 아귀다. 다섯 명이면 다섯 명 치만큼만 거짓말할 것.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-18 } }
    ] },

  { at:'S2', t:'수심 재기 — 장대 끝의 대답',
    x:`잠긴 양치 지대를 건너는 길, 척후병이 장대를 들고 앞장선다. 한 걸음마다 장대로 바닥을 짚어 수심을 잰다.<br><br>
    무릎이면 가고, 허리면 돌아가고, 장대가 다 들어가면 그쪽은 길이 아니다.<br>
    문제는 이 물에서는 장대가 재는 게 수심만이 아니라는 것이다.<br>
    바닥을 짚는 느낌이 가끔 다르다. 진흙도 돌도 아닌, 무른 것. 무르고 큰 것.<br><br>
    그런 데를 짚으면 장대 끝에서 대답이 온다. 천천히, 밀어내는 대답이.`,
    o:[
      { l:'① 장대 끝 감촉으로 길과 등을 가려 디딘다.', k:'evade', dc:26,
        doom:{ title:'수심 재기', what:'물 밑으로 끌려 들어갑니다', dc:20, sec:35,
          text:`진흙, 돌, 진흙, 뿌리. 장대 끝이 바닥을 읽으며 반을 건넜다.<br><br>다음 짚음이 무른 것에 닿았다. 밀어내는 대답 대신, 이번에는 장대를 잡아당기는 대답이 왔다.<br>장대를 놓았어야 했다. 반 박자 늦었다. 장대째 물속으로 당겨 들어갔다.<br>물이 얼굴 위에서 닫히고, 무른 것이 몸을 감는다. 크다. 장대로 짚던 등이 이렇게 길 줄은 밑에 들어와서야 알았다.<br>잡은 장대의 반대 끝이 아직 수면 위에 떠 있을 것이다.<br><br>그 장대 끝을 동료들이 잡고 당기는 진동이 물속까지 전해진다. 줄다리기다. 이쪽 몸이 줄이다.`,
          dieText:`장대는 정직했다. 무른 것을 무르다고 말해 줬다.<br><br>정직한 대답을 들은 다음이 문제였다. 무른 것 옆에도 무른 것이 있었다.<br>장대는 사흘 뒤 물가에 떠밀려 왔다. 끝에서 세 뼘 위까지 이빨 자국이 나 있었다. 수심 대신 그걸 쟀다.`,
        },
        ok:`감촉의 사전을 만들며 갔다. 진흙은 푹, 돌은 톡, 뿌리는 드르륵. 그리고 무른 것은 꾹, 하고 되민다.<br><br>꾹, 이 오면 그 자리를 크게 돌았다. 세 번 돌았다. 세 번 다 돌고 나서 물결이 그 자리에서 일었다. 돈 값이 있었다.<br>건너편 둔덕에 닿아 장대를 세워 놨다. 다음에 건널 누군가를 위해.<br><br>장대 하나로 물 밑 지도를 그린 셈이다. 눈이 못 가는 데는 끝이 간다. 끝의 말을 알아듣는 게 척후의 귀다. 오늘 그 사전에 단어가 하나 늘었다. 꾹, 은 돌아가라는 말이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 물빛과 물풀의 결로 깊이를 눈으로 먼저 거른다.', k:'sense', dc:25,
        ok:`장대를 대기 전에 눈으로 걸렀다. 얕은 데는 물빛이 바닥색이고, 깊은 데는 하늘색이다. 물풀이 수면까지 닿은 데는 무릎, 끝만 어른대면 허리.<br><br>눈으로 길을 반쯤 그려 놓고 장대는 확인용으로만 썼다. 짚는 횟수가 반으로 줄었다. 물 밑에 말 거는 횟수가 반으로 줄었다는 뜻이다.<br>무른 것 자리는 물풀이 없다. 그것도 눈이 먼저 알려 줬다. 풀이 안 자라는 자리에는 이유가 있다.<br><br>장대 끝에 오기 전에 눈에서 거르는 것. 정찰의 순서는 멀리서부터다. 눈, 귀, 끝, 발. 그 순서가 뒤집히는 날이 다치는 날이다.`,
        ng:`물빛 읽기는 맑은 물에서 통하는 법이다. 바람이 불어 수면이 흐려지자 눈이 소용없어졌다.<br><br>눈을 믿고 줄였던 장대질을 도로 늘리기 전에, 한 걸음이 먼저 깊은 데를 밟았다.<br>가슴까지 빠졌다. 허우적대는 물결이 사방으로 퍼졌다. 멀리서 물이 부푸는 게 보였다. 동료들이 장대를 뻗어 끌어냈고, 다들 가까운 둔덕으로 정신없이 올라갔다. 부푼 물이 둔덕 밑까지 왔다가 돌아갔다. 눈은 날씨가 좋을 때의 도구다. 날씨까지가 정찰이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'S2', t:'후미 — 자국을 지우며 걷는 자',
    x:`오늘은 이동이 길다. 숙영지를 옮긴다. 무리가 뒤를 캐지 못하게, 맨 뒤에서 흔적을 지우는 사람이 필요하다.<br><br>
    척후병이 후미로 돌았다. 앞서 보는 눈이 오늘은 뒤를 닦는 손이 된다.<br>
    발자국을 쓸고, 꺾인 풀을 세우고, 떨어진 것을 줍고. 그리고 가장 어려운 것. 냄새.<br><br>
    다섯 사람이 지나간 길에서 다섯 사람을 지우는 일. 앞서가는 것보다 어렵다.`,
    o:[
      { l:'① 무력을 아껴 쓰며 흔적 셋을 차례로 지운다.', k:'evade', dc:25, cost:{ might:32 },
        ok:`자국, 풀, 냄새. 순서대로 지웠다.<br><br>자국은 가지 빗자루로 결을 따라 쓸고, 풀은 한 포기씩 세우고, 냄새는 물가 길로 꺾어 물에 반쯤 잠겨 걷는 구간을 만들어 끊었다.<br>무력은 뜀걸음에만 아껴 썼다. 지우는 손은 느리고 본대는 빠르니, 사이가 벌어질 때마다 한 번에 따라붙었다.<br>해 질 녘 무리가 옛 숙영지에 들이닥치는 소리를 멀리서 들었다. 그리고 거기서 끝났다. 길이 지워진 사냥은 거기가 끝이다.<br><br>앞을 보는 재주로 뒤를 지웠다. 척후는 길을 내는 자이기도, 길을 없애는 자이기도 하다. 오늘은 없애는 날이었다.`,
        ng:`자국과 풀까지는 지웠다. 냄새에서 하나를 놓쳤다. 다친 동료의 피 한 방울.<br><br>옷에 번진 줄만 알았던 피가 길에 한 방울 떨어져 있던 모양이다.<br>무리가 그 한 방울에서 다시 길을 잡았다. 밤 숙영지 둘레에서 코 훌쩍이는 소리가 났다. 밤새 불을 키우고 교대로 섰다. 새벽에야 물러갔다. 피는 천으로 겹겹이 싸매도 길에 말을 흘린다. 다친 사람은 후미가 아니라 가운데. 물가 쪽 바람 자리. 수칙이 둘 늘었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 지우는 대신 가짜 길을 하나 더 그린다.', k:'steady', dc:24,
        ok:`다섯 사람 흔적을 완전히 지우는 건 반나절 일이다. 반나절이 없다.<br><br>지우는 대신 늘렸다. 갈림에서 진짜 길의 흔적은 대충만 지우고, 가짜 길에 더 진한 흔적을 그렸다. 발자국 몇 벌, 꺾인 가지, 눌린 풀.<br>쫓는 쪽은 둘 중 진한 쪽을 고른다. 흐린 진짜와 진한 가짜. 사냥은 늘 진한 쪽으로 간다.<br>가짜 길 끝은 바위 지대에 물렸다. 바위에서 흔적은 저절로 끝난다. 막다른 수수께끼.<br><br>무리는 바위 지대를 밤새 맴돌았다고 한다. 지울 수 없으면 고르게 하라. 고르는 것은 저쪽이지만 패는 이쪽이 돌린다.`,
        ng:`가짜 길을 그리다 시간을 너무 썼다. 본대와의 사이가 벌어질 대로 벌어졌다.<br><br>혼자 어두워지는 숲에 남았다. 무리의 선두가 가짜 길이 아니라 이쪽 작업 소리를 듣고 왔다.<br>그리다 만 가짜 길로 이쪽이 도망치는 꼴이 됐다. 그린 길이라 끝이 막다른 바위인 걸 이쪽만 안다. 바위를 타고 넘어 밤길을 돌아 본대에 합류했다. 손이 긁히고 밤이 길었다. 가짜 길은 먼저 그려 놓고 이동하는 것. 이동하면서 그리는 게 아니라. 순서 하나가 하룻밤이었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'S2', t:'큰 것의 순찰 — 시계가 되는 발소리',
    x:`높은 바위에 엎드려 꼬박 하루, 큰 것을 지켜봤다. 멀리서. 아주 멀리서.<br><br>
    큰 것은 정원을 돈다. 물가를 따라, 정해진 길로. 한 바퀴에 한나절. 물 마시는 데서 한 식경, 양치 숲에서 반 식경.<br>
    발소리가 시계다. 땅울림이 멀어지고 가까워지는 것으로 정원 전체가 시간을 안다. 작은 것들도 그 시계에 맞춰 숨고 나온다.<br><br>
    이쪽도 그 시계에 맞추면 된다. 시계태엽 눈금을 적는 데 하루를 썼을 뿐이다.`,
    o:[
      { l:'① 순찰 시계에 맞춰 일행의 이동 창을 짠다.', k:'sense', dc:25, wake:1,
        ok:`울림이 멀어지는 반나절이 이동 창이다. 큰 것이 정원 북쪽을 도는 동안 남쪽을 건너고, 남쪽으로 내려오면 둔덕에 올라 쉰다.<br><br>작은 것들도 같은 시계로 움직이니, 큰 것이 가까울 때는 오히려 무리도 숨는다. 그 틈도 창에 넣었다. 큰 울림이 지나간 직후의 반 식경. 정원에서 제일 조용한 시간.<br>이틀을 그 시계로 움직였다. 큰 것과도 무리와도 한 번을 안 마주쳤다.<br><br>지형 지도 위에 시간 지도를 포갰다. 포개진 두 장이 진짜 지도다. 발소리가 시계가 되는 땅에서는, 귀가 시계공이다.`,
        ng:`시계는 정확했다. 사흘째 아침까지는.<br><br>사흘째, 큰 것이 길을 바꿨다. 물가에 다른 큰 짐승의 사체가 떠밀려 온 탓이다. 시계가 멈추고 정원의 모든 박자가 깨졌다.<br>이동 창 한가운데서 울림이 정면으로 다가왔다. 다섯이 바위 틈에 짐짝처럼 끼어 큰 것이 지나가는 걸 발밑으로 느꼈다. 바위가 흔들리고 이가 부딪혔다.<br>시계는 살아 있는 것이다. 살아 있는 것은 멈추기도 한다. 시계를 믿되 귀는 시계 밖에 둘 것. 눈금 옆에 그렇게 적었다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-16 } },
      { l:'② 큰 것이 비운 물가에서 보급까지 챙긴다.', k:'evade', dc:25,
        ok:`순찰 창은 이동만 하라고 있는 게 아니다. 큰 것이 북쪽일 때 남쪽 물가는 정원에서 제일 안전한 곳이 된다.<br><br>그 반나절에 물을 채우고, 물가의 민물고기를 잡고, 둔덕의 산나물을 뜯었다.<br>보초 하나는 울림 담당. 울림이 커지기 시작하면 호각 한 번. 두 번째 호각 전에 다 물러나기.<br>호각 한 번에 걷고, 두 번 울기 전에 둔덕으로 돌아왔다. 큰 것이 물가에 닿았을 때 거기엔 사람 냄새 대신 물 냄새만 남아 있었다.<br><br>정찰은 피해 다니는 기술만이 아니다. 비는 때와 비는 데를 아는 기술이다. 그 둘이 겹치는 자리에서 보급이 나온다.`,
        win:{ exp:20, dream:2, item:'민물고기' }, lose:{ mind:-16, spirit:-16 },
        ng:`보급에 욕심을 냈다. 민물고기가 잘 잡혀서 호각 한 번을 그물 한 번만 더, 로 넘겼다.<br><br>두 번째 호각이 울렸을 때는 이미 땅이 울리고 있었다.<br>그물째 버리고 뛰었다. 큰 것이 물가에 닿는 물보라를 등 뒤에 들으며 둔덕을 굴러 올랐다. 잡은 고기 반을 물가에 쏟고 왔다. 큰 것한테 상을 차려 준 셈이다. 욕심은 시계보다 빠르고 다리보다 느리다. 호각 소리에 토 달지 않기. 보급 수칙 첫 줄이 됐다.` }
    ] },

  { at:'S2', t:'메아리 재기 — 승강기 찾기',
    x:`승강기가 있다는 건 안다. 정원 어느 벽인지가 문제다. 수풀과 안개가 시야를 막는다.<br><br>
    척후병은 눈이 막히면 귀로 잰다. 승강기 통로는 돌벽에 뚫린 빈 수직 공간. 소리가 거기 닿으면 다른 데와 다르게 돌아온다.<br>
    높은 바위에서 손뼉 한 번. 메아리들이 돌아온다. 숲의 메아리, 벽의 메아리.<br><br>
    그중 하나, 속이 빈 울림. 북북서.`,
    o:[
      { l:'① 세 자리에서 소리를 쏘아 통로 위치를 교차시킨다.', k:'sense', dc:25,
        ok:`한 자리 메아리로는 방향만 나온다. 거리도 얻으려면 자리를 옮겨 다시 재야 한다.<br><br>바위 셋을 골라 각각 손뼉을 쏘고 빈 울림의 방향을 그었다. 선 셋이 정원 북북서 벽 한 점에서 겹쳤다.<br>거리까지 나오니 길도 나왔다. 늪을 피해 둔덕 능선으로 도는 길.<br>이틀 뒤 그 점에서 승강기 통로를 찾았다. 수풀에 완전히 덮여 눈으로는 열 걸음 앞에서도 안 보이는 입구였다.<br><br>귀가 그린 지도가 눈이 그린 지도보다 정확한 날이 있다. 안개 낀 정원에서는 거의 매일이 그런 날이다.`,
        ng:`둘째 자리에서 손뼉을 쏘는데, 메아리 말고 다른 대답이 왔다.<br><br>무리의 울음. 손뼉 소리의 자리를 묻는 울음이었다.<br>셋째 측정을 접고 자리를 떴다. 방향만 가진 채 북북서로 더듬어 갔다. 거리를 모르니 벽을 따라 한나절을 더 뒤졌다. 늪 가장자리로 잘못 내려갔다가 물속 기척에 쫓겨 올라오기도 했다.<br>결국 찾긴 했다. 소리로 재는 자는 소리로 재어진다. 쏘는 소리는 짧게, 자리는 바로 옮기기. 측량 수칙이 생겼다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-18 } },
      { l:'② 잰 방향으로 먼저 혼자 다녀와 길을 확정한다.', k:'steady', dc:25, wake:1,
        ok:`방향은 나왔지만 다섯이 다 움직이기엔 설익었다. 혼자 가볍게 다녀오기로 했다.<br><br>짐을 다 벗고 물과 칼만 챙겼다. 가볍게, 빠르게, 흔적 없이. 혼자면 숨을 자리도 한 몸 치면 된다.<br>반나절 만에 통로 입구를 확인하고 길목 셋에 표식을 걸고 돌아왔다.<br>다음 날 다섯이 그 길을 한 번에 갔다. 헤맴 없이, 소리 없이.<br><br>본대를 세워 두고 혼자 먼저 걷는 길. 척후의 처음이자 끝이다. 다만 이제는 돌아와 전하는 것까지가 길이라는 걸 안다. 혼자 아는 길은 길이 아니다. 전해진 길이 길이다.`,
        ng:`혼자 가는 길은 빨랐다. 문제는 돌아오는 길이었다.<br><br>통로를 확인하고 돌아서는데 무리의 외곽 하나와 정면으로 마주쳤다. 혼자인 사람. 저쪽이 제일 좋아하는 그림이다.<br>칼 한 자루로 버티며 물러나 늪에 뛰어들었다. 가슴까지 오는 물을 가르며 둔덕 두 개를 돌아 귀환했다. 다 젖고 반쯤 얼어서. 길은 확정했다. 혼자 정찰의 값도 확정했다. 다음부터 확인 정찰은 둘이다. 혼자의 빠름보다 둘의 등이 크다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-16 } }
    ] },

  { at:'S2', t:'별 없는 밤 — 숲 지붕 아래의 방위',
    x:`밤 이동이 정해졌다. 낮에는 무리가 능선을 다 본다. 밤뿐이다.<br><br>
    문제는 양치 숲의 지붕이다. 잎이 하늘을 덮어 별이 안 보인다. 별 없는 밤 숲에서 방향은 반 시진이면 녹는다.<br>
    척후병이 방위를 잡는다. 별 없이, 불빛 없이, 소리도 없이.<br><br>
    남은 것은 몸과 숲 자체다. 숲은 사실 방위투성이다. 읽을 줄만 알면.`,
    o:[
      { l:'① 무력으로 선두를 지키며 숲의 결로 방위를 잇는다.', k:'evade', dc:26, cost:{ might:34 },
        ok:`읽을 것을 정했다. 바람은 밤새 북에서 온다. 뺨의 찬 쪽이 북. 양치 줄기의 이끼는 물가 쪽, 그러니까 서쪽이 두껍다. 큰 것의 울림은 늘 남쪽 물가에서 온다.<br><br>뺨과 손끝과 발바닥. 세 방위를 반 시진마다 맞춰 보며 선두를 걸었다. 어긋나면 멈추고 다시 잡았다.<br>무력은 선두의 몫에 썼다. 덤불을 소리 없이 가르고, 쓰러진 줄기를 넘겨 받고.<br>새벽, 숲을 나온 자리가 목표 둔덕에서 백 걸음 안이었다.<br><br>별이 없으면 땅이 별이다. 바람, 이끼, 울림. 셋이 한 방향을 말하면 그게 북이다. 밤 숲이 교본 한 권이었다.`,
        ng:`바람이 자정 넘어 죽었다. 방위 셋 중 하나가 꺼졌다.<br><br>남은 둘로 갔는데 이끼가 문제였다. 늪 가까운 구간은 사방이 물가라 이끼가 사방으로 두꺼웠다.<br>반 시진을 돈 자리로 되돌아왔다. 제자리 원. 밤 숲에서 제일 무서운 도형이다.<br>결국 멈춰 서서 큰 것의 울림만 기다렸다. 반 식경 뒤 남쪽이 다시 잡혔고, 그 한 방위로만 더듬어 나왔다. 새벽이 반나절 늦은 기분이었다. 방위가 꺼질 때를 대비해 넷째 방위를 마련할 것. 밤의 숙제가 생겼다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 다섯을 끈으로 잇고 걸음 수와 꺾임만으로 간다.', k:'bond', dc:25,
        ok:`밤 숲에서 흩어지면 그걸로 끝이다. 허리끈으로 다섯을 이었다.<br><br>그리고 길을 수로 바꿨다. 북으로 사백 걸음, 왼쪽으로 꺾어 이백, 다시 북으로 육백. 낮에 봐 둔 지형을 걸음 수 명령으로 번역해 둔 것이다.<br>맨 앞에서 수를 세고, 꺾임마다 끈을 두 번 당겨 알렸다. 말 한마디 없는 행군.<br>수가 끝난 자리에서 숲이 끝났다.<br><br>눈이 없는 밤에는 몸이 자이고 끈이 문장이다. 다섯 몸이 한 자로 움직이면 밤 숲도 잴 수 있는 땅이 된다. 아무도 밤새 서로의 얼굴을 못 봤지만, 아무도 혼자가 아니었다.`,
        ng:`걸음 수 행군이 중반까지는 맞았다. 문제는 쓰러진 거목이었다. 낮 지형에 없던, 어젯밤에 쓰러진 나무.<br><br>돌아가느라 걸음 수가 엉켰다. 몇 걸음을 돌았는지 어둠 속에서 셈이 흩어졌다.<br>수를 잃은 채 반 시진을 더 갔다. 숲이 끝나지 않았다. 멈추고, 끈으로 둥글게 모여 앉아 새벽을 기다렸다. 교대로 졸았다. 먼동이 트자 목표 둔덕이 왼쪽으로 삼백 걸음 비껴 있었다. 수는 장애물을 만나면 깨진다. 꺾임마다 수를 다시 묶는 매듭 수가 필요하다. 끈에도, 셈에도.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'S2', t:'마지막 백 걸음 — 승강기 앞 정찰',
    x:`승강기 입구까지 백 걸음. 다 왔다. 다 왔다는 생각이 제일 위험하다는 걸 척후병은 안다.<br><br>
    입구 둘레가 너무 조용하다. 새도 벌레도 없다. 조용한 자리는 비어서 조용한 게 아니다. 뭔가 있어서 조용한 것이다.<br>
    일행을 수풀에 세워 두고 마지막 백 걸음을 먼저 본다.<br><br>
    여기까지 와서 입구에서 당하면, 그보다 나쁜 보고는 없다.`,
    o:[
      { l:'① 혼자 반원을 그리며 입구 둘레를 먼저 쓸어 본다.', k:'evade', dc:26,
        doom:{ title:'마지막 백 걸음', what:'입구 옆 수풀로 끌려 들어갑니다', dc:20, sec:36,
          text:`반원의 반을 돌았을 때 알았다. 조용함의 임자가 어디 있는지.<br><br>입구 바로 옆 수풀. 승강기를 아는 놈이다. 사람들이 결국 여기로 온다는 걸 아는 놈. 길목이 아니라 종점에 자리 잡은 놈.<br>알아챈 것과 피하는 것 사이에 반 걸음이 모자랐다.<br>수풀이 터지듯 열리고, 몸이 옆으로 쓸려 들어갔다. 입구의 돌벽이 시야에서 미끄러져 사라진다. 수풀 속은 뼈 무더기다. 여기까지 온 사람들의.<br><br>수풀 밖에서 일행이 호각을 불고 있다. 집결 신호. 이쪽을 부르는 게 아니라 그것을 흩뜨리려는 긴 호각이다.`,
          dieText:`다 왔다는 생각이 제일 위험하다. 알고 있었다.<br><br>알면서도 백 걸음이 아흔아홉 걸음으로 느껴졌다. 그 한 걸음 차이에 그놈이 산다.<br>일행은 사흘을 돌아 다른 입구를 찾았다. 승강기 앞 수풀에는 표식이 하나 걸렸다. 이 자리의 임자를 알리는, 이쪽 조의 마지막 표식이.`,
        },
        ok:`반원을 돌며 쓸었다. 눈이 아니라 어긋남을 찾는 정찰. 조용한 데서 더 조용한 데. 수풀에서 유독 벌레 소리가 끊긴 자리.<br><br>입구 왼쪽 수풀. 거기만 소리가 비어 있다.<br>다가가지 않았다. 멀찍이 돌아 둔덕 위에서 내려다봤다. 수풀 속에 웅크린 등이 보였다. 기다리는 등.<br>일행에게 수신호로 길을 그려 줬다. 오른쪽 바위 기슭으로 크게 돌아 입구까지. 왼쪽 수풀과는 끝까지 백 걸음을 유지하며.<br>다섯이 승강기에 탔다. 왼쪽 수풀은 끝까지 움직이지 않았다. 기다림이 특기인 놈에게는 안 오는 게 답이다.<br><br>마지막 백 걸음을 정찰한 조와 안 한 조. 그 차이가 이 정원 바닥의 뼈와 승강기 안의 다섯이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 미끼 짐을 입구 쪽에 던져 조용함을 시험한다.', k:'hide', dc:25,
        ok:`빈 배낭에 돌을 채우고 고기 기름 몇 방울을 발랐다. 수풀에 숨어 입구 쪽으로 멀리 던졌다.<br><br>배낭이 구르는 소리. 그리고 입구 왼쪽 수풀이 미끄러지듯 움직였다. 조용함의 임자가 배낭을 덮쳤다.<br>크기와 빠르기를 눈에 담았다. 정면은 안 될 크기. 하지만 덮친 뒤 제자리로 돌아가는 데 한참 걸리는 몸이기도 했다.<br>그 한참 동안 다섯이 오른쪽으로 돌아 입구에 들어갔다.<br><br>조용한 자리는 소리를 던져 보면 대답한다. 배낭 하나와 돌 몇 개. 정찰 도구치고는 싸고, 알아낸 것치고는 비쌌다. 이런 거래만 하며 살고 싶다.`,
        ng:`미끼는 통했다. 통한 게 문제였다. 배낭을 덮친 그것이 돌만 든 배낭에 속은 걸 바로 알았다.<br><br>그리고 던져진 방향을 거슬러 봤다. 던진 팔이 있는 수풀을.<br>수풀째 덮쳐 왔다. 다섯이 사방으로 흩어졌다. 흩어지면서도 입구와 반대쪽으로. 입구를 들키면 안 되니까.<br>반나절을 돌아 다시 모였고, 그것이 제자리로 돌아간 밤에야 입구로 들어갔다. 미끼는 거리를 두 배로 잡고 던질 것. 던진 자리와 숨은 자리는 다른 방향일 것. 수칙이 또 늘었다. 수칙은 늘 피 맛을 보고서야 는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] }
]);
